if CHECKER_PLUGIN and hasattr(CHECKER_PLUGIN, "check_new_categories"):
    _checker_actions.append("Check for New Categories")
if CHECKER_PLUGIN and hasattr(CHECKER_PLUGIN, "check_curated_categories"):
    _checker_actions.append("Verify Curated Categories")
if CHECKER_PLUGIN and hasattr(CHECKER_PLUGIN, "check_new_publications"):
    _checker_actions.append("Check for New Publications")
if CHECKER_PLUGIN and (hasattr(CHECKER_PLUGIN, "check_new_categories")
                        or hasattr(CHECKER_PLUGIN, "check_new_publications")):
    _checker_actions.append("Check Reminder")
STORAGE_ACTIONS[0:0] = _checker_actions


def flatten_toc(entries, out=None):
    if out is None:
        out = []
    for e in entries:
        out.append(e)
        flatten_toc(e.children, out)
    return out


class App:
    def __init__(self, renderer, window=None):
        self.renderer = renderer
        # v26.07.20.27: window handle, needed ONLY for the post-video
        # window-manager nudge (SDL_RaiseWindow/SDL_ShowWindow) below --
        # see that code's own comment for why. None is a safe default
        # (the nudge is skipped entirely if this isn't provided) so this
        # doesn't risk anything for any other caller/test harness that
        # constructs App() without a real window.
        self.window = window
        self.fonts = FontManager()
        load_custom_themes()
        # v26.07.17.13 REAL BUG FIX (Kaleb caught it: "Default theme,
        # no changes"): this used to load NIGHT_MODE_ENABLED further
        # down in __init__, AFTER this boot apply_theme() call already
        # ran -- so a Night Mode setting persisted ON from a previous
        # session had no effect on the very first theme drawn at
        # launch (only a manual re-toggle within that session would
        # apply it). Moved the load up here, before the only apply_theme()
        # call that happens before it's set anywhere in this file.
        globals()["NIGHT_MODE_ENABLED"] = load_settings().get("night_mode_enabled", False)
        # v26.07.17.15: IMAGE_DIM_LEVEL loaded here too (same reasoning
        # as NIGHT_MODE_ENABLED above) -- it now feeds the color-shift
        # strength as well as the image overlay, so it needs to be set
        # before this same boot apply_theme() call, not after.
        globals()["IMAGE_DIM_LEVEL"] = load_settings().get("image_dim_level", 0)
        apply_theme(load_settings().get("theme_index", 0))
        self.screen = SCREEN_LIBRARY
        self.pinned = load_pinned()
        self.download_pins = load_download_pins()  # v26.08.06.05: pin/favorite feature for the downloader screens
        self._pending_pin_highlight_title = None  # v26.08.06.16: set by
                                      # open_pinned_download_item(),
                                      # consumed once by
                                      # draw_download_browse()'s own
                                      # one-line check after the
                                      # bookmark's real page finishes
                                      # loading -- see that function's
                                      # docstring for why this is the
                                      # ONE generic hook rather than
                                      # per-loader glue.
        self.pinned_plugin_names = load_pinned_plugins()  # v26.08.06.14: pinned SOURCES/plugins, separate feature
        self.download_pinned_index = 0  # v26.08.06.05: selection on SCREEN_DOWNLOAD_PINNED
        self.finished = load_finished()
        self.lib_sort_mode = "title"
        self.lib_filter_mode = "all"  # v0.1.117: All/Unfinished/Finished,
                                       # v26.07.27.25 added Pinned as a
                                       # fourth mode (Kaleb's request).
                                       # resets each launch same as sort mode
        self._all_books = []  # unfiltered disk scan; self.books is the
                               # filtered+sorted view derived from this
        self.books = []
        # v26.07.27.43 (Kaleb's request: Library should navigate folders
        # like a real file manager instead of one flat list with a
        # "-- FolderName" text label). "" means root. Sort/Filter/Pin
        # stay GLOBAL settings (Kaleb's own choice) -- they still apply
        # to whatever folder-scoped subset is currently shown, they're
        # just not saved per-folder.
        self.lib_current_folder = ""
        self.lib_subfolders = []  # real subfolder NAMES of the current
                                   # folder, scanned from disk each time
                                   # _apply_library_view() runs -- so an
                                   # empty folder still shows up as
                                   # navigable, not just folders that
                                   # happen to contain a book already.
        # v26.07.28.10 (Kaleb's request: multi-select for Move to
        # Folder). A set of relpaths, R2-toggled per book row, session-
        # only (never persisted -- there's no scenario where reopening
        # the app with a stale multi-select from last time is useful,
        # and it'd be one more state a person forgets they left set).
        # Deliberately a plain set keyed by relpath, same identity
        # convention self.pinned/self.finished already use -- survives
        # a Sort change (order-only, doesn't affect WHICH books exist)
        # but gets explicitly cleared on anything that changes WHAT'S
