def draw_download_browse(renderer, app):
    # v26.08.06.16 (Kaleb's bookmark redesign): the ONE generic hook
    # this redesign needed. open_pinned_download_item() sets
    # _pending_pin_highlight_title and starts a real page load same as
    # normal navigation; this runs every frame this screen draws (so
    # it fires the instant that load finishes, regardless of which
    # loader/closure did the loading) and does a simple title match --
    # best-effort, matching Kaleb's own "highlight if still findable"
    # phrasing (a since-removed/renamed item just won't match, no
    # error, cursor stays wherever it already was).
    if app._pending_pin_highlight_title and not app.dl_loading and app.dl_items:
        for _pin_i, _pin_it in enumerate(app.dl_items):
            if _pin_it.get("title") == app._pending_pin_highlight_title:
                app.dl_index = _pin_i
                break
        app._pending_pin_highlight_title = None
    fill_rect(renderer, 0, 0, SW, SH, COL_BG)
    # v26.08.06.25 REAL BUG FIX (found live-testing this exact sweep,
    # not by inspection): used to hardcode "JW Videos"/"JW Audio"
    # whenever dl_is_video/dl_is_audio was set, regardless of which
    # plugin actually populated the list -- LibriVox's SUPPORTS_
    # STREAMING routes through this SAME screen via open_plugin_audio_
    # list() (dl_is_audio=True set generically, not JW-specific), so a
    # LibriVox audiobook's browse screen was confirmed showing "JW
    # AUDIO" as its heading, live. Now derives the plugin's own real
    # name in every case -- video/audio labeling still distinguishes
    # "Videos" vs "Audio" (useful context the plain PLUGIN_NAME alone
    # doesn't carry), it just isn't hardcoded to one specific plugin's
    # brand name anymore.
    plugin_name = getattr(app.dl_plugin, "PLUGIN_NAME", "Download") if app.dl_plugin else "Download"
    name = (f"{plugin_name} Videos" if app.dl_is_video else
             f"{plugin_name} Audio" if (app.dl_is_audio or app.dl_audio_pub_mode) else
             plugin_name)
    title = f"{name.upper()}"
    if app.dl_category:
        title += f" -- {app.dl_category}"
    if app.dl_query:
        title += f'  -- "{app.dl_query}"'
    if app.dl_page > 1:
        title += f"  (page {app.dl_page})"
    if app.dl_offline_local:
        # v26.07.23.03: makes clear this list came from what's already
        # on the SD card, not a live fetch -- without this it would
        # look like a normal successful category load with no hint
        # that Download/Search/further browsing won't work right now.
        title += "  [OFFLINE -- downloaded only]"
    # v26.07.12.09: was a single unwrapped render_text() call -- Kaleb's
    # loading-screen wrap audit turned this up as a related, more severe
    # bug: unlike the loading messages (which only overflowed at large
    # Font Sizes), this title overflowed at EVERY Font Size, even the
    # smallest, once a real category name + search query + page number
    # were all concatenated (measured worst case: 949px at the smallest
    # step, 1824px at the largest, against a 680px safe width). Wrapped
    # with the SAME _wrap_hint_text() the hint bar and the text-entry
    # prompt already use, capped at 2 lines (not the hint bar's 3 --
    # this header has less vertical budget above the results list, and 2
    # lines already comfortably fits name+category+query+page in
    # practice). heading_line_h/title_block_h below replace the old
    # single-line assumption baked into `top`'s calculation, so the
    # results list always starts BELOW however many lines the title
    # actually used, at any Font Size -- verified this can't desync
    # against the windowed-list math further down, which only ever reads
    # `top`, never assumes a fixed title height itself.
    _dlb_max_w = SW - _sx(40)
    title_lines = _wrap_hint_text(app.fonts.ui_heading, title, _dlb_max_w, max_lines=2)
    heading_line_h = TTF.TTF_FontHeight(app.fonts.ui_heading)
    for _ti, _tline in enumerate(title_lines):
        render_text(renderer, app.fonts.ui_heading, _tline, COL_ACCENT,
                    _sx(20), _sy(16) + _ti * heading_line_h)
    title_block_h = heading_line_h * len(title_lines)

    title_h = TTF.TTF_FontHeight(app.fonts.ui_body)
    sub_h = TTF.TTF_FontHeight(app.fonts.ui_small)
    row_h = title_h + sub_h + _sy(14)  # v0.1.153: was +_sy(20) -- same
                        # DejaVu-metrics retune as _row_h()'s default pad
                        # (this two-line row predates/bypasses _row_h(),
                        # so it needed its own matching adjustment).
    top = _sy(16) + title_block_h + _sy(14)

    if app.dl_loading:
        # v0.1.62: was static "Loading..." text -- on a slow/laggy
        # connection that's indistinguishable from the screen being
        # frozen, since nothing on screen changes frame to frame. A
        # spinner glyph plus elapsed seconds gives a visible heartbeat
        # so a genuinely slow network call doesn't look like a hang.
        # v26.07.10.14: found during a full pre-cache/loading-screen
        # audit (Kaleb's request) -- this was the one loading indicator
        # in the whole app that predated the face system (v0.1.62, well
        # before FACE_THINKING_A/_B existed) and never got wired up to
        # it. Routed through _kaomoji_for_status() same as every other
        # loading/status message -- it matches on "loading" regardless
        # of the spinner glyph sitting right after that word.
        spinner = "|/-\\"[int(time.time() * 4) % 4]
        secs = int(time.time() - app.dl_loading_start) if app.dl_loading_start else 0
        loading_msg = _kaomoji_for_status(f"Loading {spinner}  ({secs}s)")
        render_text(renderer, app.fonts.ui_body, loading_msg, COL_DIM,
                    _sx(24), top)
    elif app.dl_load_error:
        # v26.08.05.24 BUG FIX (found this session testing the reader
        # menu's "Listen to this Book" for a title with genuinely no
        # audio, e.g. "od"): this branch prefixed EVERY dl_load_error
        # with "Couldn't reach server:", including the deliberately
        # friendly '"<title>" has no audio available' wording
        # list_audio_items()/find_audio_for_epub() already generate for
        # this exact, ordinary, non-error outcome (see the v26.07.30.xx
        # note on that wording choice) -- so a book that simply has no
        # audio read on screen as a network failure, indistinguishable
        # from a real one. Checked live: rendered literally as
        # "Couldn't reach server: \"od\" has no audio available",
        # which would tell a person their WiFi is down when it isn't.
        # Fixed: recognize this one specific, controlled wording (both
        # generating call sites use the exact same phrase) and show it
        # plainly, no alarming header, no server-failure framing.
        if str(app.dl_load_error).endswith("has no audio available"):
            render_text(renderer, app.fonts.ui_body, str(app.dl_load_error)[:70], COL_DIM,
                        _sx(24), top)
        else:
            render_text(renderer, app.fonts.ui_body, "Couldn't reach server:", COL_WARNING, _sx(24), top)
            render_text(renderer, app.fonts.ui_small, str(app.dl_load_error)[:70], COL_DIM,
                        _sx(24), top + title_h + _sy(6))
    elif not app.dl_items:
        whats_new = getattr(app.dl_plugin, "CATEGORY_WHATS_NEW", None)
        msg = ("No new publications detected via RSS right now."
               if whats_new and app.dl_category == whats_new else "No results.")
        render_text(renderer, app.fonts.ui_body, msg, COL_DIM, _sx(24), top)
    else:
        visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
        start = max(0, app.dl_index - visible // 2)
        for i in range(visible):
            di = start + i
            if di >= len(app.dl_items):
                break
            item = app.dl_items[di]
            y = top + i * row_h
            if di == app.dl_index:
                _anim_y = y  # v26.07.17.05: glide removed, instant snap
                fill_rect_rounded(renderer, _sx(10), int(_anim_y), SW - _sx(20), row_h - _sy(4), COL_MENU_SEL_BG)
            color = COL_ACCENT if di == app.dl_index else COL_TEXT
            title_line = item.get("title", "")[:56]
            if di == app._dl_downloading_idx:
                title_line += "  (downloading...)"
            # v26.07.15.26 BUG FIX (Kaleb's real-device photo: title and
            # subtitle overlapping on every row of every JW category --
            # Videos, Audio, Bibles, Watchtower, Meeting Workbooks, etc.,
            # since they all share this one renderer, plus Gutenberg).
            # Root cause: the title used _row_text_y() -- a helper built
            # to vertically CENTER A SINGLE LINE within row_h (see its
            # own docstring) -- but this is a TWO-line row (title +
            # subtitle). Centering the title as if it were the row's
            # only content pushes it down by roughly half of the
            # subtitle's own height, while the subtitle below it was
            # positioned independently via a raw "y + title_h + _sy(10)"
            # offset that assumed the title started at the row's
            # unshifted top -- the two assumptions didn't match, so the
            # (now lower) title collided with the subtitle every time,
            # at every Font Size (title_h/sub_h both scale together, so
            # this was never a small-Font-Size-only glitch). Fixed by
            # computing the actual two-line BLOCK height (title_h + a
            # real inter-line gap + sub_h) and centering THAT block
            # within the row's slack, same spirit as _row_text_y() but
            # for two lines instead of one -- title and subtitle now
            # both derive their y from the same block_top, so they can
            # never desync again regardless of row_h's own tuning.
            block_gap = _sy(4)  # visual gap between title and subtitle lines
            block_h = title_h + block_gap + sub_h
            slack = max(0, row_h - _sy(4) - block_h)  # _sy(4) matches the
                                                        # highlight_shrink
                                                        # used for this row's
                                                        # selection rect above
            block_top = y + slack // 2
            render_text(renderer, app.fonts.ui_body, title_line, color, _sx(24), block_top)
            render_text(renderer, app.fonts.ui_small, item.get("subtitle", "")[:70], COL_DIM,
                        _sx(24), block_top + title_h + block_gap)
        draw_scrollbar(renderer, app, SCREEN_DOWNLOAD_BROWSE, SW - _sx(6), top, visible * row_h,
                        len(app.dl_items), visible, start)

    if app.status_msg and time.time() < app.status_until:
        _draw_status_bar(renderer, app.fonts, app.status_msg, COL_ACCENT,
                          SH - _sy(hint_height(app.fonts)), alpha=app.status_alpha())

    hint = "UP/DOWN Select   A Download   B Back"
    if app.dl_has_next or app.dl_page > 1:
        hint = "UP/DOWN Select   L/R Page   A Download   B Back"
    elif app.dl_items:
        # v0.1.88: no server-side pages to flip through, but L/R still do
        # something useful here -- jump 10 items locally -- so say so.
        hint = "UP/DOWN Select   L/R Jump 10   A Download   B Back"
    if app.dl_is_video:
        # v0.1.110: video mode has its own Y binding (client-side title
        # search, see App.search_video_items()) -- unrelated to the
        # underlying plugin's SUPPORTS_SEARCH/SUPPORTS_MANUAL_CODE flags.
        # v26.07.20.05: A/SELECT swapped from the previous session -- A
        # streams, SELECT downloads, for video mode specifically (every
        # other screen/mode keeps "A Download" unchanged).
        hint = hint.replace("A Download", "A Stream").replace(
            "B Back", "Y Search   START Play All   L2 Shuffle   SELECT Download   B Back")
    elif app.dl_is_audio:
        # v26.07.21.36 (Kaleb's request: in-app audio playback). Was a
        # plain "A Download" hint (audio had no playback at all before
        # this) -- now matches video's A=play/SELECT=download
        # convention, plus the two list-playback modes.
        # v26.07.21.43 (Kaleb's request: unify the video/audio queue
        # buttons): Play All moved from Y to START, Shuffle from START
        # to L2 -- now identical to video's own hint text below, was
        # backwards from it before (Y/START here vs. START/L2 there).
        hint = hint.replace("A Download", "A Play").replace(
            "B Back", "START Play All   L2 Shuffle   SELECT Download   B Back")
    elif getattr(app.dl_plugin, "SUPPORTS_SEARCH", False):
        hint = hint.replace("B Back", "Y Search   B Back")
    elif getattr(app.dl_plugin, "SUPPORTS_CATEGORIES", False):
        # v0.1.156 BUG FIX: this branch was MISSING entirely -- the hint
        # text fell straight through to the SUPPORTS_MANUAL_CODE branch
        # below and said "Y Enter Code", even though handle_button()'s
        # own elif chain checks SUPPORTS_CATEGORIES first and Y actually
        # opens a category-scoped title search instead. Confirmed via
        # direct simulation the hint and the real behavior had drifted
        # apart. Now matches what Y actually does.
        hint = hint.replace("B Back", "Y Search   B Back")
    if not app.dl_is_video and not app.dl_is_audio and getattr(app.dl_plugin, "SUPPORTS_MANUAL_CODE", False):
        # v0.1.156: SELECT (not Y -- see handle_button()'s SELECT branch
        # docstring) is now its own, always-reachable binding whenever a
        # plugin declares this, regardless of whether it ALSO supports
        # search/categories -- previously this and the categories-search
        # branch shared the single Y button via an elif chain, silently
        # shadowing one or the other.
        hint = hint.replace("B Back", "SELECT Code   B Back")
    hint = hint.replace("B Back", "X Menu   B Back")
    draw_hint(renderer, app.fonts, hint)


def draw_library_delete_folder(renderer, app):
    """v26.07.23.07 (Kaleb's request): simple list picker for "Delete
    Folder" -- same layout pattern as draw_download_audio_sources()
    just above. Lists every top-level folder under LIBRARY_DIR
    (list_library_folders()) -- both app-created category folders and
    anything a person made manually. Two-press confirm (armed/
    unarmed), same safety pattern as "Delete Book"; only allows
    deleting a folder that's genuinely empty (checked live at button-
    press time, not cached here) to avoid silently destroying books."""
    fill_rect(renderer, 0, 0, SW, SH, COL_BG)
    heading_y = _sy(16)
    # v26.07.27.43: shows WHICH folder this list is scoped to now that
    # it's no longer always the Library root -- same breadcrumb
    # convention draw_library() itself uses.
    # v26.07.28.04 BUG FIX (Kaleb's request, bug-check follow-up): gated
    # on Filter == "folders" too, same reasoning as _delete_folder_base
    # right below -- this heading must match wherever the base dir
    # actually points, not a stale lib_current_folder from earlier
    # Folders browsing.
    _heading_scope = app.lib_current_folder if app.lib_filter_mode == "folders" else ""
    heading_text = "DELETE FOLDER" if not _heading_scope else f"DELETE FOLDER (in {_heading_scope})"
    render_text(renderer, app.fonts.ui_heading, _fit_text(app.fonts.ui_heading, heading_text, SW - _sx(40)),
                COL_ACCENT, _sx(20), heading_y)
    row_h = _row_h(app.fonts.ui_body)
    top = heading_y + TTF.TTF_FontHeight(app.fonts.ui_heading) + _sy(14)
    # v26.07.23.17 BUG FIX (found during a cosmetic-UI audit): rows here
    # used to render the raw label with NO width limit at all -- every
    # other similar list screen in this codebase either has short, fixed
    # labels (draw_download_audio_sources() etc., safe without _fit_text)
    # or explicitly truncates (draw_download_browse_menu()). This screen
    # is neither: folder names are real, unbounded text (a person's own
    # typed name, or a long category name like "Sing Out Joyfully to
    # Jehovah-Instrumental", 42+ characters) PLUS a 30-character "press A
    # again to confirm" suffix appended when armed -- confirmed this
    # combination would run well past the screen edge, especially at a
    # larger Font Size setting, with nothing to stop it. Now truncated
    # with the same _fit_text() ellipsis convention used everywhere else
    # dynamic-length text meets a fixed-width row.
    row_max_w = SW - _sx(48)
    # v26.07.28.03 BUG FIX (Kaleb's request, found during a requested
    # bug-check of the new Folders filter): lib_current_folder is
    # deliberately preserved across filter switches (so Folders can
    # resume where you left off), but that also meant Delete Folder
    # kept operating relative to it even while Filter != "folders" --
    # a place with no breadcrumb or subfolder rows on screen to confirm
    # it. Gated to root unless Folders is the active filter, so this
    # screen always matches what's actually visible.
    _delete_folder_scope = app.lib_current_folder if app.lib_filter_mode == "folders" else ""
    _delete_folder_base = (os.path.join(LIBRARY_DIR, _delete_folder_scope)
                            if _delete_folder_scope else LIBRARY_DIR)
    folders = list_library_folders(_delete_folder_base)
    if not folders:
        render_text(renderer, app.fonts.ui_body, "No folders yet.", COL_DIM, _sx(24), top)
    else:
        n_items = len(folders)
        idx = min(app.lib_delete_folder_index, n_items - 1)
        visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
        start = max(0, min(idx - visible // 2, max(0, n_items - visible)))
        for i in range(start, min(n_items, start + visible)):
            y = top + (i - start) * row_h
            if i == idx:
                fill_rect_rounded(renderer, _sx(10), int(y), SW - _sx(20), row_h - _sy(4), COL_MENU_SEL_BG)
            color = COL_ACCENT if i == idx else COL_TEXT
            label = folders[i]
            if i == idx and app._menu_delete_folder_armed:
                label += "  -- press A again to confirm"
            label = _fit_text(app.fonts.ui_body, label, row_max_w)
            render_text(renderer, app.fonts.ui_body, label, color, _sx(24), _row_text_y(y, row_h, app.fonts.ui_body, 4))
    if app.status_msg and time.time() < app.status_until:
        _draw_status_bar(renderer, app.fonts, app.status_msg, COL_ACCENT,
                          SH - _sy(hint_height(app.fonts)), alpha=app.status_alpha())
    hint = "UP/DOWN Select   A Delete (2x)   B Back" if folders else "B Back"
    draw_hint(renderer, app.fonts, hint)


def draw_library_move_folder(renderer, app):
    """v26.07.27.44 (Kaleb's request: "Move to Folder"). Same list-
    picker shape as draw_library_delete_folder() just above, but no
    armed/confirm state -- moving isn't destructive the way deleting
    is, a single A press is enough. Lists list_all_library_folders()
    (every folder at every depth, unlike Delete Folder's one-level
    scope, since reorganizing across branches is the whole point) with
    an explicit "(Library Root)" option prepended -- "" isn't a real
    folder name to show in the list otherwise."""
    fill_rect(renderer, 0, 0, SW, SH, COL_BG)
    heading_y = _sy(16)
    # v26.07.28.10 (Kaleb's request: multi-select). Same priority order
    # as the Library Menu label and the execution handler -- selection
    # wins over the single highlighted book if one exists.
    if app.lib_selected:
        heading_text = f"MOVE {len(app.lib_selected)} BOOKS"
    else:
        target_title = app._menu_target_book["title"] if app._menu_target_book else "(no book selected)"
        heading_text = f"MOVE: {target_title}"
    render_text(renderer, app.fonts.ui_heading, _fit_text(app.fonts.ui_heading, heading_text, SW - _sx(40)),
                COL_ACCENT, _sx(20), heading_y)
    row_h = _row_h(app.fonts.ui_body)
    top = heading_y + TTF.TTF_FontHeight(app.fonts.ui_heading) + _sy(14)
    row_max_w = SW - _sx(48)

    options = ["(Library Root)"] + list_all_library_folders()
    n_items = len(options)
    idx = min(app.lib_move_folder_index, n_items - 1)
    visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
    start = max(0, min(idx - visible // 2, max(0, n_items - visible)))
    for i in range(start, min(n_items, start + visible)):
        y = top + (i - start) * row_h
        if i == idx:
            fill_rect_rounded(renderer, _sx(10), int(y), SW - _sx(20), row_h - _sy(4), COL_MENU_SEL_BG)
        color = COL_ACCENT if i == idx else COL_TEXT
        label = _fit_text(app.fonts.ui_body, options[i], row_max_w)
        render_text(renderer, app.fonts.ui_body, label, color, _sx(24), _row_text_y(y, row_h, app.fonts.ui_body, 4))

    if app.status_msg and time.time() < app.status_until:
        _draw_status_bar(renderer, app.fonts, app.status_msg, COL_ACCENT,
                          SH - _sy(hint_height(app.fonts)), alpha=app.status_alpha())
    draw_hint(renderer, app.fonts, "UP/DOWN Select   A Move   B Back")


def draw_library_menu(renderer, app):
    draw_library(renderer, app)
    # v26.07.21.16: same per-minute clock refresh as draw_menu() above.
    app.maybe_refresh_clock()
    overlay_w = _sx(320)
    fill_rect_rounded(renderer, SW - overlay_w, 0, overlay_w, SH - _sy(hint_height(app.fonts)), COL_PANEL)
    render_text(renderer, app.fonts.ui_heading, "MENU", COL_ACCENT, SW - overlay_w + _sx(20), _sy(20))
    # v26.07.21.14 (Kaleb's request): same battery/WiFi status icons as
    # the main reader popup Menu, top-right corner of this panel too --
    # this screen's "MENU" title is short/left-anchored (not centered
    # like draw_menu()'s logo) so it never needed to shift for room.
    _draw_status_indicators(renderer, app, SW - _sx(14), _sy(18))
    row_h = _row_h(app.fonts.ui_body)
    top = _sy(76)
    item_max_w = overlay_w - _sx(40)
    n_items = len(LIBRARY_MENU_ITEMS)
    visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
    start = max(0, min(app.lib_menu_index - visible // 2, max(0, n_items - visible)))
    # v26.07.20.39 REAL BUG FIX (found during the same pass as the main
    # reader-popup-menu fix above -- same bug, third location found):
    # this loop used `(i - start)`, the raw position within the visible
    # window, so hiding "Discover More" (DOWNLOAD_PLUGINS empty --
    # e.g. jw_fetch.py AND gutenberg_fetch.py both omitted) left a
    # blank row_h-sized gap and shifted every row below it down. Fixed
    # with row_pos, the same counter-that-only-advances-for-drawn-rows
    # pattern already used in draw_storage() (v26.07.17.16) and the
    # main reader popup menu (v26.07.20.39, this same session).
    row_pos = 0
    for i in range(start, min(n_items, start + visible)):
        item = LIBRARY_MENU_ITEMS[i]
        if item == "Discover More" and not DOWNLOAD_PLUGINS:
            continue  # hide entirely if no downloader plugin is present
        if item == "Pinned Discoveries" and not app.download_pins:
            continue  # v26.08.06.05: same hide-if-empty convention as
                      # Discover More just above -- no point showing a
                      # menu entry for an empty list.
        y = top + row_pos * row_h
        row_pos += 1
        label = item
        if item == "Continue Reading":
            recent = app.most_recent_book()
            label = f"Continue: {recent['title']}" if recent else "Continue Reading: none yet"
        if item == "Mark Finished/Unfinished":
            tgt = app._menu_target_book
            if tgt:
                is_finished = tgt["relpath"] in app.finished
                label = f"{'Mark Unfinished' if is_finished else 'Mark Finished'}: {tgt['title']}"
            else:
                label = "Mark Finished/Unfinished"
        if item == "Filter: Cycle":
            label = f"Filter: {LIBRARY_FILTER_LABELS[app.lib_filter_mode]}"
        # v26.08.07.15: Move to Folder's and Delete Book's dynamic-
        # label blocks that used to live here moved to
        # draw_edit_library_menu() along with the items themselves --
        # see SCREEN_EDIT_LIBRARY_MENU's own comment. "Edit Library..."
        # itself needs no dynamic label, same as "Themes..." just
        # above it.
        armed_clear = False
        if item == "Clear All Finished":
            n_finished = len(app.finished)
            if app._menu_clear_finished_armed:
                label = f"Press A again to clear {n_finished} mark" + ("s" if n_finished != 1 else "")
                armed_clear = True
            else:
                label = f"Clear All Finished: {n_finished}"
        armed_warning = armed_clear
        if armed_warning:
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), y, overlay_w - _sx(20), row_h - _sy(6), COL_WARNING)
        elif i == app.lib_menu_index:
            _anim_y = y  # v26.07.17.05: glide removed, instant snap
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), int(_anim_y), overlay_w - _sx(20), row_h - _sy(6), COL_MENU_SEL_BG)
        color = COL_BG if armed_warning else (COL_ACCENT if i == app.lib_menu_index else COL_TEXT)
        render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, item_max_w),
                    color, SW - overlay_w + _sx(20), _row_text_y(y, row_h, app.fonts.ui_body, 6))
    draw_hint(renderer, app.fonts, "UP/DOWN Select   A Confirm   B Back")


def draw_edit_library_menu(renderer, app):
    """v26.08.07.15 (Kaleb's request: "the list is getting longer and
    longer... move the move, edit delete and new and nest them in a
    new sub menu called Edit Library"). New Folder/Move to Folder/
    Delete Folder/Delete Book, pulled out of draw_library_menu() into
    their own submenu -- same nested-overlay shape as draw_theme_menu()
    (draws over the bare Library backdrop, not over the parent menu
    panel, so it never looks like menus stacking three deep)."""
    draw_library(renderer, app)
    app.maybe_refresh_clock()
    overlay_w = _sx(320)
    fill_rect_rounded(renderer, SW - overlay_w, 0, overlay_w, SH - _sy(hint_height(app.fonts)), COL_PANEL)
    render_text(renderer, app.fonts.ui_heading, "EDIT LIBRARY", COL_ACCENT, SW - overlay_w + _sx(20), _sy(20))
    _draw_status_indicators(renderer, app, SW - _sx(14), _sy(18))
    row_h = _row_h(app.fonts.ui_body)
    top = _sy(76)
    item_max_w = overlay_w - _sx(40)
    n_items = len(EDIT_LIBRARY_MENU_ITEMS)
    visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
    start = max(0, min(app.edit_library_menu_index - visible // 2, max(0, n_items - visible)))
    row_pos = 0
    for i in range(start, min(n_items, start + visible)):
        item = EDIT_LIBRARY_MENU_ITEMS[i]
        y = top + row_pos * row_h
        row_pos += 1
        label = item
        if item == "Move to Folder":
            # v26.07.28.10 (Kaleb's request: multi-select). Selection
            # takes priority over the single highlighted book in the
            # label too, matching the trigger/execution logic below --
            # keeps this row's own text honest about what A will
            # actually act on. Moved here unchanged from
            # draw_library_menu() -- see v26.08.07.15's own comment.
            if app.lib_selected:
                label = f"Move: {len(app.lib_selected)} selected"
            elif app._menu_target_book:
                label = f"Move: {app._menu_target_book['title']}"
            else:
                label = "Move to Folder"
        armed_delete = False
        if item == "Delete Book":
            if app._menu_delete_armed:
                label = "Press A again to DELETE"
                armed_delete = True
            elif app._menu_target_book:
                label = f"Delete: {app._menu_target_book['title']}"
            else:
                label = "Delete Book"
        if armed_delete:
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), y, overlay_w - _sx(20), row_h - _sy(6), COL_WARNING)
        elif i == app.edit_library_menu_index:
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), int(y), overlay_w - _sx(20), row_h - _sy(6), COL_MENU_SEL_BG)
        color = COL_BG if armed_delete else (COL_ACCENT if i == app.edit_library_menu_index else COL_TEXT)
        render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, item_max_w),
                    color, SW - overlay_w + _sx(20), _row_text_y(y, row_h, app.fonts.ui_body, 6))
    if app.status_msg and time.time() < app.status_until:
        _draw_status_bar(renderer, app.fonts, app.status_msg, COL_ACCENT,
                          SH - _sy(hint_height(app.fonts)), alpha=app.status_alpha())
    draw_hint(renderer, app.fonts, "UP/DOWN Select   A Confirm   B Back")


def draw_theme_menu(renderer, app):
    """v26.07.15.24: overlay, NOT a full-screen takeover (see
    THEME_MENU_ITEMS' own comment for why Kaleb's follow-up question
    about this mattered) -- draws the real backdrop (whichever of
    Reader/Library opened it) first, exactly like draw_menu()/
    draw_library_menu(), so Theme +/-, Randomize, and Regenerate all
    stay visible against real content while this panel is open."""
    if app._theme_menu_return_screen == SCREEN_MENU:
        draw_reader(renderer, app)
    else:
        draw_library(renderer, app)
    overlay_w = _sx(320)
    fill_rect_rounded(renderer, SW - overlay_w, 0, overlay_w, SH - _sy(hint_height(app.fonts)), COL_PANEL)
    render_text(renderer, app.fonts.ui_heading, "THEMES", COL_ACCENT, SW - overlay_w + _sx(20), _sy(20))
    # v26.07.27.12 (Kaleb's request -- Feature #1 follow-up, found during
    # a full re-review: this popup and Video Settings below were both
    # missed the first pass, "all pop-up menus" wasn't actually ALL of
    # them). Same battery/WiFi/clock indicators every other popup now
    # shows.
    _draw_status_indicators(renderer, app, SW - _sx(14), _sy(18))
    themes = all_themes()
    current_name = themes[THEME_INDEX]["name"] if 0 <= THEME_INDEX < len(themes) else "?"
    # v26.07.28.20 (Kaleb's request: cycling clarity): same "(unsaved)"
    # label the Theme +/- toast now shows -- this subtitle is the OTHER
    # persistent place the draft's name shows up while browsing, so it
    # needs the same marker for the same reason.
    if _DRAFT_THEME is not None and THEME_INDEX == len(themes) - 1:
        current_name += " (unsaved)"
    # v26.07.15.27 (Kaleb's report): the current theme's name used to be
    # appended to BOTH the "Theme +" and "Theme -" row labels (so it
    # showed up twice in the list itself) on top of a THIRD showing in
    # the toast set_status() already gives after pressing either one.
    # Shown ONCE here instead, as a persistent subtitle under the
    # heading -- still visible at a glance while browsing the submenu,
    # without repeating per-row or fighting with the toast.
    # v26.07.28.23 (Kaleb's request: standardize popup sizing across
    # resolutions). These 3 lines used to render at app.fonts.ui_small,
    # which scales 1:1 with the main Font Size setting -- at max Font
    # Size on RG34XX-SP's shorter 480px canvas, this block alone (3
    # lines + gaps) measured 186px, 39% of the ENTIRE screen, before a
    # single menu row even started. Capped to the same already
    # resolution-aware pt _hint_pt() computes for the hint bar below --
    # reusing that value rather than inventing a second, separate cap,
    # so this and the hint bar always shrink together and stay visually
    # consistent with each other. This is supporting/glance-at context,
    # not the primary content Font Size is meant to control (the actual
    # selectable menu rows below still use app.fonts.ui_body,
    # completely unaffected -- Font Size still applies fully to what a
    # person is actually trying to read and select).
    _subtitle_pt = _hint_pt(app.fonts)
    _subtitle_font = app.fonts._get(_subtitle_pt) if _subtitle_pt else app.fonts.ui_small
    current_y = _sy(20) + TTF.TTF_FontHeight(app.fonts.ui_heading) + _sy(4)
    render_text(renderer, _subtitle_font, f"Current: {current_name}", COL_DIM,
                SW - overlay_w + _sx(20), current_y)
    small_h = TTF.TTF_FontHeight(_subtitle_font)
    # v26.07.15.31 (Kaleb's usability pass): two more at-a-glance lines --
    # how many of the 3 custom slots are used (so saving a new one and
    # silently evicting the oldest isn't a surprise), and a pointer to
    # where Backup/Restore actually live (Storage screen, reachable via
    # Settings from the PARENT menu, not from inside this submenu at
    # all -- easy to not know it exists otherwise).
    saved_y = current_y + small_h + _sy(2)
    render_text(renderer, _subtitle_font,
                f"Saved: {len(CUSTOM_THEMES)}/{MAX_CUSTOM_THEMES}", COL_DIM,
                SW - overlay_w + _sx(20), saved_y)
    backup_y = saved_y + small_h + _sy(2)
    render_text(renderer, _subtitle_font, "Backup/Restore: see Settings", COL_DIM,
                SW - overlay_w + _sx(20), backup_y)
    row_h = _row_h(app.fonts.ui_body)
    top = backup_y + small_h + _sy(14)
    item_max_w = overlay_w - _sx(40)
    n_items = len(THEME_MENU_ITEMS)
    visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
    start = max(0, min(app.theme_menu_index - visible // 2, max(0, n_items - visible)))
    # v26.07.15.27 (Kaleb's report): Theme +/- rows used to append
    # "(current_name)" to their OWN labels -- since both rows did this,
    # the current theme's name showed up TWICE just sitting in the
    # menu, and a THIRD time in the toast set_status() already shows
    # after pressing either one. Removed the per-row suffix entirely;
    # the toast alone is the feedback for what Theme +/- just switched
    # to. The current theme name is still shown once, persistently, in
    # the "Current: X" subtitle above (see current_name's first
    # assignment, right after the heading) rather than duplicated
    # across every row.
    for i in range(start, min(n_items, start + visible)):
        item = THEME_MENU_ITEMS[i]
        y = top + (i - start) * row_h
        label = item
        if item == "Regenerate Theme" and _DRAFT_REPLACE_NAME is not None:
            label = f"Regenerate Theme: re-rolling \"{_DRAFT_REPLACE_NAME}\""
        elif item == "Save Regenerated Theme" and _DRAFT_REPLACE_NAME is None:
            label = "Save Regenerated Theme: nothing pending"
        elif item == "Rename Theme":
            local_idx = THEME_INDEX - len(THEMES)
            if 0 <= local_idx < len(CUSTOM_THEMES):
                label = f"Rename Theme: \"{CUSTOM_THEMES[local_idx]['name']}\""
            else:
                label = "Rename Theme: cycle to a saved theme first"
        elif item == "Delete Theme":
            if app._theme_delete_armed:
                label = "Press A again to DELETE"
            else:
                local_idx = THEME_INDEX - len(THEMES)
                if 0 <= local_idx < len(CUSTOM_THEMES):
                    label = f"Delete Theme: \"{CUSTOM_THEMES[local_idx]['name']}\""
                else:
                    label = "Delete Theme: cycle to a saved theme first"
        armed_warning = (item == "Delete Theme" and app._theme_delete_armed)
        if armed_warning:
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), y, overlay_w - _sx(20), row_h - _sy(6), COL_WARNING)
        elif i == app.theme_menu_index:
            _anim_y = y  # v26.07.17.05: glide removed, instant snap
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), int(_anim_y), overlay_w - _sx(20), row_h - _sy(6), COL_MENU_SEL_BG)
        color = COL_BG if armed_warning else (COL_ACCENT if i == app.theme_menu_index else COL_TEXT)
        render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, item_max_w),
                    color, SW - overlay_w + _sx(20), _row_text_y(y, row_h, app.fonts.ui_body, 6))
    draw_hint(renderer, app.fonts, "UP/DOWN Select   A Confirm   B Back")


def draw_video_settings(renderer, app):
    """v26.07.20.09: Video Fill Screen + Streaming Quality, collapsed out
    of the reader popup Menu into their own small submenu (Kaleb's
    request -- same "don't overclutter the popup menu" reasoning as
    SCREEN_THEME_MENU above, just simpler: this is only ever opened from
    SCREEN_MENU, never from Library Menu too, so there's no equivalent of
    _theme_menu_return_screen to track -- B always goes straight back to
    SCREEN_MENU."""
    draw_reader(renderer, app)
    overlay_w = _sx(320)
    fill_rect_rounded(renderer, SW - overlay_w, 0, overlay_w, SH - _sy(hint_height(app.fonts)), COL_PANEL)
    # v26.07.27.13 REAL BUG FIX (found via direct pixel-width measurement
    # at the largest Font Size setting): "VIDEO SETTINGS" is long enough
    # that it ran ~100px into the status-indicator zone added just above
    # (v26.07.27.12) -- "MENU"/"THEMES" elsewhere clear with real margin
    # at every Font Size (confirmed the same way), so only this heading
    # needed it. Same _fit_text() ellipsis-truncate helper other fixed-
    # width panels already use, against the same usable-width math
    # draw_menu()'s own logo centering uses (overlay_w minus a left
    # margin minus STATUS_INDICATORS_W).
    _vs_heading_max_w = overlay_w - _sx(34) - STATUS_INDICATORS_W
    _vs_heading = _fit_text(app.fonts.ui_heading, "VIDEO SETTINGS", _vs_heading_max_w)
    render_text(renderer, app.fonts.ui_heading, _vs_heading, COL_ACCENT, SW - overlay_w + _sx(20), _sy(20))
    # v26.07.27.12 (Feature #1 follow-up): same indicators added to
    # draw_theme_menu() just above -- see that call's own comment.
    _draw_status_indicators(renderer, app, SW - _sx(14), _sy(18))
    row_h = _row_h(app.fonts.ui_body)
    top = _sy(20) + TTF.TTF_FontHeight(app.fonts.ui_heading) + _sy(18)
    item_max_w = overlay_w - _sx(40)
    n_items = len(VIDEO_SETTINGS_ITEMS)
    visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
    start = max(0, min(app.video_settings_index - visible // 2, max(0, n_items - visible)))
    for i in range(start, min(n_items, start + visible)):
        item = VIDEO_SETTINGS_ITEMS[i]
        y = top + (i - start) * row_h
        label = item
        if item == "Fill Screen":
            label = f"Fill Screen: {'On' if app.video_fill_screen else 'Off'}"
        elif item == "Streaming Quality":
            label = f"Streaming Quality: {app.video_stream_quality} (downloads stay 480p)"
        elif item == "Video Player":
            label = f"Video Player: {app.video_player_pref.capitalize()}"
        if i == app.video_settings_index:
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), y, overlay_w - _sx(20), row_h - _sy(6), COL_MENU_SEL_BG)
        color = COL_ACCENT if i == app.video_settings_index else COL_TEXT
        render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, item_max_w),
                    color, SW - overlay_w + _sx(20), _row_text_y(y, row_h, app.fonts.ui_body, 6))
    draw_hint(renderer, app.fonts, "UP/DOWN Select   A Confirm   B Back")


def draw_listen_audio_variant(renderer, app):
    """v26.08.05.16 (Kaleb's request: "song book should give option for
    choir and meeting instrumentals"). Small overlay over the reader
    (the only screen this is ever reached from -- see _start_listen_
    to_book()), same shape as draw_theme_select() just above but with
    a small variable-length list instead of the theme table, and no
    live preview (there's nothing to preview here -- picking a variant
    just decides which audio lookup A on the confirm makes next,
    unlike theme selection which is already visibly applied as you
    scroll).

    v26.08.06.22 (Kaleb's request: generalize this out of a JW-named
    screen): entirely data-driven off app._pending_variant_choices --
    the (key, label) pairs whatever plugin's get_audio_variants()
    returned, stashed there by _start_listen_to_book(). No plugin name,
    publication name, or hardcoded label string anywhere in this
    function anymore (the old `labels = {"vocals": "Vocals", ...}`
    dict and the direct MEDIA_PLUGIN.SONGBOOK_CATEGORY_ORDER read are
    both gone -- the plugin now supplies its own display labels
    directly, since it's the one that actually knows what they mean)."""
    draw_reader(renderer, app)
    overlay_w = _sx(360)
    fill_rect_rounded(renderer, SW - overlay_w, 0, overlay_w, SH - _sy(hint_height(app.fonts)), COL_PANEL)
    render_text(renderer, app.fonts.ui_heading, "LISTEN -- WHICH VERSION?", COL_ACCENT,
                SW - overlay_w + _sx(20), _sy(20))
    row_h = _row_h(app.fonts.ui_body)
    top = _sy(20) + TTF.TTF_FontHeight(app.fonts.ui_heading) + _sy(14)
    item_max_w = overlay_w - _sx(40)
    choices = app._pending_variant_choices
    for i, (_key, label) in enumerate(choices):
        y = top + i * row_h
        if i == app.audio_variant_index:
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), int(y), overlay_w - _sx(20), row_h - _sy(6), COL_MENU_SEL_BG)
        color = COL_ACCENT if i == app.audio_variant_index else COL_TEXT
        render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, item_max_w),
                    color, SW - overlay_w + _sx(20), _row_text_y(y, row_h, app.fonts.ui_body, 6))
    draw_hint(renderer, app.fonts, "UP/DOWN Select   A Confirm   B Back")



def draw_theme_select(renderer, app):
    """v26.07.15.31 (Kaleb's request): jump directly to any theme by
    name instead of stepping through Theme +/- one at a time. Overlay
    over the same live backdrop as draw_theme_menu() -- UP/DOWN in
    handle_button() already applied the highlighted theme live before
    this draws, so what's behind the panel IS the live preview; this
    function only needs to render the list itself."""
    if app._theme_menu_return_screen == SCREEN_MENU:
        draw_reader(renderer, app)
    else:
        draw_library(renderer, app)
    overlay_w = _sx(320)
    fill_rect_rounded(renderer, SW - overlay_w, 0, overlay_w, SH - _sy(hint_height(app.fonts)), COL_PANEL)
    render_text(renderer, app.fonts.ui_heading, "SELECT THEME", COL_ACCENT, SW - overlay_w + _sx(20), _sy(20))
    row_h = _row_h(app.fonts.ui_body)
    top = _sy(20) + TTF.TTF_FontHeight(app.fonts.ui_heading) + _sy(14)
    item_max_w = overlay_w - _sx(40)
    themes = all_themes()
    n_items = len(themes)
    visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
    start = max(0, min(app.theme_select_index - visible // 2, max(0, n_items - visible)))
    for i in range(start, min(n_items, start + visible)):
        y = top + (i - start) * row_h
        label = themes[i]["name"]
        # v26.07.28.20 (Kaleb's request: cycling clarity): the draft
        # slot (if any) is always the LAST entry in all_themes() and
        # was getting the same "(custom)" suffix as a real saved
        # theme -- misleading, since it isn't one yet. "(unsaved)"
        # here matches the same label Theme +/- and the Current:
        # subtitle now show for the same slot.
        if _DRAFT_THEME is not None and i == n_items - 1:
            label += "  (unsaved)"
        elif i >= len(THEMES):
            label += "  (custom)"
        if i == app.theme_select_index:
            _anim_y = y  # v26.07.17.05: glide removed, instant snap
            fill_rect_rounded(renderer, SW - overlay_w + _sx(10), int(_anim_y), overlay_w - _sx(20), row_h - _sy(6), COL_MENU_SEL_BG)
        color = COL_ACCENT if i == app.theme_select_index else COL_TEXT
        render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, item_max_w),
                    color, SW - overlay_w + _sx(20), _row_text_y(y, row_h, app.fonts.ui_body, 6))
    draw_hint(renderer, app.fonts, "UP/DOWN Preview   A Confirm   B Back")


def draw_recently_played(renderer, app):
    """v26.07.27.31 (Kaleb's request): one combined list -- books,
    video, audio, newest first -- reachable from the Library popup
    menu, plus a "Clear History" row IN the list itself (Kaleb's own
    explicit ask, not a separate popup/confirm elsewhere) as row 0,
    same two-press arm/confirm convention Clear All Finished/Delete
    Book/Delete Theme already use for a destructive bulk action. Same
    windowed-scroll shape draw_download_browse_menu() uses (visible-
    count computed from actual space, start clamped so the highlighted
    row is kept roughly centered) since this can hold up to
    RECENTS_MAX(50) rows, more than reliably fits on screen at every
    Font Size."""
    fill_rect(renderer, 0, 0, SW, SH, COL_BG)
    recents = load_recents()
    render_text(renderer, app.fonts.ui_heading, f"HISTORY ({len(recents)}/{RECENTS_MAX})",
                COL_ACCENT, _sx(20), _sy(16))
    row_h = _row_h(app.fonts.ui_body)
    top = _sy(70)
    if not recents:
        # v26.07.27.35 REAL BUG FIX (found during a requested font-size
        # bug-check): this was a raw single-line render_text() with no
        # wrapping at all, unlike every other multi-word message in
        # this file -- measured the real pixel width at max Font Size
        # and confirmed it genuinely overflowed (1084px vs a 720px
        # screen), not a latent/theoretical risk like the Clear History
        # label turned out to be. Now wraps through the same
        # _wrap_hint_text_unbounded() helper other long messages use.
        empty_lines = _wrap_hint_text_unbounded(
            app.fonts.ui_body,
            "Nothing played yet -- books, videos, and audio you open will show up here.",
            SW - _sx(44))
        body_h = TTF.TTF_FontHeight(app.fonts.ui_body)
        for i, line in enumerate(empty_lines):
            render_text(renderer, app.fonts.ui_body, line, COL_DIM, _sx(24), top + i * body_h)
        draw_hint(renderer, app.fonts, "B Back")
        return

    _KIND_LABEL = {"book": "Book", "video": "Video", "audio": "Audio"}
    # row 0 is the synthetic "Clear History" action; real entries are
    # recents[i-1] for row index i >= 1 -- see the button handler's own
    # comment for why this shape (rather than a separate popup) was
    # the more direct match for "add a clear history function in the
    # list" as asked.
    n_rows = len(recents) + 1
    visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
    start = max(0, min(app.recents_index - visible // 2, max(0, n_rows - visible)))
    for row_pos, i in enumerate(range(start, min(n_rows, start + visible))):
        y = top + row_pos * row_h
        selected = (i == app.recents_index)
        if i == 0:
            if app._recents_clear_armed:
                label = f"Press A again to clear all {len(recents)} entries"
                fill_rect_rounded(renderer, _sx(10), y, SW - _sx(20), row_h - _sy(4), COL_WARNING)
                color = COL_BG
            else:
                label = "Clear History"
                if selected:
                    fill_rect_rounded(renderer, _sx(10), y, SW - _sx(20), row_h - _sy(4), COL_MENU_SEL_BG)
                color = COL_ACCENT if selected else COL_WARNING
            # v26.07.27.35 BUG FIX (found during a requested font-size
            # bug-check): this render_text call was the only one in the
            # whole function with no _fit_text() safety net -- every
            # sibling label below DOES wrap through it. Measured the
            # real worst case (max Font Size, RECENTS_MAX(50) -- "Press
            # A again to clear all 50 entries") and confirmed it
            # doesn't actually overflow TODAY (511px used of 676px
            # available), so this wasn't a live bug -- but it's a latent
            # one with zero margin for error if RECENTS_MAX ever grows,
            # and every other label in this file gets this protection
            # as a matter of course, so the omission itself was the
            # real inconsistency worth fixing regardless.
            render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, SW - _sx(44)), color,
                        _sx(24), _row_text_y(y, row_h, app.fonts.ui_body, 4))
            continue
        entry = recents[i - 1]
        if selected:
            fill_rect_rounded(renderer, _sx(10), y, SW - _sx(20), row_h - _sy(4), COL_MENU_SEL_BG)
        color = COL_ACCENT if selected else COL_TEXT
        kind_tag = _KIND_LABEL.get(entry.get("kind"), "?")
        rel = _relative_time(entry.get("ts", 0)) or ""
        label = f"[{kind_tag}] {entry.get('title', '(untitled)')}"
        if rel:
            label += f"  ({rel})"
        render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, SW - _sx(44)),
                    color, _sx(24), _row_text_y(y, row_h, app.fonts.ui_body, 4))
    draw_hint(renderer, app.fonts, "UP/DOWN Select   LEFT/RIGHT Jump 10   A Open   B Back")


def draw_bookmarks(renderer, app):
    fill_rect(renderer, 0, 0, SW, SH, COL_BG)
    bms = [b for b in get_bookmarks(app.current_book_path) if b.get("label") != "__lastpos__"]
    render_text(renderer, app.fonts.ui_heading,
                f"BOOKMARKS ({len(bms)}/{MAX_BOOKMARKS_PER_BOOK})", COL_ACCENT, _sx(20), _sy(16))
    # v0.1.131: was a fixed _sy(44), unlike every other list screen which
    # uses the shared _row_h() helper -- at large Font Size settings the
    # fixed height didn't grow with the text, so rows lost their vertical
    # centering (and risked clipping) exactly where it matters most.
    # v26.07.12.15: the "pad=20 + offset 8 = balanced" note that used to
    # live here went stale the moment v0.1.153 dropped _row_h()'s default
    # pad to 14 -- text placement now uses _row_text_y() instead, which
    # computes real centering off the current pad rather than assuming one.
    row_h = _row_h(app.fonts.ui_body)
    top = _sy(70)
    if not bms:
        render_text(renderer, app.fonts.ui_body, "No bookmarks yet. Press START while reading.",
                    COL_DIM, _sx(24), top)
    for i, bm in enumerate(bms):
        y = top + i * row_h
        armed = (i == app._bookmark_delete_confirm_idx)
        if armed:
            fill_rect_rounded(renderer, _sx(10), y, SW - _sx(20), row_h - _sy(4), COL_WARNING)
        elif i == app.bookmarks_index:
            _anim_y = y  # v26.07.17.05: glide removed, instant snap
            fill_rect_rounded(renderer, _sx(10), int(_anim_y), SW - _sx(20), row_h - _sy(4), COL_MENU_SEL_BG)
        color = COL_BG if armed else (COL_ACCENT if i == app.bookmarks_index else COL_TEXT)
        ts = time.strftime("%b %d %H:%M", time.localtime(bm["ts"]))
        label = f"{bm['label'][:45]}  ({ts})"
        if armed:
            label = "Press X again to delete, or B to cancel"
        render_text(renderer, app.fonts.ui_body, label, color, _sx(24), _row_text_y(y, row_h, app.fonts.ui_body, 4))
    draw_hint(renderer, app.fonts, "UP/DOWN Select   L/R/Y Jump 10   A Go   X Delete   B Back")


def draw_storage(renderer, app):
    fill_rect(renderer, 0, 0, SW, SH, COL_BG)
    render_text(renderer, app.fonts.ui_heading, "SETTINGS", COL_ACCENT, _sx(20), _sy(16))

    # v26.07.09.05: this screen used to show a separate "info_lines"
    # block of static text ABOVE the action list (cache size, orphan
    # count, disk-cache ON/OFF, images ON/OFF, open-last-book ON/OFF,
    # backup count+timestamp) -- every one of those duplicated
    # information that's now folded directly into its corresponding
    # action's own label below (same pattern already used for Immersive
    # Mode's "On/Off" suffix and Pre-render's existing progress label).
    # Kaleb's request: the toggle/action row itself should show its own
    # state/stats, not a disconnected line elsewhere on screen. This also
    # directly shrinks the vertical space this screen needs, which is
    # what caused the real v0.1.54 overflow bug (info_lines + action
    # list together running off the bottom of the screen) -- removing
    # the duplicate block helps that, it doesn't just declutter.
    # v26.07.12.19: read from the App-cached stats (refresh_storage_stats())
    # instead of recomputing here -- see App.__init__'s note for why.
    cache_size = app._storage_cache_size_str
    orphan_count = app._storage_orphan_count
    finished_cache_count = app._storage_finished_cache_count
    backups = app._storage_backups
    if backups:
        # filenames are bookmarks_backup_YYYYMMDD_HHMMSS.json
        ts_part = backups[0][len("bookmarks_backup_"):-len(".json")]
        try:
            latest_str = time.strftime("%b %d %H:%M",
                                        time.strptime(ts_part, "%Y%m%d_%H%M%S"))
        except ValueError:
            latest_str = "unknown time"
    else:
        latest_str = None

    theme_backups = app._storage_theme_backups
    if theme_backups:
        # filenames are custom_themes_backup_YYYYMMDD_HHMMSS.json
        ts_part = theme_backups[0][len("custom_themes_backup_"):-len(".json")]
        try:
            latest_theme_str = time.strftime("%b %d %H:%M",
                                              time.strptime(ts_part, "%Y%m%d_%H%M%S"))
        except ValueError:
            latest_theme_str = "unknown time"
    else:
        latest_theme_str = None

    row_h = _row_h(app.fonts.ui_body)
    top = _sy(60)
    action_max_w = SW - _sx(40)
    n_items = len(STORAGE_ACTIONS)
    # v0.1.54: windowed like Library/Chapters/Menu -- this list used to
    # draw every action unconditionally, which ran past the bottom of
    # the screen once info_lines + row_h both grew with Font Size
    # (confirmed via Kaleb's on-device screenshot: "Pre-render Book
    # Images" and "Back" were pushed off-screen with no way to reach
    # them). v26.07.09.05: info_lines is gone now (folded into action
    # labels above), so this has even more headroom than before.
    visible = max(1, (SH - top - _sy(hint_height(app.fonts))) // row_h)
    start = max(0, min(app.storage_index - visible // 2, max(0, n_items - visible)))
    # v26.07.17.16 REAL BUG FIX (Kaleb's screenshot: a blank selectable-
    # looking gap between "Remove Ports Shortcut" and "Help"): the
    # `continue`s below correctly skip DRAWING a hidden row (e.g.
    # "Reinstall Ports Shortcut" when there's nothing to reinstall), but
    # `ry` used to be computed from the raw `idx` into STORAGE_ACTIONS,
    # which still counted every skipped row's height -- so the NEXT
    # visible row after a hidden one still got pushed down by a row_h
    # it never actually drew, leaving a real blank gap on screen (never
    # actually selectable -- navigation already correctly skips hidden
    # rows via _storage_hidden() below -- but visually present and
    # confusing). Fixed with `row_pos`, a separate counter that only
    # advances for rows actually drawn, used for `ry` instead of `idx`.
    # Known minor tradeoff: `visible`/`start` above are still sized
    # against the RAW list (hidden rows included), so if the current
    # scroll window contains a hidden row, one fewer real row than the
    # screen has room for may show -- never a gap, just very rarely one
    # row short of the theoretical max. Not worth a bigger windowing
    # rewrite for a single-row edge case.
    row_pos = 0
    for idx in range(start, min(n_items, start + visible)):
        action = STORAGE_ACTIONS[idx]
        # v0.1.122: checked BEFORE any drawing (highlight box included) --
        # unlike the Library Menu's existing "Discover More" hide, which
        # continues after the highlight box already drew, so a selection
        # landing on a hidden row there paints a blank highlighted rect.
        # Checking first avoids that here.
        if action == "Pre-render Book Images" and native_image is not None and native_image.available:
            continue
        # v26.07.12.14: same pattern as Pre-render above, same reasoning
        # -- native decode makes disk-caching images buy nothing, so
        # don't show a control that wouldn't do anything if toggled.
        # Unlike Pre-render (a one-shot action), this is a persistent
        # SETTING -- hiding it does NOT touch the saved value (see
        # App.__init__'s own comment on this), only whether it's
        # reachable from this screen right now.
        if action == "Toggle Disk Cache (RAM-only mode)" and native_image is not None and native_image.available:
            continue
        # v26.07.20.07: opposite-direction hide, same pattern -- see
        # _storage_hidden()'s own comment for why this one goes the other
        # way (hidden when native_media is ABSENT, not present).
        if action == "Toggle Video Fill Screen" and native_media is None:
            continue
        if action == "Streaming Quality" and native_media is None:
            continue
        if action == "Video Player" and native_media is None:
            continue
        if action == "Audio Player" and native_media is None:
            continue
        # v26.07.14.11: only show this action if there's actually a
        # roms/PORTS shortcut on disk to remove -- same conditional-hide
        # pattern as Pre-render/Disk-Cache above, so the row doesn't sit
        # there as a permanent no-op for people who never got the
        # self-install (e.g. non-standard roms mount) or already removed it.
        if action == "Remove Ports Shortcut" and not os.path.exists(_ports_launcher_path()):
            continue
        # v26.07.14.12: mirror image of the hide above -- only show the
        # reinstall option once someone has actually opted out, so the
        # two rows are mutually exclusive from the person's perspective
        # (never both visible, never both hidden in the normal case).
        if action == "Reinstall Ports Shortcut" and not load_settings().get("ports_shortcut_opted_out"):
            continue
        ry = top + row_pos * row_h
        row_pos += 1
        armed = (idx == app._storage_confirm_idx)
        if armed:
            fill_rect_rounded(renderer, _sx(10), ry, SW - _sx(20), row_h - _sy(4), COL_WARNING)
        elif idx == app.storage_index:
            _anim_y = ry  # v26.07.17.05: glide removed, instant snap
            fill_rect_rounded(renderer, _sx(10), int(_anim_y), SW - _sx(20), row_h - _sy(4), COL_MENU_SEL_BG)
        color = COL_BG if armed else (COL_ACCENT if idx == app.storage_index else COL_TEXT)
        label = action
        if action == "Clear Image Cache":
            if app._storage_book_cache_size_str is not None:
                label = f"Clear Image Cache: {cache_size} total, {app._storage_book_cache_size_str} this book"
            else:
                label = f"Clear Image Cache: {cache_size}"
        elif action == "Clear Cache for Finished Books":
            label = f"Clear Cache for Finished Books: {finished_cache_count} book(s)"
        elif action == "Clean Up Orphaned Bookmarks":
            label = f"Clean Up Orphaned Bookmarks: {orphan_count} deleted book(s)"
        elif action == "Check for Files to Migrate":
            label = "Check for Files to Migrate"
        elif action == "Backup Bookmarks Now":
            label = (f"Backup Bookmarks Now: last {latest_str}" if latest_str
                     else "Backup Bookmarks Now: no backups yet")
        elif action == "Restore Latest Backup":
            label = (f"Restore Latest Backup: {len(backups)} available, latest {latest_str}"
                     if backups else "Restore Latest Backup: none available")
        elif action == "Backup Custom Themes Now":
            label = (f"Backup Custom Themes Now: last {latest_theme_str}" if latest_theme_str
                     else "Backup Custom Themes Now: no backups yet")
        elif action == "Restore Custom Themes Backup":
            label = (f"Restore Custom Themes Backup: {len(theme_backups)} available, latest {latest_theme_str}"
                     if theme_backups else "Restore Custom Themes Backup: none available")
        elif action == "Toggle Disk Cache (RAM-only mode)":
            state = "ON (cached to disk)" if app.disk_cache_enabled else "OFF (RAM-only)"
            label = f"Disk Cache: {state}"
        elif action == "Toggle Images (text-only mode)":
            state = "ON" if app.images_enabled else "OFF (text-only)"
            label = f"Images: {state}"
        elif action == "Toggle Video Fill Screen":
            state = "Fill (stretch, no letterbox)" if app.video_fill_screen else "Fit (preserve aspect ratio)"
            label = f"Video Scaling: {state}"
        elif action == "Streaming Quality":
            label = f"Streaming Quality: {app.video_stream_quality} (downloads stay 480p)"
        elif action == "Video Player":
            label = f"Video Player: {app.video_player_pref.capitalize()}"
        elif action == "Audio Player":
            label = f"Audio Player: {app.audio_player_pref.capitalize()}"
        elif action == "Cycle Image Night Dimming":
            label = f"Image Night Dimming: {IMAGE_DIM_LABELS[app.image_dim_level]}"
        elif action == "Toggle Open Last Book on Launch":
            state = "ON" if app.open_last_book_enabled else "OFF"
            label = f"Open Last Book on Launch: {state}"
        elif action == "Toggle Sound Effects":
            state = "ON" if app.sound_enabled else "OFF"
            label = f"Sound Effects: {state}"
        elif action == "Check for New Categories":
            rel = _relative_time(app._last_new_categories_check_ts) if app._last_new_categories_check_ts else None
            label = (f"Check for New Categories: last checked {rel}" if rel
                     else "Check for New Categories: never checked")
            label += _stale_check_suffix(app._last_new_categories_check_ts, app.staleness_check_days)
        elif action == "Verify Curated Categories":
            rel = _relative_time(app._last_curated_categories_check_ts) \
                if app._last_curated_categories_check_ts else None
            label = (f"Verify Curated Categories: last checked {rel}" if rel
                     else "Verify Curated Categories: never checked")
            label += _stale_check_suffix(app._last_curated_categories_check_ts, app.staleness_check_days)
        elif action == "Check for New Publications":
            rel = _relative_time(app._last_new_publications_check_ts) \
                if app._last_new_publications_check_ts else None
            label = (f"Check for New Publications: last checked {rel}" if rel
                     else "Check for New Publications: never checked")
            label += _stale_check_suffix(app._last_new_publications_check_ts, app.staleness_check_days)
        elif action == "Check Reminder":
            state = f"{app.staleness_check_days}d" if app.staleness_check_days else "Manual Only"
            label = f"Check Reminder: {state}"
        if action == "Pre-render Book Images":
            if app._prerender_active:
                done, total, scanning = app.prerender_progress()
                label = (f"Cancel Pre-render: scanning... {total} found" if scanning
                         else f"Cancel Pre-render: {done}/{total}")
            elif app._prerender_total:
                done, total, _ = app.prerender_progress()
                label = f"Pre-render Book Images: last run {done}/{total}"
        if armed:
            label = "Press A again to confirm, or B to cancel"
        # v26.07.09.14 BUG FIX (Kaleb's report -- selector "not centered"):
        # this used to be a fixed ry + _sy(10) offset regardless of
        # row_h, so as row_h grows with Font Size the text sits closer
        # and closer to the TOP of the highlight box instead of centered
        # in it -- same bug class draw_hint() already fixed properly
        # (v0.1.131) by centering the text block within the full bar
        # height rather than anchoring it to one edge.
        text_h = TTF.TTF_FontHeight(app.fonts.ui_body)
        text_y = ry + max(0, (row_h - _sy(4) - text_h) // 2)
        render_text(renderer, app.fonts.ui_body, _fit_text(app.fonts.ui_body, label, action_max_w),
                    color, _sx(24), text_y)

    draw_scrollbar(renderer, app, SCREEN_STORAGE, SW - _sx(6), top, visible * row_h, n_items, visible, start)

    # v26.07.21.08 BUG FIX (Kaleb's report: toast hidden underneath the
    # hint bar on this screen). Was positioned right after the last
    # visible row (`top + rows*row_h`), which on a full/near-full list
    # lands at or past the hint bar's own top edge -- since the hint
    # bar draws AFTER this and is opaque, it simply covered the toast.
    # Switched to the same bottom-anchored _draw_status_bar() pattern
    # draw_reader()/draw_image_view() already use, which always sits
    # just above the hint bar regardless of list length.
    if app.status_msg and time.time() < app.status_until:
        _draw_status_bar(renderer, app.fonts, app.status_msg, COL_ACCENT,
                          SH - _sy(hint_height(app.fonts)), alpha=app.status_alpha())

    draw_hint(renderer, app.fonts, "UP/DOWN Select   A Confirm   B Back")


# ============================================================
# Main loop
# ============================================================
_PORTS_LAUNCHER_SH = """#!/bin/sh

# HELP: Read EPUB books with full link, footnote, and image support
# ICON: picoreader
# GRID: PicoReader

# v26.07.14.10 BUG FIX (Kaleb's report: quitting PicoReader when launched
# from roms/PORTS froze on the Library screen after the "Exiting..." toast
# -- required a hard reboot, no crash log, no exception -- while the exact
# same quit from Applications worked fine). Root cause confirmed on real
# device: sourcing func.sh and calling SETUP_APP (the Applications-menu
# helper) from a Ports-launched script. Real PortMaster ports never call
# this at all -- they source their own control.txt instead -- so SETUP_APP
# is suspected of leaving Applications-list-specific lifecycle state (a
# lock/PID file) that expects a teardown signal only the Applications list
# ever sends, which a Ports-launched quit never triggers. Confirmed fix on
# real device: drop func.sh/SETUP_APP entirely for this launch path. Exact
# internal mechanism NOT fully verified (GitHub blocked automated browsing
# of MustardOS/internal's script/ folder during troubleshooting) -- this is
# an empirically-confirmed fix, not a fully explained one.
# -----------------------------------------------------------------------------
APP_DIR="/run/muos/storage/application/PicoReader"
cd "$APP_DIR" || exit 1
exec python3 "$APP_DIR/main.py"
"""


def _ports_launcher_path():
    """v26.07.14.11: shared path lookup so the self-install, the removal
    action, and the Storage screen's conditional visibility check all stay
    in sync against exactly one definition -- no risk of the uninstall
    button and the self-install re-creating each other's work out of sync.

    v26.07.14.15 BUG FIX (Kaleb's file-manager screenshot, confirming his
    actual real, working PortMaster .sh files' location): the previous
    guess, /run/muos/storage/roms/PORTS, was wrong on TWO counts --
    (1) wrong base prefix: the real path is under /mnt/union, muOS's
    unified overlay merging both SD cards (SD1 "mmc" + SD2 "sdcard") into
    one view -- this IS the "universal shared roms directory" Kaleb asked
    for, not /run/muos/storage (that prefix is confirmed correct for this
    app's OWN Applications install path, but doesn't extend to content/
    roms the way it was assumed to). (2) wrong casing: the real folder is
    ROMS/Ports (title-case "Ports"), not roms/PORTS (all-caps). This is
    why self-install logged "dir_existed_before=False" every single boot
    with zero effect -- it was faithfully creating a stray, never-scanned
    directory tree at the wrong location instead of ever touching the
    real one. CONFIRMED via direct file-manager inspection, not inferred
    by analogy this time."""
    return "/mnt/union/ROMS/Ports/PicoReader.sh"


def _remove_ports_launcher():
    """v26.07.14.11 (Kaleb's request): deletes roms/PORTS/PicoReader.sh if
    present, for people who want to fully uninstall PicoReader one day --
    Archive Manager's Applications removal doesn't know this file exists
    (it lives outside the Applications folder), so without this it would be
    silently orphaned, pointing at an install directory that no longer
    exists. Returns True if a file was actually removed, False if there
    was nothing to remove. Raises on real OSError -- the Storage screen's
    caller catches this and shows a status message, same fail-soft
    principle as every other action here, just without swallowing silently
    since this one is a direct, deliberate user action worth reporting.

    v26.07.14.12 (Kaleb's follow-up): also persists an opt-out flag in
    settings.json so _self_install_ports_launcher() stops silently
    recreating the file on the very next boot -- without this, "Remove"
    was pointless, since the self-install runs unconditionally every
    launch. See _reinstall_ports_launcher() for the matching opt back in."""
    target = _ports_launcher_path()
    save_settings({"ports_shortcut_opted_out": True})
    if not os.path.exists(target):
        return False
    os.remove(target)
    _boot_log("removed roms/PORTS/PicoReader.sh (user-requested)\n")
    return True


def _reinstall_ports_launcher():
    """v26.07.14.12 (Kaleb's request): the opt back in to
    _remove_ports_launcher()'s opt-out -- clears the settings.json flag
    and immediately writes the launcher, rather than just clearing the
    flag and waiting for the next boot's self-install to notice. Returns
    True/raises exactly like _remove_ports_launcher() so the Storage
    screen caller can handle both the same way."""
    save_settings({"ports_shortcut_opted_out": False})
    return _self_install_ports_launcher(force=True)


def _self_install_ports_launcher(force=False):
    """v26.07.14.09, repair logic added v26.07.14.10: write roms/PORTS/
    PicoReader.sh if it's missing OR out of date, so PicoReader shows up
    under Explore Content > Ports as well as Applications, and anyone who
    already has the old SETUP_APP-calling version (the one with the
    confirmed exit-hang bug -- see _PORTS_LAUNCHER_SH's own comment) gets
    it silently replaced on next launch instead of staying stuck with it
    forever. Compares actual file content, not just existence, so this
    stays correct across any future launcher-script fix too. Fail-soft --
    any error here (path doesn't exist, read-only filesystem, permissions)
    is logged and swallowed, never raised, since this must never be able to
    block a normal app launch. See this function's caller in main() for the
    NEEDS REAL-DEVICE CONFIRMATION note on the path itself (CONFIRMED as of
    v26.07.14.10 -- see that comment).

    v26.07.14.12: respects the settings.json opt-out flag set by
    _remove_ports_launcher() -- without this check, Remove Ports Shortcut
    would get silently undone on the very next launch, since this function
    runs unconditionally at every startup. force=True (only ever passed by
    _reinstall_ports_launcher(), a direct user action) bypasses the flag
    check so opting back in doesn't need a second boot to take effect;
    the normal every-boot call from main() never passes force.

    v26.07.14.14 BUG FIX (Kaleb's report: shortcut never showed up under
    Ports at all, and /tmp/picoreader_crash.log had NO line about it
    whatsoever): this used to bail out silently if roms/PORTS didn't
    resolve as a real directory (os.path.isdir() check, then bare
    `return`) -- isdir() returning False isn't an exception, so even the
    fail-soft except clause below never logged it, which is exactly why
    the log was silent. ORIGINAL GUESS (proven wrong -- Kaleb confirmed he
    already has real PortMaster games installed and working, so roms/
    PORTS does exist on his device): assumed the folder had simply never
    been created. Real cause still UNCONFIRMED -- Kaleb is on a two-SD-
    card setup, so the more likely explanation is that
    /run/muos/storage/roms/PORTS (inferred by analogy to this app's own
    /run/muos/storage/application/PicoReader install path, and to a
    community forum's reference to /run/muos/storage/info/core) simply
    isn't the correct resolved path for his card configuration -- e.g. if
    his real Ports folder lives under whichever SD card muOS's unified
    storage overlay treats differently. Two changes this version: (1)
    creates the directory instead of giving up, in case that ever is the
    real cause on some setup, and (2) ALWAYS logs the exact resolved
    target path and whether the directory existed before this ran --
    unconditionally, on every single call, success or not -- so the next
    real-device test is conclusive instead of another silent no-op."""
    _boot_log(f"roms/PORTS self-install check: target={_ports_launcher_path()} "
               f"dir_existed_before={os.path.isdir(os.path.dirname(_ports_launcher_path()))}\n")
    try:
        # v26.07.14.15: clean up the stray tree the previous WRONG path
        # guess (/run/muos/storage/roms/PORTS) may have created via
        # v26.07.14.14's makedirs call -- that path was never scanned by
        # muOS (confirmed real path is /mnt/union/ROMS/Ports), so anyone
        # who ran that version has an orphaned, harmless-but-pointless
        # empty-ish directory tree sitting on their device. One-time,
        # best-effort, never blocks the real install below on failure.
        _stray_old_path = "/run/muos/storage/roms/PORTS/PicoReader.sh"
        if os.path.exists(_stray_old_path):
            try:
                os.remove(_stray_old_path)
                _boot_log("removed stray old-path file from wrong-path guess\n")
            except Exception:
                pass

        if not force and load_settings().get("ports_shortcut_opted_out"):
            return
        target = _ports_launcher_path()
        ports_dir = os.path.dirname(target)
        os.makedirs(ports_dir, exist_ok=True)
        if os.path.exists(target):
            with open(target, "r") as f:
                if f.read() == _PORTS_LAUNCHER_SH:
                    return  # already current, nothing to do
        with open(target, "w") as f:
            f.write(_PORTS_LAUNCHER_SH)
        os.chmod(target, 0o755)
        _boot_log("self-installed/updated roms/PORTS/PicoReader.sh\n")
    except Exception as e:
        _boot_log(f"roms/PORTS self-install skipped: {e}\n")


def main():
    global SH  # v26.07.16.15: reassigned below for the RG34XX/RG34XX SP
               # native short-height profile; must be declared before
               # any read of SH in this function.
    global DEV_W, DEV_H  # v26.07.20.11: promoted to module scope so
               # video streaming's Fill Screen mode can target the real
               # detected device resolution instead of PicoReader's own
               # SW/SH reading-canvas approximation -- see the module-
               # level DEV_W/DEV_H comment for why that distinction
               # matters here specifically.
    # v26.07.14.09 (Kaleb's request): self-install a roms/PORTS/PicoReader.sh
    # launcher on every startup if it's missing/stale, so PicoReader shows up
    # under Explore Content > Ports (not just Applications) and gets picked
    # up by muOS's normal content-launch/History tracking -- without needing
    # a second manual file drop alongside the .muxapp install. CONFIRMED on
    # real device (v26.07.14.10 session): /run/muos/storage/roms/PORTS is
    # the correct live path, and content launched this way IS picked up by
    # History/last-played, same as any real ROM/port. See
    # _self_install_ports_launcher()'s own docstring for the SETUP_APP
    # exit-hang bug this had to work around (fixed same session).
    _self_install_ports_launcher()

    # v0.1.79: CPython's default GIL switch interval (5ms) turned out not
    # to be tight enough on the real ARM device -- Kaleb confirmed a real
    # background-decode stall (image loading, and worse, whole-book
    # pre-render) still froze ALL input for several seconds even after
    # the v0.1.78 cooperative time.sleep(0) yields added inside
    # mini_jpeg.py's hot loops. Those cooperative yields only offer the
    # GIL up at convenient points; they don't change how urgently
    # CPython actually forces a handoff between offers, which is what
    # setswitchinterval controls. Dropping it to 1ms (from the 5ms
    # default) makes the interpreter force that handoff five times more
    # often, giving the main thread's SDL_PollEvent/render loop far more
    # regular chances to run even while the decode thread is continuously
    # CPU-bound between yield points. This is a global interpreter
    # setting (affects all threads, not just image decode) but the cost
    # is a small constant amount of extra thread-switch bookkeeping --
    # negligible next to a multi-hundred-millisecond JPEG decode.
    sys.setswitchinterval(0.001)

    if SDL.SDL_Init(SDL_INIT_VIDEO | SDL_INIT_JOYSTICK) != 0:
        _boot_log(f"SDL_Init failed: {SDL.SDL_GetError()}\n")
        sys.exit(1)

    # v0.1.148: detect the real device resolution so the app's fixed
    # 720x720 internal canvas can letterbox/pillarbox onto other muOS
    # screens (640x480 RG28XX/RG35XX family, 720x480 RG34XX, 1024x768
    # TrimUI Brick, 1280x720 TrimUI Smart Pro -- confirmed groupings via
    # community.muos.dev). RGCubeXX-H (720x720) keeps the exact original
    # window path (no fullscreen flag, no scaling) so there is zero
    # regression risk on the primary dev device.
    disp_mode = SDL_DisplayMode()
    if SDL.SDL_GetDesktopDisplayMode(0, ctypes.byref(disp_mode)) == 0 and disp_mode.w > 0 and disp_mode.h > 0:
        DEV_W, DEV_H = disp_mode.w, disp_mode.h
    else:
        DEV_W, DEV_H = SW, SH  # detection failed -- fall back to native square

    _boot_log(f"Detected display: {DEV_W}x{DEV_H}\n")

    # v26.07.16.20: CANVAS PROFILE TABLE, replacing the .15-.19 hand-
    # written if/elif chain with one data-driven rule (Kaleb's request:
    # "adapt to ratios without breaking the 720-wide logic"). SW stays
    # hardcoded 720 everywhere, unchanged -- every entry here is just a
    # canvas HEIGHT paired with the aspect ratio it represents. For any
    # detected device, pick whichever canvas height's aspect ratio is
    # numerically CLOSEST to the device's real aspect ratio -- this is
    # the exact reasoning that hand-picked 3:2 (not a shrunk-further
    # 16:9-exact 720x405) for TrimUI Smart Pro in .19, now generalized
    # so any FUTURE device resolution gets a sensible canvas without
    # writing a new branch: SDL_RenderSetLogicalSize's own scale-to-fit
    # already handles the exact-match-vs-scaled-with-bars distinction
    # automatically (scale lands on exactly 1.0, i.e. zero bars, when
    # the device's own aspect ratio exactly equals a table entry's --
    # RG34XX/RG34XX SP, RG28XX/RG35XX/RG40XX, and TrimUI Brick all hit
    # this for free; TrimUI Smart Pro's genuine 16:9-vs-3:2 mismatch
    # still gets left/right bars, same as .19).
    CANVAS_HEIGHT_PROFILES = [
        (720, "1:1  (RGCubeXX-H)"),
        (480, "3:2  (RG34XX/RG34XX SP native; nearest fit for 16:9 -- TrimUI Smart Pro)"),
        (540, "4:3  (TrimUI Brick, RG28XX/RG35XX/RG40XX)"),
    ]

    def _pick_canvas_height(dev_w, dev_h):
        if dev_w <= 0 or dev_h <= 0:
            return SW  # detection garbage -- fall back to the 1:1 square
        dev_ratio = dev_w / dev_h
        best_h, best_diff = SW, None
        for h, _label in CANVAS_HEIGHT_PROFILES:
            diff = abs(dev_ratio - (SW / h))
            if best_diff is None or diff < best_diff:
                best_h, best_diff = h, diff
        return best_h

    if (DEV_W, DEV_H) == (SW, SW):
        # v0.1.148: RGCubeXX-H keeps the EXACT original window path (no
        # fullscreen flag, no scaling) -- zero regression risk on the
        # primary dev device, byte-identical to every version before
        # any of this profile work started.
        SH = SW
        win = SDL.SDL_CreateWindow(b"PicoReader", SDL_WINDOWPOS_CENTERED,
                                    SDL_WINDOWPOS_CENTERED, SW, SH, 0)
    else:
        SH = _pick_canvas_height(DEV_W, DEV_H)
        _boot_log(f"Canvas profile: {SW}x{SH}, window {DEV_W}x{DEV_H} "
                   f"(nearest-aspect match; SDL scale-to-fit adds bars "
                   f"only if the match isn't exact)\n")
        win = SDL.SDL_CreateWindow(b"PicoReader", SDL_WINDOWPOS_CENTERED,
                                    SDL_WINDOWPOS_CENTERED, DEV_W, DEV_H,
                                    SDL_WINDOW_FULLSCREEN_DESKTOP)
    if not win:
        _boot_log(f"SDL_CreateWindow failed: {SDL.SDL_GetError()}\n")
        sys.exit(1)

    # v26.07.16.23 (Kaleb's final call, removing .21/.22): no render
    # scale-quality hint at all. .22's linear-only-for-downscale split
    # was a real, defensible fix for RG28XX/RG35XX/RG40XX's 0.889x
    # scale (nearest-neighbor that close to 1:1 can drop a thin font
    # stroke here and there), but Kaleb weighed it against a flat
    # "keep everything crisp, one simple rule, no per-device branching"
    # and chose consistency -- the downscale effect is subtle at 0.889x
    # (not a dramatic ratio), so the simplicity win outweighs a marginal,
    # possibly-imperceptible improvement. SDL2's own default IS
    # "nearest" already, so simply not calling SDL_SetHint at all
    # reproduces this -- no explicit hint call needed, no
    # SDL_HINT_RENDER_SCALE_QUALITY reference anywhere in this file.
    renderer = SDL.SDL_CreateRenderer(win, -1, 2)
    if not renderer:
        renderer = SDL.SDL_CreateRenderer(win, -1, 1)
    if not renderer:
        _boot_log(f"SDL_CreateRenderer failed: {SDL.SDL_GetError()}\n")
        sys.exit(1)

    # v0.1.148: pin the renderer's logical coordinate space to the app's
    # canvas (SW x SH -- SH picked by the nearest-aspect-match table
    # above, v26.07.16.20). SDL2 itself computes the integer-safe
    # scale-to-fit and centers it, landing on scale=1.0 (zero bars)
    # whenever the device's aspect ratio exactly matches the picked
    # canvas, or adding bars on whichever axis has leftover room
    # otherwise -- none of the app's own layout math (SW/SH/_sx/_sy,
    # used everywhere) has to change.
    SDL.SDL_RenderSetLogicalSize(renderer, SW, SH)

    # v26.07.27.38 (Kaleb's request, video-transition-glitch follow-up):
    # confirmed via Kaleb's real ffplay.log that the fb0 blank/unblank
    # nudge genuinely RUNS every time ("fb0/blank=ok") but doesn't
    # actually fix the leftover-frame glitch between queue videos --
    # meaning the stale content likely isn't in the legacy fbdev
    # framebuffer that sysfs path controls at all, but in a separate
    # DRM/KMS hardware plane ffplay/mpv wrote to directly, which that
    # blank toggle has no reach into. Logging which video driver SDL
    # actually ended up using (kmsdrm/fbdev/x11/other) is the one fact
    # that tells us which mechanism could actually reach whatever's
    # leaving that leftover behind, instead of guessing at a third
    # blind nudge. Cheap, safe, read-only -- can't affect behavior.
    # RESOLVED (Kaleb, v26.07.29 session): the mpv-native-OSD-title
    # approach (dropping PicoReader's own SDL title-card overlay in
    # favor of mpv's --osd-playing-msg, see the "MAJOR FEATURES ADDED"
    # entry higher up) sidestepped the glitch entirely rather than
    # working around it -- confirmed fixed on real hardware.
    _video_driver = SDL.SDL_GetCurrentVideoDriver()
    _video_driver_str = _video_driver.decode("utf-8", errors="replace") if _video_driver else "(unknown)"
    _boot_log(f"SDL video driver in use: {_video_driver_str}\n")
    if native_media is not None:
        native_media._ffplay_log(f"[diag] SDL video driver in use: {_video_driver_str}\n")

    if SDL.SDL_NumJoysticks() > 0:
        SDL.SDL_JoystickOpen(0)

    try:
        app = App(renderer, win)
    except Exception:
        import traceback
        _boot_log("\n--- App() init FAILED ---\n")
        _boot_log(traceback.format_exc())
        _boot_log("--- END ---\n")
        sys.exit(1)

    running = True

    class SDL_KeyboardEvent(ctypes.Structure):
        _fields_ = [("type", ctypes.c_uint32), ("timestamp", ctypes.c_uint32),
                    ("windowID", ctypes.c_uint32), ("state", ctypes.c_ubyte),
                    ("repeat", ctypes.c_ubyte), ("padding2", ctypes.c_ubyte),
                    ("padding3", ctypes.c_ubyte),
                    ("keysym_scancode", ctypes.c_int), ("keysym_sym", ctypes.c_int),
                    ("keysym_mod", ctypes.c_uint16), ("keysym_unused", ctypes.c_uint32)]

    class SDL_JoyHatEvent(ctypes.Structure):
        _fields_ = [("type", ctypes.c_uint32), ("timestamp", ctypes.c_uint32),
                    ("which", ctypes.c_int32), ("hat", ctypes.c_ubyte),
                    ("value", ctypes.c_ubyte), ("padding1", ctypes.c_ubyte),
                    ("padding2", ctypes.c_ubyte)]

    class SDL_JoyAxisEvent(ctypes.Structure):
        # v26.07.20.19: right-stick support. Standard SDL2 layout --
        # value is a SIGNED 16-bit int (range -32768..32767).
        _fields_ = [("type", ctypes.c_uint32), ("timestamp", ctypes.c_uint32),
                    ("which", ctypes.c_int32), ("axis", ctypes.c_ubyte),
                    ("padding1", ctypes.c_ubyte), ("padding2", ctypes.c_ubyte),
                    ("padding3", ctypes.c_ubyte), ("value", ctypes.c_int16),
                    ("padding4", ctypes.c_uint16)]

    class SDL_JoyButtonEvent(ctypes.Structure):
        _fields_ = [("type", ctypes.c_uint32), ("timestamp", ctypes.c_uint32),
                    ("which", ctypes.c_int32), ("button", ctypes.c_ubyte),
                    ("state", ctypes.c_ubyte), ("padding1", ctypes.c_ubyte),
                    ("padding2", ctypes.c_ubyte)]

    ev_buf = (ctypes.c_byte * 56)()
    SDL.SDL_GetTicks.restype = ctypes.c_uint32

    # v0.1.79: input avalanche fix. During a long background-decode
    # stall (see mini_jpeg.py / ImageLoader notes), SDL still queues
    # every button press that happens while the app can't get back to
    # its event loop -- confirmed by Kaleb: mashing B during a hang,
    # thinking it wasn't registering, then having ALL of those presses
    # fire back-to-back the instant it recovered, backing out of the
    # reader -> library -> clean out of the app in one frame. The inner
    # `while True: poll_event()` loop below already drains the whole
    # queue before the next redraw, with no way to tell "just pressed"
    # apart from "queued 2 seconds ago" -- so it acted on all of them as
    # if they'd just happened. Every SDL button/key/hat event carries its
    # own timestamp (SDL_GetTicks() at the moment it was generated), so
    # any event older than STALE_INPUT_MS versus *now* almost certainly
    # queued up during a stall rather than being a deliberate rapid
    # button mash -- drop it instead of acting on it. Doesn't touch
    # legitimate fast double-taps (350ms is generous for that) and
    # doesn't fix the underlying stall itself, but stops one stall from
    # cascading into an accidental app exit.
    STALE_INPUT_MS = 350

    def poll_event():
        if SDL.SDL_PollEvent(ctypes.byref(ev_buf)) == 0:
            return None
        etype = ctypes.cast(ev_buf, ctypes.POINTER(ctypes.c_uint32))[0]
        return etype, ev_buf

    while running:
        if app._pending_link_video is not None:
            # v26.07.20.32: a background thread resolved an in-book video
            # link and handed it off here -- see App._pending_link_video's
            # own comment (in __init__) for the full redesign reasoning.
            # This block does the ACTUAL play_video_source() call + cleanup
            # synchronously on the MAIN thread, structurally identical to
            # play_video_item() (the browse-screen path, which has never
            # shown the leftover-video-frame bug this redesign exists to
            # test/fix) -- no more SDL calls from a background thread
            # anywhere in this app.
            pending = app._pending_link_video
            app._pending_link_video = None
            SDL.SDL_SetRenderDrawColor(app.renderer, 0, 0, 0, 255)
            SDL.SDL_RenderClear(app.renderer)
            SDL.SDL_RenderPresent(app.renderer)
            SDL.SDL_RenderClear(app.renderer)
            SDL.SDL_RenderPresent(app.renderer)
            native_media.maybe_trim_memory(app._clear_text_texture_cache)
            ok, msg = native_media.play_video_source(
                pending["url"], is_local=False, sdl=SDL, joy_a=JOY_A, joy_b=JOY_B,
                joy_l1=JOY_L, joy_r1=JOY_R, joy_l2=JOY_L2, joy_r2=JOY_R2,
                joy_y=JOY_Y, joy_x=JOY_X,
                # v26.07.29.14 BUG FIX: same missing joy_start/joy_select
                # gap as play_video_item()'s call site just above (see
                # that comment for the full root cause) -- this is the
                # in-book-link video path, the other of the two call
                # sites that had never gotten them.
                joy_start=JOY_START, joy_select=JOY_BACK,
                player_pref=app.video_player_pref,
                fill_screen=app.video_fill_screen, screen_w=DEV_W, screen_h=DEV_H)
            native_media._ffplay_log(
                f"[diag] in-book video returned (main thread): ok={ok} msg={msg!r} "
                f"fill_screen={app.video_fill_screen} DEV={DEV_W}x{DEV_H} "
                f"-- about to double-clear\n")
            SDL.SDL_SetRenderDrawColor(app.renderer, 0, 0, 0, 255)
            SDL.SDL_RenderClear(app.renderer)
            SDL.SDL_RenderPresent(app.renderer)
            SDL.SDL_RenderClear(app.renderer)
            SDL.SDL_RenderPresent(app.renderer)
            native_media._ffplay_log("[diag] double-clear complete\n")
            app._nudge_window_after_video()
            native_media._ffplay_log("[diag] window nudge complete\n")
            app.set_status(msg or (f'Finished playing "{pending["title"]}"' if ok
                                    else "Playback failed"), duration=4.0)
            app.dirty = True
            continue
        while True:
            res = poll_event()
            if res is None:
                break
            etype, raw = res
            btn = None
            ev_timestamp = None

            if etype == SDL_QUIT_EV:
                # v26.07.17.19: unconditional flush -- this is a hard OS-
                # level quit (window close), doesn't go through the
                # quit_requested toast path below, so it's the only
                # chance to persist any debounced-but-unwritten setting.
                flush_settings_now()
                flush_pin_finished_now()  # v26.07.17.20: same reasoning
                flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
                running = False
                break
            elif etype == SDL_KEYDOWN_EV:
                kev = ctypes.cast(raw, ctypes.POINTER(SDL_KeyboardEvent))[0]
                ev_timestamp = kev.timestamp
                k = kev.keysym_sym
                if k == SDLK_ESCAPE:
                    flush_settings_now()  # v26.07.17.19: same reasoning as SDL_QUIT_EV above
                    flush_pin_finished_now()  # v26.07.17.20
                    flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
                    running = False
                elif k == SDLK_UP: btn = "UP"
                elif k == SDLK_DOWN: btn = "DOWN"
                elif k == SDLK_LEFT: btn = "LEFT"
                elif k == SDLK_RIGHT: btn = "RIGHT"
                elif k == SDLK_RETURN: btn = "A"
                elif k == SDLK_BACKSPACE: btn = "B"
                elif k == SDLK_TAB: btn = "X"
                elif k == SDLK_EQUALS: btn = "R"
                elif k == SDLK_MINUS: btn = "L"
            elif etype == SDL_JOYHATMOTION_EV:
                hev = ctypes.cast(raw, ctypes.POINTER(SDL_JoyHatEvent))[0]
                ev_timestamp = hev.timestamp
                hv = hev.value
                if hv & SDL_HAT_UP: btn = "UP"
                elif hv & SDL_HAT_DOWN: btn = "DOWN"
                elif hv & SDL_HAT_LEFT: btn = "LEFT"
                elif hv & SDL_HAT_RIGHT: btn = "RIGHT"
            elif etype == SDL_JOYAXISMOTION_EV:
                # Y axis mirrors L/R (page turn), X axis mirrors L2/R2
                # (chapter nav). Edge-triggered like the D-pad's own hat
                # events -- fires ONCE when the axis crosses
                # AXIS_DEADZONE in a direction, then requires it to pass
                # back through center before firing again. No repeat-
                # while-held (same "one push, one action" feel the
                # D-pad already has, and keeps this purely event-driven
                # -- no new per-frame timing loop). Y axis sign
                # convention: negative = up (SDL/muOS standard,
                # confirmed via controller_ref.txt's leftx/lefty/rightx/
                # righty layout) -- up fires R (next page), down fires L
                # (previous page). X axis: right fires R2 (next
                # chapter), left fires L2 (previous), matching this
                # app's existing L2=previous/R2=next convention.
                aev = ctypes.cast(raw, ctypes.POINTER(SDL_JoyAxisEvent))[0]
                ev_timestamp = aev.timestamp
                val = aev.value
                if aev.axis == JOY_AXIS_RY:
                    new_dir = 1 if val > AXIS_DEADZONE else (-1 if val < -AXIS_DEADZONE else 0)
                    if new_dir != 0 and app._axis_ry_dir == 0:
                        btn = "L" if new_dir == 1 else "R"
                    app._axis_ry_dir = new_dir
                elif aev.axis == JOY_AXIS_RX:
                    new_dir = 1 if val > AXIS_DEADZONE else (-1 if val < -AXIS_DEADZONE else 0)
                    if new_dir != 0 and app._axis_rx_dir == 0:
                        btn = "R2" if new_dir == 1 else "L2"
                    app._axis_rx_dir = new_dir
                # v26.07.21.08 (Kaleb's request): left stick, same
                # mapping/behavior as right stick above.
                elif aev.axis == JOY_AXIS_LY:
                    new_dir = 1 if val > AXIS_DEADZONE else (-1 if val < -AXIS_DEADZONE else 0)
                    if new_dir != 0 and app._axis_ly_dir == 0:
                        btn = "L" if new_dir == 1 else "R"
                    app._axis_ly_dir = new_dir
                elif aev.axis == JOY_AXIS_LX:
                    new_dir = 1 if val > AXIS_DEADZONE else (-1 if val < -AXIS_DEADZONE else 0)
                    if new_dir != 0 and app._axis_lx_dir == 0:
                        btn = "R2" if new_dir == 1 else "L2"
                    app._axis_lx_dir = new_dir
            elif etype == SDL_JOYBUTTONDOWN_EV:
                bev = ctypes.cast(raw, ctypes.POINTER(SDL_JoyButtonEvent))[0]
                ev_timestamp = bev.timestamp
                b = bev.button
                if b == JOY_A: btn = "A"
                elif b == JOY_B: btn = "B"
                elif b == JOY_X: btn = "X"
                elif b == JOY_Y: btn = "Y"
                elif b == JOY_L: btn = "L"
                elif b == JOY_R: btn = "R"
                elif b == JOY_L2: btn = "L2"
                elif b == JOY_R2: btn = "R2"
                elif b == JOY_START: btn = "START"
                elif b == JOY_BACK: btn = "SELECT"

            if btn and ev_timestamp is not None:
                # v0.1.79: uint32-wraparound-safe "how old is this event"
                age_ms = (SDL.SDL_GetTicks() - ev_timestamp) & 0xFFFFFFFF
                if age_ms > STALE_INPUT_MS:
                    btn = None  # drop it -- queued during a stall, not a live press

            if btn:
                app.dirty = True
                # v26.07.14.03 (Kaleb's request, adaptive/dynamic budget
                # for the cold-wrap slice size -- see
                # _ensure_page_built()'s cold-wrap branch): records the
                # moment of any REAL button press, so the wrap step size
                # can ramp back down to small/responsive immediately the
                # instant input happens, rather than staying on big
                # slices for the rest of a build just because the old
                # fixed initial-responsive-window already elapsed.
                app._last_input_time = time.perf_counter()
                # v26.07.10.22: arm the extreme-page-queue drain gate on
                # L2/R2, disarm it on any other button -- see
                # App._chapter_nav_pending's docstring (App.__init__).
                # Deliberately not touched at all when btn is falsy
                # (no press this frame) -- idle time must never arm or
                # disarm it, only real navigation does.
                if btn in ("L2", "R2"):
                    app._chapter_nav_pending = True
                else:
                    app._chapter_nav_pending = False
                handle_button(app, btn, renderer=renderer)
                if app.quit_requested:
                    # v26.07.17.19: unconditional flush -- this is a real
                    # quit path (Library B-to-quit or Reader menu's
                    # "Exit App"), same reasoning as SDL_QUIT_EV/ESCAPE
                    # above. Placed right at the top of this block so it
                    # happens even if something below it hiccups.
                    flush_settings_now()
                    flush_pin_finished_now()  # v26.07.17.20
                    flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
                    # v26.07.10.04: brief exit toast (Kaleb's request)
                    # instead of the window just vanishing the instant B
                    # is pressed.
                    # v26.07.12.20 BUG FIX: this used to hardcode
                    # draw_library() on the documented assumption that
                    # quit_requested was ONLY ever set from SCREEN_LIBRARY's
                    # B handler -- true until this version added "Exit
                    # App" to the Reader popup menu. Left as-is, exiting
                    # from the Reader menu would have flashed the Library
                    # screen behind the toast instead of the book you were
                    # actually reading. Now picks whichever of the two
                    # real quit sources is current; draw_reader() is also
                    # correct for SCREEN_MENU (the popup is drawn ON TOP
                    # of draw_reader() -- see draw_menu()'s own first
                    # line -- so showing just the reader underneath,
                    # without the now-closing popup, is the right visual).
                    # v26.07.27.02: set_status() moved to AFTER the
                    # background draw call below (was here) -- see that
                    # comment for why calling it before the background
                    # draw caused the real "toast shows twice stacked" bug.
                    SDL.SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255)
                    SDL.SDL_RenderClear(renderer)
                    # v26.07.27.02 REAL BUG FIX (Kaleb's report: "toast
                    # sometimes shows twice stacked"). Root cause: draw_
                    # library()/draw_reader()/draw_download_browse() (all
                    # three of the backgrounds this block can pick) ALSO
                    # draw the status bar themselves, as part of their own
                    # normal per-frame code (same "if app.status_msg and
                    # time.time() < app.status_until: _draw_status_bar(...)"
                    # pattern every screen uses) -- and since set_status()
                    # for the exit toast was called BEFORE this dispatch,
                    # that internal draw was ALSO rendering the exact same
                    # "Exiting Pico Reader" text, at the exact same
                    # position, underneath the forced-alpha redraw a few
                    # lines below. Two overlapping renders of the same
                    # message is exactly what "stacked twice" describes --
                    # the v26.07.16.34 fix below only ever forced the
                    # SECOND (outer) draw's alpha to 255 without realizing
                    # a first (inner) draw of the same text already
                    # happened. Fixed by blanking app.status_msg for the
                    # duration of this background draw call ONLY (nothing
                    # else reads status_msg between here and the
                    # set_status() call right after), so the internal
                    # per-screen status-bar draw has nothing to render
                    # this one frame; the real exit text is set
                    # immediately after, for our own single forced draw
                    # only. draw_download_video_sources()/
                    # draw_download_audio_sources() never had this problem
                    # to begin with (confirmed: neither draws a status bar
                    # internally at all) -- this fix is a safe no-op for
                    # those two, not a risk of a NEW regression there.
                    app.status_msg = None
                    if app.screen == SCREEN_LIBRARY:
                        draw_library(renderer, app)
                    elif app.screen == SCREEN_DOWNLOAD_BROWSE_MENU:
                        draw_download_browse(renderer, app)
                    elif app.screen == SCREEN_DOWNLOAD_QUICK_MENU:
                        if app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_SOURCES:
                            draw_download_sources(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_MAIN:
                            draw_download_main(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_CATEGORIES:
                            draw_download_categories(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_VIDEO_SOURCES:
                            draw_download_video_sources(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_VIDEO_SERIES:
                            draw_download_video_series(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_AUDIO_SOURCES:
                            draw_download_audio_sources(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_AUDIO_GROUP:
                            draw_download_audio_group(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_AUDIO_BOOKS:
                            draw_download_audio_books(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_AUDIO_ISSUES:
                            draw_download_audio_issues(renderer, app)
                        elif app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_PINNED:
                            draw_download_pinned(renderer, app)
                        else:
                            draw_reader(renderer, app)  # defensive fallback
                    else:
                        draw_reader(renderer, app)
                    app.set_status(f"Exiting Pico Reader {FACE_DONE}", duration=EXIT_TOAST_SECONDS)
                    # v26.07.16.34 BUG FIX (Kaleb's report -- "no text in
                    # the overlay" when exiting): the NORMAL per-frame
                    # status-bar alpha (app.status_alpha()) fades in over
                    # 120ms from the moment set_status() was called --
                    # since this whole block is a single forced frame with
                    # no later frame for that fade-in to complete on,
                    # drawing at the real fade alpha here would render
                    # fully (or almost fully) transparent. Force alpha=255
                    # for this one draw instead -- the only status-bar
                    # draw for this frame now, per the fix just above.
                    _draw_status_bar(renderer, app.fonts, app.status_msg, COL_ACCENT,
                                      SH - _sy(hint_height(app.fonts)), alpha=255)
                    SDL.SDL_RenderPresent(renderer)
                    SDL.SDL_Delay(int(EXIT_TOAST_SECONDS * 1000))
                    running = False
                    break

        need_redraw = app.dirty
        _build_only_redraw = False
        if not need_redraw and app.screen == SCREEN_SPLASH:
            need_redraw = True  # must animate every frame, no button press to wait for
        if not need_redraw and app.screen == SCREEN_READER:
            # v26.07.13.19 CRITICAL BUG FIX (Kaleb's report): without
            # this, a page's progressive wrap/warm-load/background-
            # prerender NEVER advanced unless a button press happened to
            # force a redraw that frame -- need_redraw = app.dirty only
            # becomes True on an actual input event or state change, and
            # NOTHING about a chunk step itself marks the app dirty. So a
            # person just sitting on a loading page, pressing nothing,
            # saw the %-progress marker never move at all; it only crept
            # forward when button-mashing happened to force enough
            # redraws -- exactly matching Kaleb's report of "~1% per
            # 3-6 button presses" and pages that would never finish
            # loading if left alone. This is the same class of gap
            # already handled for images two lines below
            # (has_pending_image_updates()) -- extending it to cover the
            # wrap/warm-load/bg-prerender states this session added.
            #
            # Scoped to the CURRENTLY-VIEWED page's own build (live_wrap_
            # key/live_warmload_key matching (current_file, size_index))
            # plus the background queue (_bg_wrap_state) -- NOT a blanket
            # "always redraw on the reader screen", so this stops forcing
            # extra frames the instant nothing is left to build, exactly
            # like Kaleb asked ("make sure the idle checker is stopped
            # so it doesn't cause lag").
            _wrap_key_for_redraw = (app.state.current_file, app.fonts.size_index)
            need_redraw = (
                app._live_wrap_key == _wrap_key_for_redraw
                or app._live_warmload_key == _wrap_key_for_redraw
                or app._bg_wrap_state is not None
            )
            # v26.07.13.20: this redraw is happening ONLY because a
            # build is active -- nothing the person did caused it. Marks
            # it so the throttle below can tell "must render because of
            # real input/other reasons" apart from "just keeping the
            # build moving" -- see advance_progressive_builds()'s
            # docstring for why that distinction matters.
            _build_only_redraw = need_redraw
        if not need_redraw and app.screen == SCREEN_READER:
            need_redraw = app.has_pending_image_updates()
        if not need_redraw and app.screen == SCREEN_IMAGE_VIEW and app._imgview_span is not None:
            snap = app.image_loader.get_status_snapshot(app._img_key(app._imgview_span.src))
            need_redraw = snap["result"] is None or snap["result"] == "loading" or snap["is_upgrading"]
        if not need_redraw and app.screen == SCREEN_DOWNLOAD_BROWSE:
            need_redraw = app.dl_loading or app._dl_downloading_idx is not None
        if not need_redraw and app.screen == SCREEN_TEXT_ENTRY:
            need_redraw = app.te_checking
        if not need_redraw and app.screen == SCREEN_STORAGE:
            need_redraw = app._prerender_active
        if not need_redraw and app.status_msg and time.time() < app.status_until:
            need_redraw = True
        if not need_redraw and _THEME_TRANS_FROM is not None:
            need_redraw = True  # v26.07.16.07: keep redrawing every
                                  # frame while the theme color slider
                                  # transition is in progress
        # v26.07.21.20 (considered, then reverted -- Kaleb's call,
        # "maybe it shouldn't refresh on timer, what is more simple"):
        # briefly forced a periodic redraw here so the popup Menu clock
        # would keep ticking even while sitting fully idle (no button
        # presses). Correct in principle but not worth the complexity
        # it dragged in -- simpler and genuinely lower-CPU to do
        # nothing here at all. See maybe_refresh_clock()'s own comment
        # for the final, much simpler design this settled on.

        if need_redraw and _build_only_redraw and \
                (time.time() - app._last_build_render_time) < READER_BUILD_RENDER_THROTTLE:
            # v26.07.13.20 (Kaleb's report: real device total cold-build
            # time, 4:17, far worse than the ~50s dev-hardware-scaled
            # estimate -- suspected cause: continuous 60fps FULL
            # rendering during the entire build, competing with the
            # wrap's own time budget). Advance the build's actual state
            # every single iteration regardless (unthrottled -- this is
            # the real work, never slowed down), but only pay for a full
            # visible render+present a few times a second instead of
            # every iteration. See advance_progressive_builds()'s
            # docstring for the full reasoning.
            app.advance_progressive_builds(renderer)
            # v26.07.13.26 BUG FIX (Kaleb's report: a build reaching
            # ~100% doesn't visibly finish -- the "N%" toast just stays
            # frozen on screen -- until a button is pressed). Same root
            # cause as v26.07.13.25's fix: once the build actually
            # completes INSIDE the call just above (self._page_cache_key
            # now matches the page being viewed), the build-in-progress
            # condition that's been forcing redraws goes false on the
            # very next check -- so nothing ever forces one more real,
            # visible render to replace the stale mid-build toast with
            # the actual completed page. Detect that exact transition
            # here and fall through to a real render THIS frame instead
            # of skipping it, rather than leaving the last throttled
            # frame's now-stale content on screen indefinitely.
            if app._page_cache_key != app.state.current_file:
                time.sleep(0.001)
                continue

        if need_redraw:
            _tick_theme_transition()  # v26.07.16.07: interpolate COL_*
                                        # globals BEFORE any draw_*() this
                                        # frame reads them
            if _build_only_redraw:
                app._last_build_render_time = time.time()
            # v0.1.83 fix: clear dirty BEFORE drawing, not after. The old
            # order (draw, then app.dirty=False) raced with the ImageLoader
            # worker thread's on_update() callback (setattr(self,"dirty",
            # True), fired the instant a background decode lands -- see
            # ImageLoader._worker_loop()). With native_jpeg's near-instant
            # decode, a VISIBLE-priority image can finish decoding WHILE
            # this exact frame is still being drawn (the frame started out
            # drawing the "Loading image..." placeholder, unaware the
            # result would land a moment later on another thread). If
            # on_update() set dirty=True mid-draw, the old `app.dirty =
            # False` at the end of this block silently clobbered it, and
            # has_pending_image_updates() no longer reported anything
            # pending (the decode was already done) -- so the render loop
            # went idle with the completed image never actually painted,
            # requiring an unrelated button press (which force-sets
            # dirty=True) to finally show it. Root cause of "first cover
            # image doesn't appear until L1/R1/dpad" (Kaleb) -- present
            # with mini_jpeg too but rare there; native's speed makes the
            # race land almost every time. Fix: snapshot-and-clear BEFORE
            # drawing, so any dirty=True set mid-draw by the worker thread
            # survives into the next loop iteration -- worst case one
            # harmless extra redraw.
            app.dirty = False

            # v0.1.148: full-target clear (not just the 720x720 logical
            # viewport) so any pillarbox/letterbox bars on non-square
            # devices are actually painted black every frame -- SDL_Render
            # Clear() clears the whole physical render target regardless
            # of SDL_RenderSetLogicalSize, while every draw_* call below
            # only ever touches the scaled 720x720 viewport. On the
            # CubeXX-H (no bars) this is a harmless redundant fill, since
            # every screen already paints its own full-canvas background.
            SDL.SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255)
            SDL.SDL_RenderClear(renderer)

            if app.screen == SCREEN_SPLASH:
                draw_splash(renderer, app)
            elif app.screen == SCREEN_LIBRARY:
                draw_library(renderer, app)
            elif app.screen == SCREEN_READER:
                draw_reader(renderer, app)
            elif app.screen == SCREEN_MENU:
                draw_menu(renderer, app)
            elif app.screen == SCREEN_TOC:
                draw_toc(renderer, app)
            elif app.screen == SCREEN_BOOKMARKS:
                draw_bookmarks(renderer, app)
            elif app.screen == SCREEN_RECENTLY_PLAYED:
                draw_recently_played(renderer, app)
            elif app.screen == SCREEN_STORAGE:
                draw_storage(renderer, app)
            elif app.screen == SCREEN_LIBRARY_MENU:
                draw_library_menu(renderer, app)
            elif app.screen == SCREEN_EDIT_LIBRARY_MENU:
                draw_edit_library_menu(renderer, app)
            elif app.screen == SCREEN_LIBRARY_DELETE_FOLDER:
                draw_library_delete_folder(renderer, app)
            elif app.screen == SCREEN_LIBRARY_MOVE_FOLDER:
                draw_library_move_folder(renderer, app)
            elif app.screen == SCREEN_THEME_MENU:
                draw_theme_menu(renderer, app)
            elif app.screen == SCREEN_VIDEO_SETTINGS:
                draw_video_settings(renderer, app)
            elif app.screen == SCREEN_THEME_SELECT:
                draw_theme_select(renderer, app)
            elif app.screen == SCREEN_LISTEN_AUDIO_VARIANT:
                draw_listen_audio_variant(renderer, app)
            elif app.screen == SCREEN_TEXT_ENTRY:
                draw_text_entry(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_SOURCES:
                draw_download_sources(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_PINNED:
                draw_download_pinned(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_MAIN:
                draw_download_main(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_CATEGORIES:
                draw_download_categories(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_VIDEO_SOURCES:
                draw_download_video_sources(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_AUDIO_SOURCES:
                draw_download_audio_sources(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_AUDIO_GROUP:
                draw_download_audio_group(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_AUDIO_BOOKS:
                draw_download_audio_books(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_AUDIO_ISSUES:
                draw_download_audio_issues(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_VIDEO_SERIES:
                draw_download_video_series(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_BROWSE:
                draw_download_browse(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_QUICK_MENU:
                draw_download_quick_menu(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_BROWSE_MENU:
                # v26.07.23.23 BUG FIX (Kaleb's report: "pressing X does
                # nothing, no pop up menu" / "the pop up is black
                # screen"): draw_download_browse_menu() has existed
                # since this popup menu system was first built
                # (v26.07.21.42, well before this session) and the
                # button handler correctly sets app.screen to this
                # value on X -- but the render dispatch itself never
                # had a matching branch to actually CALL the draw
                # function. Every screen this popup was ever supposed
                # to cover (any JW or Gutenberg item-browse list) was
                # affected identically: pressing X changed the screen
                # state correctly, but nothing ever got drawn for it,
                # leaving whatever the base clear color is (black) with
                # nothing painted on top -- indistinguishable from a
                # crash without checking process state, exactly
                # matching what Kaleb saw. This is why none of this
                # session's own testing ever caught it: every menu-
                # content/dispatch test exercised the LOGIC in
                # isolation (which items appear, what pressing A does),
                # never the actual SDL render call chain, since real
                # SDL rendering can't run in this sandbox at all.
                draw_download_browse_menu(renderer, app)
            elif app.screen == SCREEN_DOWNLOAD_HELP:
                draw_download_help(renderer, app)
            elif app.screen == SCREEN_LICENSES:
                draw_licenses(renderer, app)
            elif app.screen == SCREEN_HELP:
                draw_app_help(renderer, app)
            elif app.screen == SCREEN_AV_HELP:
                draw_av_help(renderer, app)
            elif app.screen == SCREEN_IMAGE_VIEW:
                draw_image_view(renderer, app)

            # v0.1.131: BMO-style outer screen frame -- always last, after
            # every screen's own drawing, so it can't be forgotten on any
            # individual screen (see _draw_screen_frame() docstring).
            # v26.07.09.14: bottom_radius scaled to the CURRENT hint bar
            # height so its fixed-size corner mask doesn't disproportionately
            # dominate a short hint bar at small Font Size steps -- see
            # _draw_screen_frame()'s docstring for the full story.
            _bottom_radius = min(SCREEN_FRAME_RADIUS, _sy(hint_height(app.fonts)) // 2)
            _draw_screen_frame(renderer, bottom_radius=_bottom_radius)

            SDL.SDL_RenderPresent(renderer)
            time.sleep(0.016)
        else:
            # nothing to draw -- sleep longer to save CPU/battery while idle
            time.sleep(0.05)

    if app.current_book_path:
        app.save_progress()
        flush_pin_finished_now()  # v26.07.17.20: book-close checkpoint
        flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
    SDL.SDL_Quit()


def handle_button(app, btn, body_h_px=None, renderer=None):
    # v26.07.28.20 (Kaleb's request: cycling clarity -- Theme +/- now
    # also reads _DRAFT_THEME/_DRAFT_REPLACE_NAME to label an unsaved
    # regenerate draft, on top of the SCREEN_THEME_SELECT branch further
    # down that already needed to WRITE them). Python requires a
    # function-wide `global` declaration to appear before ANY use of
    # the name in that function, not just before the first assignment --
    # declared once here, at the top, rather than repeated/scattered at
    # each branch that touches them.
    global _DRAFT_THEME, _DRAFT_REPLACE_NAME
    # v26.07.16.01: single choke point for UI sound effects -- see
    # SND_BTN_MAP's docstring (near SoundEngine) for why this is a flat
    # button->sound table rather than instrumented per screen branch.
    _snd = SND_BTN_MAP.get(btn)
    if _snd:
        # v26.08.05.26 BUG FIX (Kaleb's report: "audio not in sync on
        # the opening main title splash"): the intro theme's leftover
        # tail used to get cut off as a side effect of play()'s old
        # blanket clear-before-queue (removed in v26.08.05.25 to fix a
        # SEPARATE keyboard-sound bug -- see SoundEngine.play()'s
        # docstring). Without that side effect, skipping the splash
        # left the rest of the ~1.5s intro theme still queued, so it
        # kept playing audibly for up to a second or so AFTER the
        # screen had already cut to Library/Reader -- heard as the
        # splash "audio not syncing" with what's on screen. Fixed with
        # a narrowly-targeted stop() here (clears the queue) BEFORE
        # queueing this button's own confirm/back cue, only for the
        # splash-skip case specifically -- every other screen/button
        # still just queues normally, so the keyboard fix is untouched.
        if app.screen == SCREEN_SPLASH and btn in ("START", "A", "B"):
            app.stop_sound()
        app.play_sound(_snd)
    # body_h_px param kept for call-site compatibility but no longer used
    # -- v0.1.86: replaced with _reader_body_layout(), the same formula
    # draw_reader() uses, so the two can never disagree about body_rows
    # again. See _reader_body_layout()'s docstring for the bug this fixes.
    _body_top, line_h, body_rows = _reader_body_layout(app.fonts, app.immersive_mode)

    if app.screen == SCREEN_SPLASH:
        # v26.07.10.06: START/A/B all skip straight to the real
        # destination (Kaleb's request) -- same target draw_splash()
        # itself hands off to once its timer runs out, just triggered
        # early instead of waiting.
        if btn in ("START", "A", "B"):
            app.screen = app._splash_dest_screen
        return

    if app.screen == SCREEN_LIBRARY:
        # v26.07.27.43 (Kaleb's request: real folder navigation, like a
        # file manager). Combined index space.
        # v26.07.28.09 BUG FIX (Kaleb's report: pinned books were
        # showing BELOW subfolders in Folders filter -- every other
        # filter already puts pinned first via sort_library(), but
        # subfolder rows always drew before ANY book row here,
        # including pinned ones). Combined index is now three segments
        # in order: pinned books, subfolder rows, everything else --
        # n_pinned is 0 for every other filter (nothing there is ever
        # split out separately), so this is a pure no-op everywhere
        # except Folders; sort_library() already guarantees app.books'
        # first n_pinned entries ARE the pinned ones, in order, so no
        # extra sorting is needed here, just correct index math.
        n_subfolders = len(app.lib_subfolders)
        n_pinned = sum(1 for b in app.books if b["relpath"] in app.pinned)
        n = n_subfolders + len(app.books)  # total row count is unaffected by row ORDER
        # v26.07.28.02: gated on Filter == "folders" too -- lib_current_folder
        # is deliberately preserved across filter switches (so switching
        # back to Folders returns to where you were browsing), but B
        # must only mean "go up a level" while Folders is the active
        # filter; every other filter is the flat whole-library view, so
        # B there always means the normal quit-app action.
        in_folder = app.lib_filter_mode == "folders" and bool(app.lib_current_folder)

        def _selected_is_folder():
            return n_pinned <= app.lib_index < n_pinned + n_subfolders

        def _selected_book():
            idx = app.lib_index
            if idx < n_pinned:
                return app.books[idx] if idx < len(app.books) else None
            if idx >= n_pinned + n_subfolders:
                bi = idx - n_subfolders
                if 0 <= bi < len(app.books):
                    return app.books[bi]
            return None

        if btn == "UP":
            app.lib_index = (app.lib_index - 1) % n if n else 0
            _note_scroll_activity(app, SCREEN_LIBRARY)
        elif btn == "DOWN":
            app.lib_index = (app.lib_index + 1) % n if n else 0
            _note_scroll_activity(app, SCREEN_LIBRARY)
        elif btn == "Y":
            app.cycle_sort_mode()
        elif btn == "LEFT" and n:
            # v0.1.110: quick-scroll -- D-pad LEFT/RIGHT jump 10 rows at a
            # time, same convention as Chapters/Bookmarks' L/R. Clamps
            # rather than wraps, so a long library doesn't quietly loop
            # you back to the opposite end.
            app.lib_index = max(0, app.lib_index - 10)
        elif btn == "RIGHT" and n:
            app.lib_index = min(n - 1, app.lib_index + 10)
        elif btn == "X":
            # v26.07.12.05: swapped with START (Kaleb's request, after
            # real testing) -- X now opens the Library menu here, matching
            # X's "open menu" meaning in the Reader (see MENU screen's
            # docstring: "opened with X or Y"). Previously X was pin/unpin
            # and START opened this menu, which put two DIFFERENT "open a
            # menu" buttons in play across the two screens (X in Reader,
            # START in Library) -- confusing after enough real use, and
            # also collided conceptually with START's Reader meaning
            # ("set a bookmark", i.e. mark THIS one) once Kaleb noticed
            # pin/unpin is the exact same kind of action as a bookmark --
            # both mean "mark this book/position as one I care about".
            app.lib_menu_index = 0
            # capture whichever book was highlighted right now -- Delete
            # Book in the menu always targets this, not whatever's
            # highlighted once inside the menu (there's no book list
            # shown there). v26.07.27.43: None if a folder row is
            # currently highlighted instead of a book -- Delete Book's
            # own handler already no-ops gracefully on a missing target,
            # same as an empty library.
            app._menu_target_book = _selected_book()
            app._menu_delete_armed = False
            app.screen = SCREEN_LIBRARY_MENU
            app.refresh_status_indicators()
        elif btn == "A" and n:
            if _selected_is_folder():
                # v26.07.27.43: navigate INTO the highlighted subfolder --
                # same os.path.join()/os.sep convention scan_library()
                # already uses for the "folder" field on each book, so
                # this always matches what a book's own folder field
                # says once you're inside it.
                # v26.07.28.09: subfolder rows now start AFTER the
                # pinned-book segment (see _selected_is_folder()'s own
                # comment above) -- offset by n_pinned, not a bare index.
                folder_name = app.lib_subfolders[app.lib_index - n_pinned]
                app.lib_current_folder = (os.path.join(app.lib_current_folder, folder_name)
                                           if app.lib_current_folder else folder_name)
                app.lib_index = 0
                # v26.07.28.10: a selection made in one folder shouldn't
                # silently carry into a completely different one -- see
                # self.lib_selected's own docstring in App.__init__.
                app.lib_selected.clear()
                app._apply_library_view()
            else:
                book = _selected_book()
                if book:
                    app.open_book(book)
        elif btn == "R2":
            # v26.07.28.10 (Kaleb's request: multi-select for Move to
            # Folder -- decided in favor of a direct in-list toggle over
            # a Library-Menu-gated "enter multi-select mode" step, since
            # the latter would add a whole extra mode flag with its own
            # clearing/edge-case questions on top of the exact same
            # underlying selection set, for zero reduction in actual
            # complexity -- plus more steps for what should be a fast,
            # frequent action). No-ops on a folder row (folders aren't
            # move targets themselves) and on an empty list, same guard
            # shape as every other book-only action here.
            book = _selected_book()
            if book:
                key = book["relpath"]
                if key in app.lib_selected:
                    app.lib_selected.discard(key)
                else:
                    app.lib_selected.add(key)
        elif btn == "SELECT":
            # v26.07.27.25 (Kaleb's request, download-button-consistency
            # follow-up): SELECT here used to be the Finished/Unfinished
            # toggle (v0.1.117), but "Mark Finished/Unfinished" already
            # exists as its own Library Menu row (X -> Mark Finished/
            # Unfinished) and does the exact same thing -- SELECT was a
            # pure redundant shortcut, not a unique feature, so freeing
            # it up cost nothing. Filter now gets the same "quick one-
            # press cycle" hotkey treatment Y already gives Sort, instead
            # of only being reachable through X -> Menu -> Filter: Cycle.
            #
            # v26.07.28.06 BUG FIX (Kaleb's report: SELECT wasn't
            # reaching Folder mode). Root cause: this required
            # `app.books` to be non-empty just to register the
            # keypress at all -- Y's own Sort-cycle right above has NO
            # such guard. Any filter with zero matching items (Finished
            # with nothing finished yet, Pinned with nothing pinned, or
            # Folders while browsing a subfolder that only has
            # sub-subfolders and no direct books) silently ate every
            # SELECT press, trapping the cycle right there with no way
            # to advance to whatever came next -- which explains landing
            # on Folders specifically, since it's the last entry in
            # LIBRARY_FILTER_MODES and Pinned (right before it) is
            # exactly the kind of filter that's often legitimately
            # empty. Guard removed entirely, matching Y's unconditional
            # pattern -- cycling the FILTER should never depend on
            # whether the CURRENT filter happens to have any items.
            app.cycle_filter_mode()
            app.set_status(f"Filter: {LIBRARY_FILTER_LABELS[app.lib_filter_mode]}")
        elif btn == "B":
            if in_folder:
                # v26.07.27.43: go UP one folder level instead of
                # quitting, same "Back means go up, not out" convention
                # every other screen in this app already follows -- only
                # the ROOT level still means Quit (unchanged below).
                parent = os.path.dirname(app.lib_current_folder.rstrip(os.sep))
                app.lib_current_folder = parent
                app.lib_index = 0
                # v26.07.28.10: same reasoning as the A/folder-enter
                # branch above -- selection shouldn't carry between
                # different folders.
                app.lib_selected.clear()
                app._apply_library_view()
            else:
                app.play_sound("error")  # v26.07.16.02 (Kaleb's request):
                                          # the "wonk" sound doubles as the
                                          # exit-app cue -- distinct/final-
                                          # feeling without needing a new
                                          # dedicated sound.
                app.quit_requested = True
        elif btn == "L2" and DOWNLOAD_PLUGINS:
            if len(DOWNLOAD_PLUGINS) == 1:
                app.open_downloader(DOWNLOAD_PLUGINS[0])
            else:
                app.dl_source_index = 0
                app.screen = SCREEN_DOWNLOAD_SOURCES
        elif btn == "L":
            # v0.1.55: L/R were unmapped on the Library screen -- added as
            # a Font Size -/+ hotkey (Kaleb's request) so the setting is
            # reachable without opening the Library menu. Same logic/
            # status message as the "Font Size -/+" menu items.
            before = app.fonts.size_index
            app.fonts.smaller()
            app._page_cache_key = None
            pt = app.fonts.SIZE_STEPS[app.fonts.size_index]
            if app.fonts.size_index == before:
                app.set_status(f"Font size: {pt}pt (smallest)")
            else:
                app.set_status(f"Font size: {pt}pt")
        elif btn == "R":
            before = app.fonts.size_index
            app.fonts.bigger()
            app._page_cache_key = None
            pt = app.fonts.SIZE_STEPS[app.fonts.size_index]
            if app.fonts.size_index == before:
                app.set_status(f"Font size: {pt}pt (largest)")
            else:
                app.set_status(f"Font size: {pt}pt")
        elif btn == "START":
            # v26.07.12.05: swapped with X -- see X's handler above for
            # the full reasoning. START now pins/unpins, same one-press
            # toggle feel it always had, just moved off X.
            # v26.07.27.43: guarded to only act on an actual highlighted
            # book -- pinning doesn't mean anything for a folder row.
            book = _selected_book()
            if book:
                app.toggle_pin(book)

    elif app.screen == SCREEN_LIBRARY_MENU:
        n = len(LIBRARY_MENU_ITEMS)

        # v26.07.21.04 REAL BUG FIX (found during an audit prompted by
        # Kaleb's Settings-screen ghost-row report -- same bug class,
        # third confirmed location, this one worse than the other two:
        # this screen had NO hidden-row check at all in navigation, not
        # just an incomplete one. draw_library_menu() already hides
        # "Discover More" via `continue` when DOWNLOAD_PLUGINS is empty
        # (no jw_fetch.py/gutenberg_fetch.py bundled), but UP/DOWN was a
        # plain `% n` wrap with no skip -- the cursor could rest
        # invisibly on that row (no highlight drawn at all) whenever a
        # build ships without any downloader plugin. Never caught before
        # because Kaleb's own builds always bundle jw_fetch.py. The A
        # handler already defensively no-ops on this row (see
        # `elif choice == "Discover More" and DOWNLOAD_PLUGINS:` below),
        # so this was purely a navigation/visibility bug, not a crash
        # risk -- but the same invisible-cursor symptom Kaleb reported
        # on Settings. Mirrors draw_library_menu()'s own condition
        # exactly, same pattern as _storage_hidden()/_menu_hidden().
        def _lib_menu_hidden(idx):
            item = LIBRARY_MENU_ITEMS[idx]
            if item == "Discover More" and not DOWNLOAD_PLUGINS:
                return True
            if item == "Pinned Discoveries" and not app.download_pins:
                return True  # v26.08.06.05: same hide-if-empty rule as
                             # draw_library_menu()'s matching skip
            return False

        if btn == "UP":
            new_idx = app.lib_menu_index
            for _ in range(n):
                new_idx = (new_idx - 1) % n
                if not _lib_menu_hidden(new_idx):
                    break
            app.lib_menu_index = new_idx
            app._menu_clear_finished_armed = False
        elif btn == "DOWN":
            new_idx = app.lib_menu_index
            for _ in range(n):
                new_idx = (new_idx + 1) % n
                if not _lib_menu_hidden(new_idx):
                    break
            app.lib_menu_index = new_idx
            app._menu_clear_finished_armed = False
        elif btn == "B":
            app._menu_clear_finished_armed = False
            app.screen = SCREEN_LIBRARY
        elif btn == "A":
            choice = LIBRARY_MENU_ITEMS[app.lib_menu_index]
            if choice != "Clear All Finished":
                app._menu_clear_finished_armed = False
            if choice == "Continue Reading":
                app.open_continue_reading()
            elif choice == "Mark Finished/Unfinished":
                if app._menu_target_book:
                    app.toggle_finished(app._menu_target_book)
                    # stays open -- same reasoning as Pin/Unpin above
            elif choice == "Filter: Cycle":
                app.cycle_filter_mode()
                # stays open, same as Theme +/- -- lets Kaleb cycle
                # through All/Unfinished/Finished and see the label
                # update without re-opening the menu each time
            elif choice == "History":
                app.recents_index = 0
                app._recents_clear_armed = False
                app._recents_return_screen = SCREEN_LIBRARY_MENU
                app.screen = SCREEN_RECENTLY_PLAYED
            elif choice == "Clear All Finished":
                if len(app.finished) == 0:
                    pass  # nothing to clear -- no-op, same spirit as
                          # Delete Book's "nothing was highlighted" no-op
                elif app._menu_clear_finished_armed:
                    app.clear_all_finished()
                    app._menu_clear_finished_armed = False
                    # stays open (unlike Delete Book) -- clearing marks
                    # isn't as disruptive as removing a book file, and
                    # Kaleb may want to keep adjusting Filter right after
                    # seeing the count clear
                else:
                    app._menu_clear_finished_armed = True
            elif choice == "Edit Library...":
                # v26.08.07.15 (Kaleb's request: "the list is getting
                # longer and longer" -- New Folder, Move to Folder,
                # Delete Folder, and Delete Book moved into their own
                # submenu instead of living here directly). Just
                # navigates in, same shape as "Themes..." right below.
                app.edit_library_menu_index = 0
                app._menu_delete_armed = False
                app.screen = SCREEN_EDIT_LIBRARY_MENU
            elif choice == "Themes...":
                app.theme_menu_index = 0
                app._theme_menu_return_screen = SCREEN_LIBRARY_MENU
                app._theme_delete_armed = False  # v26.07.15.30: defensive --
                                       # every exit path already clears this,
                                       # but reset explicitly on entry too
                                       # rather than relying on that alone
                app.screen = SCREEN_THEME_MENU
                app.refresh_status_indicators()
            elif choice == "Discover More" and DOWNLOAD_PLUGINS:
                if len(DOWNLOAD_PLUGINS) == 1:
                    app.open_downloader(DOWNLOAD_PLUGINS[0])
                else:
                    app.dl_source_index = 0
                    app.screen = SCREEN_DOWNLOAD_SOURCES
            elif choice == "Pinned Discoveries" and app.download_pins:
                # v26.08.06.05 (Kaleb's request: pin/favorite feature
                # in the downloader screens). Same reset shape as
                # Discover More just above.
                app.download_pinned_index = 0
                app.screen = SCREEN_DOWNLOAD_PINNED
            elif choice == "Settings":
                app.storage_index = 0
                app._storage_confirm_idx = None
                app._storage_return_screen = SCREEN_LIBRARY_MENU
                app.refresh_storage_stats()
                app.screen = SCREEN_STORAGE
            elif choice == "Back":
                app.screen = SCREEN_LIBRARY

    elif app.screen == SCREEN_EDIT_LIBRARY_MENU:
        # v26.08.07.15 (Kaleb's request: "the list is getting longer
        # and longer... move the move, edit delete and new and nest
        # them in a new sub menu called Edit Library"). New Folder/
        # Move to Folder/Delete Folder/Delete Book -- same four
        # actions that used to dispatch directly from SCREEN_LIBRARY_
        # MENU, UNCHANGED in behavior, only where they're reached
        # from changed. SCREEN_LIBRARY_DELETE_FOLDER's and SCREEN_
        # LIBRARY_MOVE_FOLDER's own B-handlers were updated to return
        # HERE instead of straight to SCREEN_LIBRARY_MENU (see those
        # two screens further down), and New Folder's open_text_
        # entry() return_screen argument likewise now points here, so
        # cancelling out of typing a folder name -- or finishing it --
        # lands back in this submenu rather than skipping past it to
        # the parent menu.
        n = len(EDIT_LIBRARY_MENU_ITEMS)
        if btn == "UP":
            app.edit_library_menu_index = (app.edit_library_menu_index - 1) % n
            app._menu_delete_armed = False
        elif btn == "DOWN":
            app.edit_library_menu_index = (app.edit_library_menu_index + 1) % n
            app._menu_delete_armed = False
        elif btn == "B":
            app._menu_delete_armed = False
            app.screen = SCREEN_LIBRARY_MENU
        elif btn == "A":
            choice = EDIT_LIBRARY_MENU_ITEMS[app.edit_library_menu_index]
            if choice != "Delete Book":
                app._menu_delete_armed = False
            if choice == "Move to Folder":
                # v26.07.28.10 (Kaleb's request: multi-select). A batch
                # selection is enough to proceed even if nothing happens
                # to be highlighted right now (e.g. the cursor drifted
                # onto a folder row after selecting some books) --
                # _menu_target_book alone is still required for the
                # single-book fallback path, unchanged.
                if app.lib_selected or app._menu_target_book is not None:
                    app.lib_move_folder_index = 0
                    app.screen = SCREEN_LIBRARY_MOVE_FOLDER
                # else: nothing selected and nothing was highlighted --
                # no-op, same as before
            elif choice == "Delete Book":
                if app._menu_target_book is None:
                    pass  # nothing was highlighted when START was pressed
                elif app._menu_delete_armed:
                    book = app._menu_target_book
                    title = book["title"]
                    if app.delete_book(book):
                        app.refresh_library()  # also purges this book's
                                                # image cache, anchor cache,
                                                # and pin/finished entries
                                                # -- see delete_book()
                        # v26.07.28.11 BUG FIX (Kaleb's request, bug-check
                        # follow-up): same class of bug as Delete Folder's
                        # own v26.07.28.05 fix -- this clamped against
                        # len(app.books) alone, ignoring subfolder rows
                        # that can also be showing (Folders filter). Not
                        # a crash, but the cursor could jump much further
                        # back than actually necessary after deleting a
                        # book while subfolders were also on screen.
                        app.lib_index = max(0, min(app.lib_index,
                                                    len(app.lib_subfolders) + len(app.books) - 1))
                        app.set_status(f'Deleted "{title}"')
                    else:
                        app.set_status(f'Could not delete "{title}"')
                    app._menu_delete_armed = False
                    app._menu_target_book = None
                    app.screen = SCREEN_LIBRARY
                else:
                    # first press -- arm it, same two-press-confirm safety
                    # the old Library-screen SELECT delete used
                    app._menu_delete_armed = True
            elif choice == "New Folder":
                # v26.07.23.07 (Kaleb's request): simple text-entry ->
                # os.makedirs. Auto-capitalizes each word as you type
                # (see SCREEN_TEXT_ENTRY's char-append handler) so a
                # typical folder name reads naturally without a shift
                # key. Sanitized the same way category-download
                # folders already are (sanitize_folder_name(), reusing
                # jw_fetch.py's shared utility) so a typed name can
                # never contain a character FAT32/exFAT would reject.
                #
                # v26.07.27.43 (Kaleb's request: create INSIDE the
                # folder currently being browsed, not always at the
                # Library root -- part of the real folder-navigation
                # feature). Explicitly re-applies the library view
                # after creating so the new (sub)folder shows up
                # immediately as a navigable row, without needing to
                # leave and re-enter.
                def _on_new_folder_confirm(app, value):
                    name = (value or "").strip()
                    if not name:
                        app.set_status("Folder name can't be empty")
                        return
                    sanitizer = getattr(MEDIA_PLUGIN, "sanitize_folder_name", None)
                    safe_name = sanitizer(name) if sanitizer else name
                    # v26.07.28.03 BUG FIX (Kaleb's request, bug-check
                    # follow-up): lib_current_folder is preserved across
                    # filter switches, but it must only be used to place
                    # a new folder while Folders is the active filter --
                    # otherwise the folder gets created somewhere with
                    # no breadcrumb/subfolder row on screen to show it,
                    # which reads as "nothing happened".
                    _new_folder_scope = app.lib_current_folder if app.lib_filter_mode == "folders" else ""
                    parent_dir = (os.path.join(LIBRARY_DIR, _new_folder_scope)
                                  if _new_folder_scope else LIBRARY_DIR)
                    target = os.path.join(parent_dir, safe_name)
                    already_existed = os.path.isdir(target)
                    try:
                        os.makedirs(target, exist_ok=True)
                        # v26.07.23.08 BUG FIX (found during folder-
                        # management audit): exist_ok=True makes this a
                        # silent no-op when the folder was already
                        # there (e.g. typing a name that title-cases to
                        # the same result as an existing folder) -- but
                        # the message always said "Created" regardless,
                        # even when nothing was actually created.
                        if already_existed:
                            app.set_status(f'"{safe_name}" already exists')
                        else:
                            app.set_status(f'Created folder "{safe_name}"')
                            app._apply_library_view()
                    except OSError as e:
                        app.set_status(f"Couldn't create folder: {e}")
                app.open_text_entry("New Folder Name", "", _on_new_folder_confirm,
                                     SCREEN_EDIT_LIBRARY_MENU,
                                     hint="e.g. My Own Folder", autocap=True)
            elif choice == "Delete Folder":
                app.lib_delete_folder_index = 0
                app._menu_delete_folder_armed = False
                app.screen = SCREEN_LIBRARY_DELETE_FOLDER
            elif choice == "Back":
                app.screen = SCREEN_LIBRARY_MENU

    elif app.screen == SCREEN_LIBRARY_DELETE_FOLDER:
        # v26.07.23.07 (Kaleb's request): same two-press-confirm safety
        # as "Delete Book". Deliberately only allows deleting a folder
        # that's genuinely empty (checked live right here, not cached --
        # a folder could gain a book between opening this screen and
        # pressing A) to avoid silently destroying downloaded/personal
        # books. A non-empty folder just gets a clear status message
        # instead of being force-deleted -- "keep it simple" per
        # Kaleb's own framing of this feature, no bulk-move-books flow.
        #
        # v26.07.28.03 BUG FIX (Kaleb's request, bug-check follow-up):
        # gated on Filter == "folders" too -- see the matching comment
        # on the draw-side computation of this same value, right above
        # draw_library_delete_folder()'s picker loop.
        _delete_folder_scope = app.lib_current_folder if app.lib_filter_mode == "folders" else ""
        _delete_folder_base = (os.path.join(LIBRARY_DIR, _delete_folder_scope)
                                if _delete_folder_scope else LIBRARY_DIR)
        folders = list_library_folders(_delete_folder_base)
        n = len(folders)
        if btn == "UP":
            app.lib_delete_folder_index = (app.lib_delete_folder_index - 1) % n if n else 0
            app._menu_delete_folder_armed = False
        elif btn == "DOWN":
            app.lib_delete_folder_index = (app.lib_delete_folder_index + 1) % n if n else 0
            app._menu_delete_folder_armed = False
        elif btn == "B":
            app._menu_delete_folder_armed = False
            app.screen = SCREEN_EDIT_LIBRARY_MENU
        elif btn == "A" and n:
            name = folders[app.lib_delete_folder_index]
            folder_path = os.path.join(_delete_folder_base, name)
            if app._menu_delete_folder_armed:
                try:
                    contents = os.listdir(folder_path)
                    if contents:
                        # v26.07.28.17 (Kaleb's request: make this clear
                        # to understand). Used to always say "move or
                        # delete its books first" even when the folder
                        # had no books at all -- just an empty subfolder
                        # sitting inside it, confirmed as a real case by
                        # direct test. Classifies what's ACTUALLY in
                        # there (direct children only, matching what
                        # os.listdir() and this whole check already look
                        # at -- doesn't need to recurse further since
                        # the message only needs to name what's one
                        # level down) so the message matches reality
                        # either way.
                        has_books = any(c.lower().endswith(".epub") for c in contents)
                        has_subfolders = any(os.path.isdir(os.path.join(folder_path, c)) for c in contents)
                        if has_books and has_subfolders:
                            detail = "move or delete its books and subfolders first"
                        elif has_books:
                            detail = "move or delete its books first"
                        elif has_subfolders:
                            detail = "clear out its subfolder(s) first"
                        else:
                            detail = "clear out its contents first"  # non-epub files
                        app.set_status(f'"{name}" isn\'t empty -- {detail}')
                    else:
                        os.rmdir(folder_path)
                        app.set_status(f'Deleted folder "{name}"')
                        app.lib_delete_folder_index = max(
                            0, min(app.lib_delete_folder_index,
                                   len(list_library_folders(_delete_folder_base)) - 1))
                        app._apply_library_view()
                        # v26.07.28.05 BUG FIX (Kaleb's request, bug-check
                        # follow-up): the picker's OWN index just above
                        # was already clamped, but the underlying Library
                        # screen's app.lib_index (subfolder+book combined
                        # index) never was -- deleting a folder can shrink
                        # that list too (one fewer subfolder row), and B
                        # from here only returns to the Library Menu, not
                        # straight to Library, so this was never caught
                        # by Delete Book's own clamp (a different code
                        # path). Not a crash (draw_library()/handle_button()
                        # both tolerate an out-of-range index and self-heal
                        # on the next D-pad press), but the highlight could
                        # sit invisibly on a row that no longer exists
                        # until then -- same symptom class as the
                        # `_lib_menu_hidden` ghost-row bugs elsewhere in
                        # this file, just via a different trigger.
                        n_sub_after = len(app.lib_subfolders)
                        total_after = n_sub_after + len(app.books)
                        app.lib_index = max(0, min(app.lib_index, total_after - 1))
                except OSError as e:
                    app.set_status(f"Couldn't delete folder: {e}")
                app._menu_delete_folder_armed = False
            else:
                app._menu_delete_folder_armed = True

    elif app.screen == SCREEN_LIBRARY_MOVE_FOLDER:
        # v26.07.27.44 (Kaleb's request: "Move to Folder"). No armed/
        # confirm state -- moving isn't destructive (nothing is lost),
        # same reasoning New Folder gets a single press. Lists every
        # folder at every depth (list_all_library_folders()) plus an
        # explicit "(Library Root)" option at index 0.
        options = ["(Library Root)"] + list_all_library_folders()
        n = len(options)
        if btn == "UP":
            app.lib_move_folder_index = (app.lib_move_folder_index - 1) % n if n else 0
        elif btn == "DOWN":
            app.lib_move_folder_index = (app.lib_move_folder_index + 1) % n if n else 0
        elif btn == "B":
            app.screen = SCREEN_EDIT_LIBRARY_MENU
        elif btn == "A" and n and (app.lib_selected or app._menu_target_book):
            dest_folder = "" if app.lib_move_folder_index == 0 else options[app.lib_move_folder_index]
            dest_label = "Library Root" if not dest_folder else dest_folder
            if app.lib_selected:
                # v26.07.28.10 (Kaleb's request: multi-select). Resolve
                # via app._all_books (the full unfiltered scan), not
                # app.books (whatever's currently filtered/scoped) --
                # selection is cleared on every folder/filter change
                # (see self.lib_selected's own docstring) so in practice
                # these should always already be a subset of app.books
                # too, but resolving against the full scan is the more
                # robust source of truth and costs nothing extra.
                by_relpath = {b["relpath"]: b for b in app._all_books}
                moved, failed = [], []
                succeeded_relpaths = []
                for relpath in list(app.lib_selected):
                    book = by_relpath.get(relpath)
                    if book is None:
                        continue  # shouldn't happen, but don't crash a whole batch over one stale entry
                    ok, result = app.move_book(book, dest_folder)
                    if ok:
                        moved.append((book["title"], result))
                        # v26.07.28.22: result IS the NEW relpath on
                        # success -- move_book() ALREADY migrated this
                        # book's entry in self.lib_selected internally
                        # (old relpath -> new, see its own v26.07.28.11
                        # fix), so discarding by the OLD `relpath` below
                        # would be a no-op (it's already gone, replaced
                        # by `result`) and leave the new one stranded in
                        # the selection after a supposedly-cleared
                        # successful move -- confirmed by direct test.
                        succeeded_relpaths.append(result)
                    else:
                        failed.append((book["title"], result))
                app.refresh_library()
                # v26.07.28.22 BUG FIX (Kaleb's request: re-audit heavily-
                # touched areas). This used to clear() the WHOLE
                # selection regardless of outcome -- a book that failed
                # to move (e.g. a name collision at the destination)
                # lost its selection right along with the ones that
                # actually succeeded, so retrying just the failed book
                # with a different destination meant re-selecting it
                # from scratch. Only successfully-moved relpaths are
                # discarded now; a failed book stays selected.
                for _rp in succeeded_relpaths:
                    app.lib_selected.discard(_rp)
                app.lib_index = max(0, min(app.lib_index, len(app.lib_subfolders) + len(app.books) - 1))
                app.screen = SCREEN_LIBRARY
                # v26.07.28.10: honest partial-failure reporting rather
                # than a blanket "Moved N books" that hides a collision
                # -- same "tell the truth about what happened" standard
                # delete_book()/move_book() itself already holds to.
                if not failed:
                    app.set_status(f"Moved {len(moved)} book{'s' if len(moved) != 1 else ''} to {dest_label}")
                elif not moved:
                    app.set_status(f"Couldn't move any books: {failed[0][1]}")
                else:
                    app.set_status(f"Moved {len(moved)}, {len(failed)} failed "
                                    f"(\"{failed[0][0]}\": {failed[0][1]})")
            else:
                book = app._menu_target_book
                title = book["title"]
                ok, result = app.move_book(book, dest_folder)
                if ok:
                    app.refresh_library()
                    app.set_status(f'Moved "{title}" to {dest_label}')
                    app._menu_target_book = None
                    app.lib_index = max(0, min(app.lib_index, len(app.lib_subfolders) + len(app.books) - 1))
                    app.screen = SCREEN_LIBRARY
                else:
                    app.set_status(f"Couldn't move: {result}")

    elif app.screen == SCREEN_THEME_MENU:
        n = len(THEME_MENU_ITEMS)
        if btn == "UP":
            app.theme_menu_index = (app.theme_menu_index - 1) % n
            app._theme_delete_armed = False
        elif btn == "DOWN":
            app.theme_menu_index = (app.theme_menu_index + 1) % n
            app._theme_delete_armed = False
        elif btn == "B":
            app._theme_delete_armed = False
            app.screen = app._theme_menu_return_screen
        elif btn == "A":
            choice = THEME_MENU_ITEMS[app.theme_menu_index]
            if choice != "Delete Theme":
                app._theme_delete_armed = False
            if choice == "Select Theme...":
                app._theme_select_prev_index = THEME_INDEX
                app.theme_select_index = THEME_INDEX
                app.screen = SCREEN_THEME_SELECT
            elif choice == "Theme +":
                themes = all_themes()
                new_index = (THEME_INDEX + 1) % len(themes)
                apply_theme(new_index)
                save_settings({"theme_index": new_index})
                app._page_cache_key = None
                # v26.07.28.20 (Kaleb's request: cycling clarity -- an
                # unsaved Regenerate Theme draft used to cycle through
                # Theme +/- exactly like a real permanent saved theme,
                # with nothing distinguishing it, indefinitely, until
                # explicitly saved or escaped via Select Theme. Labeled
                # here instead of auto-clearing on cycle-past (Kaleb's
                # own choice between the two) -- same suffix convention
                # draw_theme_select()'s list already uses for "(custom)".
                _label = themes[new_index]['name']
                if _DRAFT_THEME is not None and new_index == len(themes) - 1:
                    _label += " (unsaved)"
                app.set_status(f"Theme: {_label}")
            elif choice == "Theme -":
                themes = all_themes()
                new_index = (THEME_INDEX - 1) % len(themes)
                apply_theme(new_index)
                save_settings({"theme_index": new_index})
                app._page_cache_key = None
                # v26.07.28.20: same "(unsaved)" label as Theme + above.
                _label = themes[new_index]['name']
                if _DRAFT_THEME is not None and new_index == len(themes) - 1:
                    _label += " (unsaved)"
                app.set_status(f"Theme: {_label}")
            elif choice == "Reset to Default":
                apply_theme(0)
                save_settings({"theme_index": 0})
                app._page_cache_key = None
                app.set_status(f"Theme: {THEMES[0]['name']}")
            elif choice == "Randomize Theme":
                app.randomize_theme(SCREEN_THEME_MENU)
            elif choice == "Regenerate Theme":
                app.regenerate_theme(SCREEN_THEME_MENU)
            elif choice == "Save Regenerated Theme":
                app.save_regenerated_theme(SCREEN_THEME_MENU)
            elif choice == "Rename Theme":
                app.rename_theme(SCREEN_THEME_MENU)
            elif choice == "Delete Theme":
                # Same two-press confirm pattern as Delete Book/Clear All
                # Finished -- destructive, so a single accidental A press
                # can't lose a saved theme.
                if app._theme_delete_armed:
                    app._theme_delete_armed = False
                    app.delete_theme()
                else:
                    local_idx = THEME_INDEX - len(THEMES)
                    if 0 <= local_idx < len(CUSTOM_THEMES):
                        app._theme_delete_armed = True
                    else:
                        app.set_status("Cycle to one of your saved themes first (Theme +/-)")
            elif choice == "Back":
                app.screen = app._theme_menu_return_screen

    elif app.screen == SCREEN_VIDEO_SETTINGS:
        n = len(VIDEO_SETTINGS_ITEMS)
        if btn == "UP":
            app.video_settings_index = (app.video_settings_index - 1) % n
        elif btn == "DOWN":
            app.video_settings_index = (app.video_settings_index + 1) % n
        elif btn == "B":
            app.screen = SCREEN_MENU
            app.refresh_status_indicators()
        elif btn == "A":
            choice = VIDEO_SETTINGS_ITEMS[app.video_settings_index]
            if choice == "Fill Screen":
                app.video_fill_screen = not app.video_fill_screen
                save_settings({"video_fill_screen": app.video_fill_screen})
                # stays open, same pattern as Theme +/- above
            elif choice == "Streaming Quality":
                _idx = STREAM_QUALITY_CYCLE.index(app.video_stream_quality) \
                    if app.video_stream_quality in STREAM_QUALITY_CYCLE else 1
                app.video_stream_quality = STREAM_QUALITY_CYCLE[(_idx + 1) % len(STREAM_QUALITY_CYCLE)]
                save_settings({"video_stream_quality": app.video_stream_quality})
                # stays open, same pattern as Theme +/- above
            elif choice == "Video Player":
                _cycle = {"mpv": "ffplay", "ffplay": "mpv"}
                app.video_player_pref = _cycle.get(app.video_player_pref, "ffplay")
                save_settings({"video_player_pref": app.video_player_pref})
                # stays open, same pattern as Theme +/- above
            elif choice == "Back":
                app.screen = SCREEN_MENU
                app.refresh_status_indicators()

    elif app.screen == SCREEN_LISTEN_AUDIO_VARIANT:
        # v26.08.06.22 (generalized from SCREEN_LISTEN_SONGBOOK_CHOICE):
        # entirely data-driven off app._pending_variant_choices -- the
        # (key, label) pairs stashed by _start_listen_to_book() when it
        # called the current plugin's get_audio_variants() capability
        # hook. No plugin-specific attribute access anywhere here.
        choices = app._pending_variant_choices
        n = len(choices)
        if n == 0:
            app.screen = SCREEN_READER
        elif btn == "UP":
            app.audio_variant_index = (app.audio_variant_index - 1) % n
        elif btn == "DOWN":
            app.audio_variant_index = (app.audio_variant_index + 1) % n
        elif btn == "B":
            app._pending_variant_filename = None
            app.screen = SCREEN_READER
        elif btn == "A":
            filename = app._pending_variant_filename
            key, _label = choices[app.audio_variant_index]
            app._pending_variant_filename = None
            if filename:
                app.open_listen_to_book(filename, audio_variant=key)
            else:
                app.screen = SCREEN_READER

    elif app.screen == SCREEN_THEME_SELECT:
        themes = all_themes()
        n = len(themes)
        if btn == "UP":
            app.theme_select_index = (app.theme_select_index - 1) % n
            apply_theme(app.theme_select_index)  # live preview as you move
            app._page_cache_key = None
        elif btn == "DOWN":
            app.theme_select_index = (app.theme_select_index + 1) % n
            apply_theme(app.theme_select_index)
            app._page_cache_key = None
        elif btn == "B":
            # Cancel -- revert to whatever was active before this screen
            # opened, same "preview live, revert on cancel" contract as
            # Randomize/Regenerate's own draft mechanism.
            apply_theme(app._theme_select_prev_index)
            save_settings({"theme_index": THEME_INDEX})
            app._page_cache_key = None
            app.screen = SCREEN_THEME_MENU
        elif btn == "A":
            # Confirm -- already applied live by UP/DOWN above, just persist.
            # v26.07.28.19 BUG FIX (Kaleb's request: bug-check on the
            # Theme menu). _DRAFT_THEME/_DRAFT_REPLACE_NAME (Regenerate
            # Theme's pending-preview state) were never cleared by
            # picking a DIFFERENT theme here -- confirmed reachable: an
            # abandoned regenerate draft (left pending by pressing B out
            # of the Theme Menu, or just navigating to Select Theme
            # instead of finishing it) would silently keep being what
            # the NEXT "Regenerate Theme" press re-rolled, regardless of
            # which theme is actually showing as current, since
            # regenerate_theme()'s own "already pending" check only
            # looks at _DRAFT_REPLACE_NAME being non-None, not at
            # whether THEME_INDEX still agrees with it. Confirming a
            # DIFFERENT theme here is an unambiguous "I'm done with
            # that draft" signal -- global draft state is invalidated
            # unless the person is re-confirming the draft slot itself
            # (reachable by scrolling to it in this same picker), in
            # which case it's still the same theme they were already
            # regenerating and nothing should be lost.
            draft_idx = len(themes) - 1 if _DRAFT_THEME is not None else -1
            if app.theme_select_index != draft_idx:
                _DRAFT_THEME = None
                _DRAFT_REPLACE_NAME = None
            save_settings({"theme_index": THEME_INDEX})
            app.set_status(f"Theme: {themes[app.theme_select_index]['name']}")
            app.screen = SCREEN_THEME_MENU

    elif app.screen == SCREEN_DOWNLOAD_SOURCES:
        # v26.08.06.14 (Kaleb's request: pin a preferred source to the
        # top of this list): uses the SAME _sorted_download_plugins()
        # the draw call uses -- see that function's own docstring for
        # why both MUST agree on ordering.
        plugins = _sorted_download_plugins(app)
        n = len(plugins)
        if btn == "UP": app.dl_source_index = (app.dl_source_index - 1) % n if n else 0
        elif btn == "DOWN": app.dl_source_index = (app.dl_source_index + 1) % n if n else 0
        elif btn == "B": app.screen = SCREEN_LIBRARY
        elif btn == "A" and plugins:
            app.open_downloader(plugins[app.dl_source_index])
        elif btn == "START" and plugins:
            # v26.08.06.14: toggles the CURRENTLY HIGHLIGHTED plugin's
            # pin state. Re-selects it by NAME after the list re-sorts
            # (not by the old numeric index) so the cursor stays on
            # the same plugin the person just pinned/unpinned instead
            # of jumping to whatever now occupies that row number --
            # pinning moves rows around, so the index alone would
            # silently point at a DIFFERENT plugin the very next frame.
            chosen = plugins[app.dl_source_index]
            chosen_name = getattr(chosen, "PLUGIN_NAME", None)
            if chosen_name in app.pinned_plugin_names:
                app.pinned_plugin_names.remove(chosen_name)
                app.set_status(f'Unpinned "{chosen_name}"')
            else:
                app.pinned_plugin_names.append(chosen_name)
                app.set_status(f'Pinned "{chosen_name}"')
            save_pinned_plugins(app.pinned_plugin_names)
            new_order = _sorted_download_plugins(app)
            app.dl_source_index = next((i for i, p in enumerate(new_order) if p is chosen), 0)
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_SOURCES
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_PINNED:
        entries = list(app.download_pins.items())
        n = len(entries)
        if btn == "UP":
            app.download_pinned_index = (app.download_pinned_index - 1) % n if n else 0
            _note_scroll_activity(app, SCREEN_DOWNLOAD_PINNED)
        elif btn == "DOWN":
            app.download_pinned_index = (app.download_pinned_index + 1) % n if n else 0
            _note_scroll_activity(app, SCREEN_DOWNLOAD_PINNED)
        elif btn == "B":
            app.screen = SCREEN_LIBRARY_MENU
        elif btn == "A" and entries:
            key, entry = entries[app.download_pinned_index]
            app.open_pinned_download_item(entry)
        elif btn == "X" and entries:
            # v26.08.06.13 (Kaleb's request: "make sure the categories
            # pages all have pop up menus similar to JW.py with the
            # font controls and exit options"): X used to unpin
            # DIRECTLY here, the only picker screen in the whole app
            # where X didn't open the shared Font Size/Library/Exit
            # App popup every other screen (SOURCES, CATEGORIES,
            # MAIN, VIDEO_SOURCES, AUDIO_SOURCES, etc.) already has.
            # Now opens that SAME SCREEN_DOWNLOAD_QUICK_MENU, with
            # "Unpin" added as an item inside it (see
            # _download_quick_menu_items()'s own new branch) --
            # matches exactly how the Browse screen's own Pin/Unpin
            # already lives INSIDE its quick menu rather than as a
            # direct X binding.
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_PINNED
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_MAIN:
        n = len(DOWNLOAD_MAIN_ITEMS)
        if btn == "UP": app.dl_main_index = (app.dl_main_index - 1) % n
        elif btn == "DOWN": app.dl_main_index = (app.dl_main_index + 1) % n
        elif btn == "B":
            if len(DOWNLOAD_PLUGINS) > 1:
                app.screen = SCREEN_DOWNLOAD_SOURCES
            else:
                app.screen = SCREEN_LIBRARY
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_MAIN
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif btn == "A":
            choice = DOWNLOAD_MAIN_ITEMS[app.dl_main_index]
            if choice == "Publications":
                app.dl_cat_index = 0
                app.dl_category = None
                app.screen = SCREEN_DOWNLOAD_CATEGORIES
            elif choice == "Video":
                app.video_source_index = 0
                app.screen = SCREEN_DOWNLOAD_VIDEO_SOURCES
            elif choice == "Audio":
                app.audio_source_index = 0
                app._pending_audio_source = None
                app.screen = SCREEN_DOWNLOAD_AUDIO_SOURCES
            else:  # "Back"
                if len(DOWNLOAD_PLUGINS) > 1:
                    app.screen = SCREEN_DOWNLOAD_SOURCES
                else:
                    app.screen = SCREEN_LIBRARY
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_CATEGORIES:
        if getattr(app.dl_plugin, "TREE_CATEGORIES", False):
            _handle_download_categories_tree_button(app, btn)
            return
        categories = _visible_categories(app.dl_plugin)
        n = len(categories)
        if btn == "UP": app.dl_cat_index = (app.dl_cat_index - 1) % n if n else 0; _note_scroll_activity(app, SCREEN_DOWNLOAD_CATEGORIES)
        elif btn == "DOWN": app.dl_cat_index = (app.dl_cat_index + 1) % n if n else 0; _note_scroll_activity(app, SCREEN_DOWNLOAD_CATEGORIES)
        elif btn == "RIGHT" and n:
            # v0.1.88: jump ~10 items at a time -- Kaleb's request, since
            # some plugins' CATEGORIES lists (JW back-issue categories,
            # Gutenberg's 17-entry picker) are long enough that one-at-a-
            # time UP/DOWN got tedious once these became full scrollable
            # lists instead of the old paged browsing.
            #
            # v26.07.23.32 (Kaleb's request: "make those L1 R1 font
            # size... the 6th screen we should modify jump 10 items
            # with the left and right d pad... and make the l and r
            # font"): moved from the L/R shoulder buttons to the D-pad's
            # own LEFT/RIGHT (confirmed genuinely free here, this
            # screen never used them) so L/R can join the other five
            # download-flow screens' font_size_hotkey() convention
            # instead, all six now consistent.
            app.dl_cat_index = min(app.dl_cat_index + 10, n - 1)
        elif btn == "LEFT" and n:
            app.dl_cat_index = max(app.dl_cat_index - 10, 0)
        elif btn == "Y" and getattr(app.dl_plugin, "SUPPORTS_SEARCH", False):
            # v26.07.09.11: Search used to only be reachable AFTER opening
            # some category first (SCREEN_DOWNLOAD_BROWSE's own Y handler)
            # -- forcing an extra, pointless hop through a category just to
            # search. Added here too so it's available from the very first
            # JW/Gutenberg screen. dl_category is still None at this point
            # (nothing chosen yet), so this is a plugin-wide search, same
            # as searching with no category ever mattered to start_search().
            def _on_cat_search_confirm(app, value):
                app.screen = SCREEN_DOWNLOAD_BROWSE
                app.start_search(value)
            label = getattr(app.dl_plugin, "PLUGIN_NAME", "")
            app.open_text_entry(f"Search {label}", "",
                                 _on_cat_search_confirm, SCREEN_DOWNLOAD_CATEGORIES,
                                 hint="Search by title or author  (case-insensitive)")
        elif btn == "SELECT" and getattr(app.dl_plugin, "SUPPORTS_MANUAL_CODE", False):
            # v26.07.09.11: same reasoning as the Y handler just above --
            # Manual Code was Browse-only before, forcing an unnecessary
            # category hop first. Mirrors SCREEN_DOWNLOAD_BROWSE's SELECT
            # handler exactly.
            def _on_cat_code_validate(app, value):
                parts = value.strip().split()
                code = parts[0] if parts else ""
                issue = parts[1] if len(parts) > 1 else None
                item, err = app.dl_plugin.lookup_pub_code(code, issue)
                if item:
                    app.dl_items = [item]
                    app.dl_query = value
                    app.dl_page = 1
                    app.dl_has_next = False
                    app.dl_load_error = None
                    app.dl_offline_local = False  # clear stale offline banner
                    app.dl_index = 0
                    app.te_checking = False
                    app.screen = SCREEN_DOWNLOAD_BROWSE
                else:
                    app.te_checking = False
                    app.te_error = err or "Not found"
                app.dirty = True
            app.open_text_entry("Pub code (+ issue YYYYMM if needed)", "",
                                 None, SCREEN_DOWNLOAD_CATEGORIES, on_validate=_on_cat_code_validate,
                                 hint=getattr(app.dl_plugin, "MANUAL_CODE_HINT", ""))
        elif btn == "B":
            # v26.07.09.10: incognito-style search token -- leaving the
            # plugin entirely (not just backing out of a sub-screen
            # that stays inside it) forgets any cached OmniSearch
            # bearer token, so the NEXT visit fetches fresh rather than
            # silently reusing one from a prior, unrelated session in
            # this plugin. getattr-gated: older jw_fetch.py builds
            # without clear_search_token_cache() just skip this, same
            # graceful-degradation convention as every other optional
            # jw_fetch.py feature check in this file.
            clear_fn = getattr(app.dl_plugin, "clear_search_token_cache", None)
            if clear_fn:
                clear_fn()
            if _plugin_has_media_split(app.dl_plugin):
                # v26.08.03.08: reached via the new Publications entry
                # on SCREEN_DOWNLOAD_MAIN -- back goes there, not
                # straight out to Sources/Library.
                app.screen = SCREEN_DOWNLOAD_MAIN
            elif len(DOWNLOAD_PLUGINS) > 1:
                app.screen = SCREEN_DOWNLOAD_SOURCES
            else:
                app.screen = SCREEN_LIBRARY
        elif btn == "A" and categories:
            # v0.1.110: jw_fetch.CATEGORY_VIDEOS is a pseudo-category (like
            # CATEGORY_WHATS_NEW) that doesn't route through
            # open_category()/list_items() -- it opens the small video-
            # source picker instead (Enjoy Life Forever / JW Broadcasting /
            # Governing Body Updates / The Good News According to Jesus),
            # replacing what used to be four separate Library Menu entries.
            chosen = categories[app.dl_cat_index]
            if chosen == getattr(app.dl_plugin, "CATEGORY_VIDEOS", None):
                app.video_source_index = 0
                app.screen = SCREEN_DOWNLOAD_VIDEO_SOURCES
            elif chosen == getattr(app.dl_plugin, "CATEGORY_AUDIO", None):
                # v26.07.10.01: same pseudo-category pattern as
                # CATEGORY_VIDEOS just above.
                app.audio_source_index = 0
                app._pending_audio_source = None
                app.screen = SCREEN_DOWNLOAD_AUDIO_SOURCES
            elif chosen == getattr(app.dl_plugin, "CATEGORY_DOWNLOADED", None):
                # v26.08.07.18: same pseudo-category pattern as
                # CATEGORY_VIDEOS/CATEGORY_AUDIO above -- LibriVox's
                # "Downloaded Audiobooks" entry, intercepted here
                # before open_category() would ever call list_items()
                # with it (that module has no filesystem access of its
                # own -- see CATEGORY_DOWNLOADED's own comment there).
                app.open_downloaded_audiobooks()
            else:
                app.open_category(chosen)
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_CATEGORIES
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_VIDEO_SOURCES:
        n = len(VIDEO_SOURCE_ITEMS)
        if btn == "UP": app.video_source_index = (app.video_source_index - 1) % n; _note_scroll_activity(app, SCREEN_DOWNLOAD_VIDEO_SOURCES)
        elif btn == "DOWN": app.video_source_index = (app.video_source_index + 1) % n; _note_scroll_activity(app, SCREEN_DOWNLOAD_VIDEO_SOURCES)
        elif btn == "B":
            # v26.08.03.08: reached via SCREEN_DOWNLOAD_MAIN's own Video
            # entry for a split plugin -- back goes there. Non-split
            # plugins never go through SCREEN_DOWNLOAD_MAIN (this screen
            # is only reachable for them via the old CATEGORY_VIDEOS
            # pseudo-category still left in their unfiltered list), so
            # back still needs to land on Categories for that path.
            app.screen = SCREEN_DOWNLOAD_MAIN if _plugin_has_media_split(app.dl_plugin) \
                else SCREEN_DOWNLOAD_CATEGORIES
        elif btn == "A":
            choice = VIDEO_SOURCE_ITEMS[app.video_source_index]
            source = VIDEO_SOURCE_BY_LABEL.get(choice)
            if source and source.get("search"):
                def _on_video_search_validate(app, value):
                    query = (value or "").strip()
                    if not query:
                        app.te_checking = False
                        app.te_error = "Type something to search for"
                        app.dirty = True
                        return
                    try:
                        results, err = MEDIA_PLUGIN.search_media(query, filter="videos")
                    except Exception as e:
                        results, err = [], str(e)
                    items = [it for it in (results or []) if it.get("_kind") == "video"]
                    if err or not items:
                        app.te_checking = False
                        app.te_error = err or f'No videos found for "{query}"'
                        app.dirty = True
                        return
                    app.dl_plugin = MEDIA_PLUGIN
                    app.dl_is_video = True
                    app._current_video_source = None  # search results are
                                                        # never one stable
                                                        # category to file
                                                        # downloads under
                    app.dl_category = None
                    app._dl_video_all_items = items
                    app.dl_items = items
                    app.dl_index = 0
                    app.dl_page = 1
                    app.dl_query = query
                    app.dl_has_next = False
                    app.dl_load_error = None
                    app.dl_offline_local = False  # clear stale offline banner
                    app.te_checking = False
                    app.screen = SCREEN_DOWNLOAD_BROWSE
                    app.dirty = True
                app.open_text_entry("Search JW Videos", "", None,
                                     SCREEN_DOWNLOAD_VIDEO_SOURCES,
                                     on_validate=_on_video_search_validate,
                                     hint='e.g. "faith", "family life", "Jeremiah"')
            elif source and source.get("subcategories"):
                app.open_video_series_source(source)
            elif source and source.get("downloaded"):
                # v26.08.07.18: see jw_fetch.py's own "Downloaded" marker
                # entry comment and open_downloaded_media()'s docstring.
                app.open_downloaded_media(is_video=True)
            elif source:
                app._pending_video_source = None
                app._current_video_source = source  # v26.07.23.03: used for
                                                       # the ROMS/movies
                                                       # subfolder name and
                                                       # offline fallback
                app.open_plugin_video_list(source["loader"], **source.get("args", {}))
            else:
                # choice == "Back", or (defensive) an unrecognized label --
                # either way, there's nothing to open.
                app.screen = SCREEN_DOWNLOAD_MAIN if _plugin_has_media_split(app.dl_plugin) \
                    else SCREEN_DOWNLOAD_CATEGORIES
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_VIDEO_SOURCES
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_VIDEO_SERIES:
        # v26.07.15.09: sub-picker for VIDEO_SOURCES entries marked
        # "subcategories" (currently just "Series") -- only reachable via
        # one of those, so app._pending_video_source is always set here.
        # Choosing an entry normally merges its own "key"/"label" into
        # the parent source's "loader"/"args" (list_mediator_category
        # (key, title)), exactly like the Bible-book picker merges
        # booknum in.
        #
        # v26.07.15.15: a subcategory entry MAY instead carry its own
        # "loader" (and optional "args") to fully override the parent's
        # -- needed when a specific entry has real behavior beyond a
        # plain category fetch (e.g. Series > "The Good News According
        # to Jesus" uses list_good_news_items(), which re-sorts by
        # episode number instead of the generic newest-first date sort,
        # since these episodes weren't published in narrative order --
        # see that function's own v26.07.09.14 bug-fix comment). Generic
        # mechanism, not JW-specific: any future plugin's subcategory
        # can do the same by adding "loader"/"args" to its own entry.
        source = app._pending_video_source
        n = len(app.dl_items)
        if btn == "UP": app.dl_index = (app.dl_index - 1) % n if n else 0
        elif btn == "DOWN": app.dl_index = (app.dl_index + 1) % n if n else 0
        elif btn == "B": app.screen = SCREEN_DOWNLOAD_VIDEO_SOURCES
        elif btn == "A" and n:
            sub = app.dl_items[app.dl_index]
            app._current_video_source = sub  # v26.07.23.03: leaf entry is
                                               # the folder name, not the
                                               # parent "Series" source
            if "loader" in sub:
                app.open_plugin_video_list(sub["loader"], **sub.get("args", {}))
            else:
                args = dict(source.get("args", {}))
                args["key"] = sub["key"]
                args["title"] = sub["label"]
                app.open_plugin_video_list(source["loader"], **args)
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_VIDEO_SERIES
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_AUDIO_SOURCES:
        # v26.07.10.01/.02: same shape as SCREEN_DOWNLOAD_VIDEO_SOURCES
        # just above -- "search" special-case now included (v26.07.10.02:
        # Search Audio, mirroring Search Videos exactly) alongside the
        # "books" special-case: a source marked "books": True (Bible
        # Reading Audio) opens the Bible-book sub-picker instead of
        # calling its loader directly -- the loader/args are still
        # exactly what gets called once a book is chosen there, just
        # with booknum added in.
        n = len(AUDIO_SOURCE_ITEMS)
        if btn == "UP": app.audio_source_index = (app.audio_source_index - 1) % n; _note_scroll_activity(app, SCREEN_DOWNLOAD_AUDIO_SOURCES)
        elif btn == "DOWN": app.audio_source_index = (app.audio_source_index + 1) % n; _note_scroll_activity(app, SCREEN_DOWNLOAD_AUDIO_SOURCES)
        elif btn == "B":
            # v26.08.03.08: same reasoning as SCREEN_DOWNLOAD_VIDEO_
            # SOURCES' own B-handler just above.
            app.screen = SCREEN_DOWNLOAD_MAIN if _plugin_has_media_split(app.dl_plugin) \
                else SCREEN_DOWNLOAD_CATEGORIES
        elif btn == "A":
            choice = AUDIO_SOURCE_ITEMS[app.audio_source_index]
            source = AUDIO_SOURCE_BY_LABEL.get(choice)
            if source and source.get("search"):
                # v26.07.10.02: mirrors the video "Search Videos" handler
                # exactly -- search_media(filter="audio"), keep only
                # _kind=="audio" hits (unresolved, _raw_lank only --
                # resolved lazily at download time in start_download()'s
                # audio branch, same as video).
                def _on_audio_search_validate(app, value):
                    query = (value or "").strip()
                    if not query:
                        app.te_checking = False
                        app.te_error = "Type something to search for"
                        app.dirty = True
                        return
                    try:
                        results, err = MEDIA_PLUGIN.search_media(query, filter="audio")
                    except Exception as e:
                        results, err = [], str(e)
                    items = [it for it in (results or []) if it.get("_kind") == "audio"]
                    if err or not items:
                        app.te_checking = False
                        app.te_error = err or f'No audio found for "{query}"'
                        app.dirty = True
                        return
                    app.dl_plugin = MEDIA_PLUGIN
                    app.dl_is_audio = True
                    app._pending_audio_source = None
                    app._pending_audio_group_source = None  # v26.07.30.16:
                                          # Search Audio is reached
                                          # directly from SCREEN_DOWNLOAD_
                                          # AUDIO_SOURCES, not through the
                                          # group screen -- explicit
                                          # clear so a STALE value from an
                                          # earlier Music/Publications
                                          # visit this session can't
                                          # misroute B-back afterward.
                    app._audio_pub_return_category = None
                    app._current_audio_group_label = None  # v26.07.30.22:
                                          # same reasoning as
                                          # _pending_audio_group_source
                                          # above -- Search Audio has no
                                          # group, downloads go straight
                                          # under .../<PLUGIN_NAME>/ with
                                          # no Music/Publications level.
                    app._current_audio_source = None  # search results are
                                                        # never a music_category
                    app.dl_category = None
                    app.dl_items = items
                    app.dl_index = 0
                    app.dl_page = 1
                    app.dl_query = query
                    app.dl_has_next = False
                    app.dl_load_error = None
                    app.dl_offline_local = False  # clear stale offline banner
                    app.te_checking = False
                    app.screen = SCREEN_DOWNLOAD_BROWSE
                    app.dirty = True
                app.open_text_entry("Search Audio", "", None,
                                     SCREEN_DOWNLOAD_AUDIO_SOURCES,
                                     on_validate=_on_audio_search_validate,
                                     hint='e.g. "love", "faith", "psalm"')
            elif source and source.get("subcategories"):
                # v26.07.30.16: new -- "Music"/"Publications" both have
                # this now (AUDIO_SOURCES didn't support subcategories
                # at all before this session; mirrors the video "Series"
                # handling below exactly).
                app.open_audio_group_source(source)
            elif source and source.get("downloaded"):
                # v26.08.07.18: see jw_fetch.py's own "Downloaded" marker
                # entry comment and open_downloaded_media()'s docstring.
                app.open_downloaded_media(is_video=False)
            elif source and source.get("books"):
                app.open_audio_book_picker(source)
            elif source:
                app._pending_audio_source = None
                app._current_audio_source = source  # v26.07.23.01: remembered
                                                       # for the "Download All"
                                                       # menu-item check (see
                                                       # _download_browse_menu_items())
                app.open_plugin_audio_list(source["loader"], **source.get("args", {}))
            else:
                # choice == "Back"
                app.screen = SCREEN_DOWNLOAD_MAIN if _plugin_has_media_split(app.dl_plugin) \
                    else SCREEN_DOWNLOAD_CATEGORIES
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_AUDIO_SOURCES
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_AUDIO_GROUP:
        # v26.07.30.16: sub-picker for AUDIO_SOURCES entries marked
        # "subcategories" ("Music"/"Publications") -- only reachable via
        # one of those, so app._pending_audio_group_source is always set
        # here. Mirrors SCREEN_DOWNLOAD_VIDEO_SERIES's handler closely,
        # plus a NEW "pub_category" branch (video's Series entries never
        # needed this -- it's specific to browsing STATIC_PUBLICATIONS
        # for their audiobook versions).
        source = app._pending_audio_group_source
        n = len(app.dl_items)
        if btn == "UP": app.dl_index = (app.dl_index - 1) % n if n else 0
        elif btn == "DOWN": app.dl_index = (app.dl_index + 1) % n if n else 0
        elif btn == "B": app.screen = SCREEN_DOWNLOAD_AUDIO_SOURCES
        elif btn == "A" and n:
            sub = app.dl_items[app.dl_index]
            # v26.07.30.22: every leaf reached from here belongs to
            # THIS group ("Music" or "Publications") -- set once,
            # applies to all three branches below (pub_category,
            # books, direct loader). _category_dest_dir() uses this
            # for the new nested folder structure.
            app._current_audio_group_label = source["label"]
            if sub.get("pub_category"):
                # v26.07.30.16: "Books"/"Brochures and Booklets"/"Tracts"
                # under Publications -- browse that category's real
                # STATIC_PUBLICATIONS catalog (jw_fetch.list_items(),
                # same data the EPUB Library uses) in audio-lookup mode.
                app._pending_audio_source = sub  # so SCREEN_DOWNLOAD_
                                                   # BROWSE's B-handler
                                                   # knows to come back
                                                   # here, same "was a
                                                   # sub-picker opened
                                                   # first" signal the
                                                   # books/subcategory
                                                   # branches already use
                app._current_audio_source = None  # no single stable
                                                     # folder name at
                                                     # this level -- each
                                                     # DOWNLOADED item
                                                     # gets its own
                                                     # title-named folder
                                                     # once actually
                                                     # selected, set at
                                                     # that point instead
                app.open_audio_pub_category(sub["pub_category"])
            elif sub.get("issues"):
                # v26.07.30.28: Watchtower Study/Meeting Workbook audio
                # -- browse the full back-issue list instead of only
                # ever fetching the current issue.
                app._current_audio_source = sub
                app.open_audio_issue_picker(sub)
            elif sub.get("books"):
                app.open_audio_book_picker(sub)
            else:
                app._pending_audio_source = None
                app._current_audio_source = sub
                app.open_plugin_audio_list(sub["loader"], **sub.get("args", {}))
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_AUDIO_GROUP
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_AUDIO_BOOKS:
        # v26.07.10.01: Bible-book sub-picker -- only reachable via a
        # "books": True AUDIO_SOURCES entry, so app._pending_audio_source
        # is always set here. Choosing a book adds its booknum to that
        # source's own args and calls its loader exactly like any other
        # audio source would.
        #
        # v26.07.30.16 BUG FIX: "Bible Reading Audio (NWT)" moved one
        # level deeper this session (now under Publications, not a
        # top-level AUDIO_SOURCES entry) -- B used to go straight to
        # SCREEN_DOWNLOAD_AUDIO_SOURCES unconditionally, which would now
        # skip past SCREEN_DOWNLOAD_AUDIO_GROUP entirely (wrong screen,
        # and would strand app._pending_audio_group_source stale). Since
        # NO top-level AUDIO_SOURCES entry has "books": True anymore --
        # only nested ones do -- this screen is now ALWAYS reached via
        # the group picker, so B always returns there.
        n = len(app.dl_items)
        if btn == "UP": app.dl_index = (app.dl_index - 1) % n if n else 0
        elif btn == "DOWN": app.dl_index = (app.dl_index + 1) % n if n else 0
        elif btn == "B":
            # v26.08.07.22 REAL BUG FIX (Kaleb's question: "check to
            # see if this keeps persisting" -- traced to the SAME root
            # cause as v26.08.07.21's four fixes: the v26.08.06.17-.20
            # dl_items/dl_index unification updated forward navigation
            # but missed this backward path too. This is the SAME bug
            # ONE LEVEL UP from the Audio Issues fix already made --
            # confirmed live: B from a Watchtower Study issue list
            # showed 214 leftover issues relabeled as the group screen
            # instead of the real 14-entry group list.
            # open_audio_group_source() rebuilds dl_items from
            # _pending_audio_group_source["subcategories"] directly --
            # no network call, static config, same fix shape as v26.
            # 08.07.21's other three.
            app.open_audio_group_source(app._pending_audio_group_source)
        elif btn == "A" and n:
            entry = app.dl_items[app.dl_index]
            booknum, name = entry["_booknum"], entry["title"]
            source = app._pending_audio_source
            if source:
                args = dict(source.get("args", {}))
                args["booknum"] = booknum
                app.open_plugin_audio_list(source["loader"], **args)
                # v26.07.30.24: set AFTER the call, not before -- open_
                # plugin_audio_list() resets this to None by default
                # (see its own docstring), same override pattern as
                # _audio_pub_return_category. Gives this book its own
                # subfolder -- see the __init__ comment on
                # _current_audio_book_label for the filename-collision
                # bug this fixes.
                app._current_audio_book_label = name
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_AUDIO_BOOKS
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_AUDIO_ISSUES:
        # v26.07.30.28: back-issue picker for AUDIO_SOURCES entries
        # marked "issues": True (Watchtower Study/Public Watchtower/
        # Awake!/Meeting Workbook audio) -- only reachable via one of
        # those, so app._pending_audio_source is always set here.
        # Mirrors SCREEN_DOWNLOAD_AUDIO_BOOKS closely; the list itself
        # (app.dl_items, v26.08.06.20) was already fetched async by
        # open_audio_issue_picker() before this screen was shown, not
        # a fixed constant like BIBLE_BOOKS.
        n = len(app.dl_items)
        if btn == "UP": app.dl_index = (app.dl_index - 1) % n if n else 0
        elif btn == "DOWN": app.dl_index = (app.dl_index + 1) % n if n else 0
        elif btn == "B":
            # v26.08.07.22 REAL BUG FIX: same fix as SCREEN_DOWNLOAD_
            # AUDIO_BOOKS' own B-handler just above -- confirmed live
            # (the exact case that surfaced this: B from a Watchtower
            # Study issue list showed 214 leftover issues relabeled as
            # the group screen instead of the real 14-entry group
            # list). See that branch's own comment for the full story.
            app.open_audio_group_source(app._pending_audio_group_source)
        elif btn == "A" and n:
            entry = app.dl_items[app.dl_index]
            issue = entry["_issue"]
            source = app._pending_audio_source
            if source:
                args = dict(source.get("args", {}))
                args["issue"] = issue
                app.open_plugin_audio_list(source["loader"], **args)
                # v26.07.30.28: set AFTER the call (same override
                # pattern as the book/pub-category trackers) -- the
                # issue is already known here (the user just picked
                # it), no need to wait on the background thread the
                # way the RSS-resolved "This Week" case originally did.
                app._current_audio_issue_label = issue
        elif btn == "X":
            app.dl_quick_menu_return_screen = SCREEN_DOWNLOAD_AUDIO_ISSUES
            app.download_quick_menu_index = 0
            app.screen = SCREEN_DOWNLOAD_QUICK_MENU
            app.refresh_status_indicators()
        elif app.font_size_hotkey(btn):
            pass

    elif app.screen == SCREEN_DOWNLOAD_BROWSE:
        n = len(app.dl_items)
        if btn == "UP":
            app.dl_index = (app.dl_index - 1) % n if n else 0
            _note_scroll_activity(app, SCREEN_DOWNLOAD_BROWSE)
        elif btn == "DOWN":
            app.dl_index = (app.dl_index + 1) % n if n else 0
            _note_scroll_activity(app, SCREEN_DOWNLOAD_BROWSE)
        elif btn == "R":
            # v0.1.88: R already meant "next page" when the plugin paginates
            # server-side (has_next=True). Some lists -- e.g. a JW back-
            # issue category, or a Gutenberg category -- come back as one
            # single page with no next/prev at all, so R used to just do
            # nothing there even though the list itself can be 20-30+ items.
            # Falls back to a local ~10-item jump in that case, so the same
            # button always does something useful on every list screen.
            if app.dl_has_next:
                app.dl_next_page()
            elif n:
                app.dl_index = min(app.dl_index + 10, n - 1)
        elif btn == "L":
            if app.dl_page > 1:
                app.dl_prev_page()
            elif n:
                app.dl_index = max(app.dl_index - 10, 0)
        elif btn == "Y" and app.dl_is_video:
            # v0.1.110: none of the four video sources have server-side
            # search -- each is fetched as one small complete list -- so
            # this is a client-side title filter over the already-loaded
            # catalog. See App.search_video_items().
            app.open_video_search_entry()
        elif btn == "Y" and not app.dl_is_video and not app.dl_is_audio and (
                getattr(app.dl_plugin, "SUPPORTS_SEARCH", False)
                or getattr(app.dl_plugin, "SUPPORTS_CATEGORIES", False)):
            # v0.1.157 BUG FIX (Kaleb's follow-up question: "when does
            # category topic search even get used?"): this used to be
            # TWO separate elif branches -- one for SUPPORTS_SEARCH, one
            # for SUPPORTS_CATEGORIES -- both calling the exact same
            # app.start_search(value), which already threads
            # self.dl_category through regardless of which branch opened
            # the box. Since elif only checks the first match, a plugin
            # declaring BOTH flags (gutenberg_fetch.py does) always hit
            # the SUPPORTS_SEARCH branch, silently shadowing the
            # SUPPORTS_CATEGORIES one -- same shadowing pattern as the
            # Y/SELECT bug just fixed above, except this one was
            # cosmetic rather than functional: confirmed via direct
            # simulation that searching inside Gutenberg's "Adventure"
            # category already correctly stayed scoped to Adventure
            # either way (dl_category isn't affected by which branch
            # fired), but the prompt shown was the generic "Search
            # Project Gutenberg" instead of the more specific "Search
            # Adventure" -- misleading about what the search would
            # actually be scoped to. Now a single branch: label is
            # "Search {category}" whenever a category is currently
            # open (regardless of which flag(s) got it there), else
            # "Search {plugin name}" -- matching what start_search()
            # actually does either way.
            app.open_category_search_entry()
        elif btn == "SELECT" and not app.dl_is_video and not app.dl_is_audio and getattr(app.dl_plugin, "SUPPORTS_MANUAL_CODE", False):
            # v0.1.156 BUG FIX (Kaleb's report, follow-up to the Help
            # screen): this used to be bound to Y, in an elif chain AFTER
            # the SUPPORTS_CATEGORIES branch above. jw_fetch.py declares
            # BOTH SUPPORTS_CATEGORIES=True and SUPPORTS_MANUAL_CODE=True,
            # and elif only ever checks the first matching branch -- so
            # for the actual live MEDIA_PLUGIN config, this code was
            # completely unreachable: Y always hit the category-search
            # branch above instead. Confirmed directly: simulated
            # pressing Y on a real category ("Books & Brochures") landed
            # on "Search Books & Brochures", never the code-entry screen,
            # even though the hint bar text (built separately, see
            # draw_download_browse()) claimed "Y Enter Code" for exactly
            # this situation -- the hint text and the real Y behavior had
            # drifted out of sync. Moved to its own button (SELECT, free
            # on this screen) so category search and manual code entry
            # are BOTH reachable rather than one silently shadowing the
            # other.
            app.open_pub_code_entry()
        elif btn == "B":
            if app._downloaded_media_category is not None:
                # v26.08.07.20 (Kaleb's follow-up: "does the download
                # list have the categories of the folders?"). Checked
                # FIRST, same reasoning as _listen_to_book_active just
                # below -- none of the other B-branches here know about
                # this two-level breadcrumb, so without this check B
                # would fall all the way through to SCREEN_DOWNLOAD_
                # AUDIO_SOURCES/VIDEO_SOURCES, skipping the category
                # list entirely. Rebuilds the category list fresh from
                # disk (so a deletion made while inside this category
                # is reflected immediately) rather than caching it.
                app.open_downloaded_media(app.dl_is_video)
            elif app._downloaded_media_root is not None:
                # v26.08.07.20 BUG FIX (caught by real dispatch testing,
                # not guessed): AT the category-list level itself (not
                # yet inside a category), dl_is_video/dl_is_audio are
                # BOTH deliberately False (see open_downloaded_media()'s
                # own comment on why) -- but the generic branches below
                # use those SAME two flags to decide where B goes once
                # actually leaving this feature, so with both False
                # execution fell all the way through to the wrong
                # default (SCREEN_DOWNLOAD_SOURCES, the top-level plugin
                # picker) instead of back to Audio/Video Sources.
                # _downloaded_media_want_video (remembered from
                # open_downloaded_media()'s own argument) is what this
                # level needs instead. Cleared after use so a stray
                # leftover value can't affect some unrelated later
                # screen.
                app.screen = (SCREEN_DOWNLOAD_VIDEO_SOURCES if app._downloaded_media_want_video
                              else SCREEN_DOWNLOAD_AUDIO_SOURCES)
                app._downloaded_media_root = None
            elif app._listen_to_book_active:
                # v26.08.05.03 BUG FIX (Kaleb's question -- "does B go
                # back to the book?" -- it did not, this branch didn't
                # exist yet): checked FIRST, before any of the browse-
                # origin branches below, since none of THOSE flags get
                # set by "Listen to this Book" and the fallback chain
                # was landing on SCREEN_DOWNLOAD_AUDIO_SOURCES instead.
                app.dl_is_audio = False
                app._listen_to_book_active = False
                app.screen = SCREEN_READER
            elif app.dl_is_video:
                # v0.1.110: video browse is now opened from
                # SCREEN_DOWNLOAD_VIDEO_SOURCES (Download Books > JW >
                # Videos), not directly from the Library Menu -- so B goes
                # back there, letting Kaleb pick a different video source
                # without walking all the way back through Library Menu >
                # Download Books > JW > Videos again.
                # v26.07.15.09: if a Series sub-category was chosen first
                # (a "subcategories" source), go back to
                # SCREEN_DOWNLOAD_VIDEO_SERIES instead, mirroring the
                # audio branch just below exactly -- same reasoning,
                # picking a different series shouldn't re-open Videos
                # from scratch.
                app.dl_is_video = False
                if app._pending_video_source:
                    # v26.08.07.21 REAL BUG FIX (same sweep, video side
                    # of the exact same bug class just fixed for audio
                    # -- Music/Publications group, Bible books, and
                    # Watchtower-family issues). This used to only flip
                    # .screen to SCREEN_DOWNLOAD_VIDEO_SERIES, leaving
                    # dl_items as whatever video item list was just
                    # left (e.g. a handful of videos from inside one
                    # series) instead of the real subcategories list.
                    # open_video_series_source() rebuilds dl_items from
                    # source["subcategories"] directly -- no network
                    # call, static config, same fix shape as its three
                    # audio-side siblings.
                    app.open_video_series_source(app._pending_video_source)
                elif app._video_return_category is not None:
                    # v26.08.07.03 (Kaleb's request: preemptively close
                    # the same gap just fixed for audio -- see
                    # _audio_return_category's identical branch just
                    # below for the full reasoning). Always None for
                    # every real call today (JW video never goes
                    # through generic dl_category browsing), so this
                    # branch is currently dead code for JW -- only
                    # fires for a future category-browsed video plugin.
                    app.dl_plugin = app._video_return_plugin
                    app.open_category(app._video_return_category)
                else:
                    app.screen = SCREEN_DOWNLOAD_VIDEO_SOURCES
            elif app.dl_audio_pub_mode:
                # v26.07.30.16: browsing a Publications category
                # (Books/Brochures/Tracts) for its audio versions --
                # B goes back to the Publications/Music group picker.
                #
                # v26.08.07.23 REAL BUG FIX (Kaleb's request: "check
                # all categories in audio and video with the back
                # button" -- caught by the sweep, same bug class as
                # v26.08.07.21/.22, a further sibling those two missed
                # since this one is gated by dl_audio_pub_mode, a
                # different flag from the dl_is_audio branch those
                # fixes live in). Confirmed live: B from "Books"
                # correctly changed .screen to download_audio_group,
                # but dl_items was left as the 24-item Books
                # publication list -- selecting a row there would have
                # tried to treat a book title as one of Publications'
                # own group entries. open_audio_group_source()
                # rebuilds dl_items from _pending_audio_group_source
                # directly (static config, no network call) -- same
                # fix shape as every other instance of this bug.
                app.dl_audio_pub_mode = False
                app.open_audio_group_source(app._pending_audio_group_source)
            elif app.dl_is_audio:
                # v26.07.10.01: same idea as the video branch just above --
                # B goes back to whichever audio picker screen got you
                # here.
                #
                # v26.07.30.16 BUG FIX: this used to only distinguish
                # "Bible book chosen first" (-> SCREEN_DOWNLOAD_AUDIO_
                # BOOKS) from everything else (-> SCREEN_DOWNLOAD_AUDIO_
                # SOURCES unconditionally). Two problems once Music/
                # Publications nesting landed this session: (1) EVERY
                # audio source is now one level deeper, reached via
                # SCREEN_DOWNLOAD_AUDIO_GROUP, not straight from
                # SCREEN_DOWNLOAD_AUDIO_SOURCES -- the old unconditional
                # target would skip past the group screen entirely,
                # landing back at the very top for no reason; (2) a
                # track list reached via Publications > Books/etc. needs
                # to re-open THAT SAME publication list (open_audio_pub_
                # category()), not just flip .screen -- the list itself
                # was replaced by the track view, flipping .screen alone
                # would show a stale/empty browse. _audio_pub_return_
                # category (set only by that one path, None everywhere
                # else) disambiguates all three cases correctly.
                app.dl_is_audio = False
                if app._audio_pub_return_category:
                    app.open_audio_pub_category(app._audio_pub_return_category)
                elif app._pending_audio_source and app._pending_audio_source.get("issues"):
                    # v26.08.07.21 REAL BUG FIX (found by deliberately
                    # testing the full real B chain out of a Watchtower
                    # Study issue's track list, not just checking the
                    # screen name): this used to ONLY flip .screen to
                    # SCREEN_DOWNLOAD_AUDIO_ISSUES, same bug class as
                    # every other "flip screen without rebuilding
                    # dl_items" fix already made elsewhere in this file
                    # (see open_audio_pub_category()'s own call just
                    # above, or the video/audio B-back crash fix
                    # mentioned in this file's own AI notes) -- just
                    # never caught for this ONE specific branch until
                    # now. dl_items was left as the track list (e.g. 7
                    # chapter titles) while .screen said "issues" (a
                    # real 214-entry list) -- confirmed live: the count
                    # and titles shown were still the track list's, not
                    # a fresh issue fetch. Selecting one of those stale
                    # rows would have tried to treat a TRACK as an
                    # ISSUE, wrong shape for open_audio_issue_picker()'s
                    # "issue" argument. Fixed by actually calling
                    # open_audio_issue_picker() again (a real, if quick,
                    # re-fetch) instead of just changing the screen
                    # name -- same fix shape open_audio_pub_category()
                    # already gets on the branch right above this one.
                    app.open_audio_issue_picker(app._pending_audio_source)
                elif app._pending_audio_source:
                    # v26.08.07.21 REAL BUG FIX (same sweep, same bug
                    # class as the AUDIO_ISSUES branch just above --
                    # caught by testing the real B chain out of a Bible
                    # reading audio chapter list, not just checking the
                    # screen name). This used to only flip .screen to
                    # SCREEN_DOWNLOAD_AUDIO_BOOKS, leaving dl_items as
                    # the chapter list (e.g. 50 chapters) instead of
                    # the real 66-book Bible list -- confirmed live.
                    # open_audio_book_picker() rebuilds dl_items from
                    # BIBLE_BOOKS directly (no network call, it's a
                    # fixed constant) same as it did the first time.
                    app.open_audio_book_picker(app._pending_audio_source)
                elif app._pending_audio_group_source:
                    # v26.08.07.21 REAL BUG FIX (same sweep, same class,
                    # third instance -- Music/Publications group list).
                    # open_audio_group_source() rebuilds dl_items from
                    # source["subcategories"] directly (no network
                    # call, it's static config) -- same fix shape as
                    # the two branches just above.
                    app.open_audio_group_source(app._pending_audio_group_source)
                elif app._audio_return_category is not None:
                    # v26.08.07.01 BUG FIX (Kaleb's report: B from a
                    # LibriVox track list landed on JW's Music/
                    # Publications picker instead of the LibriVox
                    # category the book was opened from). None of the
                    # JW-specific pending vars above are set for a
                    # plugin reached via generic category browsing --
                    # restore the saved plugin/category and genuinely
                    # reopen it (open_category() re-fetches the list,
                    # same as every other real "go back" case here),
                    # instead of falling through to the JW-only default.
                    app.dl_plugin = app._audio_return_plugin
                    # v26.08.07.18: "Downloaded Audiobooks" is a
                    # pseudo-category (see librivox_fetch.CATEGORY_
                    # DOWNLOADED's own comment) -- open_category()
                    # would call list_items() over the network for it
                    # and get back nothing real. Route back to the
                    # local scan instead, same interception
                    # SCREEN_DOWNLOAD_CATEGORIES's own "A" handler does.
                    if (app._audio_return_category
                            == getattr(app._audio_return_plugin, "CATEGORY_DOWNLOADED", object())):
                        app.open_downloaded_audiobooks()
                    else:
                        app.open_category(app._audio_return_category)
                else:
                    # Search Audio results -- no group/source tracked.
                    app.screen = SCREEN_DOWNLOAD_AUDIO_SOURCES
            elif app.dl_category is not None:
                # v26.07.09.14 BUG FIX (Kaleb's report): dl_category used
                # to just persist here, unreset -- so a search started
                # from the Categories screen (either Gutenberg's main
                # search, or JW's Y/SELECT shortcuts added directly to
                # this screen in v26.07.09.11) could silently inherit
                # whatever category was last browsed, instead of
                # searching everything like the Categories screen implies
                # it should. Categories now always genuinely means "no
                # category" the moment you land on it.
                app.dl_category = None
                app.screen = SCREEN_DOWNLOAD_CATEGORIES
            elif len(DOWNLOAD_PLUGINS) > 1:
                # v26.07.09.10: see the matching comment at the
                # SCREEN_DOWNLOAD_CATEGORIES B-handler -- this is the
                # OTHER real exit point that leaves the plugin entirely
                # (the two branches above, video-sources and
                # categories, both stay inside it and must NOT clear
                # the token).
                clear_fn = getattr(app.dl_plugin, "clear_search_token_cache", None)
                if clear_fn:
                    clear_fn()
                app.screen = SCREEN_DOWNLOAD_SOURCES
            else:
                clear_fn = getattr(app.dl_plugin, "clear_search_token_cache", None)
                if clear_fn:
                    clear_fn()
                app.screen = SCREEN_LIBRARY
        elif btn == "A" and app.dl_is_video and app.dl_items:
            # v26.07.20.05: swapped from the previous session -- A now
            # streams (was SELECT), SELECT now downloads (was A). Video-
            # specific branch must come before the generic "A" branch
            # below since this is an elif chain; non-video screens still
            # hit the generic branch exactly as before.
            app.play_video_item(app.dl_index)
        elif btn == "A" and app.dl_is_audio and app.dl_items:
            # v26.07.21.36 (Kaleb's request): same A=play/SELECT=download
            # convention as video above, now extended to audio -- audio
            # used to have no playback at all, A only downloaded. Must
            # come before the generic "A" branch below, same reasoning
            # as the video branch.
            app.play_audio_item(app.dl_index)
        elif btn == "A" and app.dl_audio_pub_mode and app.dl_items:
            # v26.07.30.16: item here is a normal EPUB-shaped
            # STATIC_PUBLICATIONS entry (from open_audio_pub_category()),
            # not yet a resolved audio track -- selecting it fetches
            # THIS title's real audio tracks via list_audio_items(),
            # same generic mechanism every other AUDIO_SOURCES entry
            # already uses, just with a live-derived pub/args instead of
            # a hardcoded one.
            item = app.dl_items[app.dl_index]
            return_category = app.dl_category  # capture BEFORE
                                                  # open_plugin_audio_list
                                                  # clears dl_category
            # v26.07.30.33 (Kaleb: "what about other books and
            # brochures will that be consistent with album names?" --
            # checked live before assuming: real Books/Brochures/
            # Tracts ALL carry a stable, publication-level album tag
            # ("BOOK--Walk Courageously With God", "BROCHURE--Love
            # People--Make Disciples", or just the title for single-
            # track Tracts) -- same shape as Watchtower/NWT, not the
            # Life Stories per-track problem. Safe to mark here too.
            app._current_audio_source = {"label": item.get("title", item.get("_pub", "Audio")),
                                          "use_album_folder": True}
            app.open_plugin_audio_list("list_audio_items",
                                        pub=item["_pub"], **(item.get("_extra") or {}))
            app._audio_pub_return_category = return_category  # override
                                                  # the method's own
                                                  # default-None reset,
                                                  # AFTER the call, so
                                                  # B correctly re-opens
                                                  # this same publication
                                                  # list instead of going
                                                  # to a generic screen
            app._current_audio_pub_category_label = return_category  # v26.07.30.26:
                                                  # same synchronous
                                                  # override as the line
                                                  # above (this is
                                                  # already-known state,
                                                  # not something the
                                                  # background thread
                                                  # needs to resolve) --
                                                  # gives Books/
                                                  # Brochures and
                                                  # Booklets/Tracts its
                                                  # own folder level
                                                  # above the title.
        elif (btn == "A" and app.dl_items and not app.dl_is_video and not app.dl_is_audio
              and app.dl_items[app.dl_index].get("_local_folder")):
            # v26.08.07.20 (Kaleb's follow-up: "does the download list
            # have the categories of the folders? That would be
            # helpful"). Same shape as LibriVox's _local_book_folder
            # branch just below -- a JW category folder from open_
            # downloaded_media()'s new top level, not a live browse
            # result, so this reads the real files directly instead of
            # going anywhere near the network.
            app.open_downloaded_media_category(app.dl_items[app.dl_index]["_local_folder"])
        elif (btn == "A" and app.dl_items and not app.dl_is_video and not app.dl_is_audio
              and app.dl_items[app.dl_index].get("_local_book_folder")):
            # v26.08.07.18 (Kaleb's request: "Downloaded Audiobooks" --
            # see open_downloaded_audiobooks()'s own docstring). This
            # book came from a local folder scan, not a live LibriVox
            # search -- list_local_book_tracks() reads the real files
            # directly instead of open_plugin_audio_list()'s network-
            # loader machinery (nothing to fetch, nothing to thread).
            # Checked BEFORE the generic MULTI_FILE+SUPPORTS_STREAMING
            # branch just below, which this book item would otherwise
            # ALSO match (LIBRIVOX_PLUGIN has both flags) and try to
            # hit the network for a book that's already fully local.
            _folder = app.dl_items[app.dl_index]["_local_book_folder"]
            _book_label = app.dl_items[app.dl_index].get("title", "Audio")
            app.dl_plugin = LIBRIVOX_PLUGIN
            app.dl_is_audio = True
            app.dl_items = list_local_book_tracks(_folder)
            app.dl_index = 0
            app._current_audio_source = None
            app._current_audio_book_label = _book_label
            app._audio_return_category = LIBRIVOX_PLUGIN.CATEGORY_DOWNLOADED if LIBRIVOX_PLUGIN else None
            app._audio_return_plugin = LIBRIVOX_PLUGIN
            app.dl_offline_local = False
            app.dirty = True
        elif (btn == "A" and app.dl_items and not app.dl_is_video and not app.dl_is_audio
              and getattr(app.dl_plugin, "MULTI_FILE", False)
              and getattr(app.dl_plugin, "SUPPORTS_STREAMING", False)):
            # v26.08.06.01 (Kaleb's request: "streaming should be the
            # primary function... work just like JW audio downloader
            # and streamer works with mpv"): a LibriVox list_items()
            # entry is a whole BOOK, not yet a resolved audio track --
            # same shape problem the dl_audio_pub_mode branch above
            # already solved for JW Books/Brochures/Tracts. Reuses the
            # exact same fix: resolve this book's real tracks first
            # (list_book_tracks_for_ui(), a thin (items, err) adapter
            # over the plugin's own link()), THEN hand off to the
            # existing generic audio browse screen -- Stream (A),
            # Play All (START), Shuffle All (L2), Download (SELECT)
            # all work completely unchanged from here, no new
            # playback code needed.
            _book_label = app.dl_items[app.dl_index].get("title", "Audio")
            _book_plugin = app.dl_plugin  # v26.08.06.06 BUG FIX: capture
                                  # BEFORE the call -- open_plugin_audio_
                                  # list() reassigns self.dl_plugin, so
                                  # "app.dl_plugin" read AFTER the call
                                  # would be whatever it just got set TO
                                  # (see that method's own new `plugin`
                                  # param and docstring for the real bug
                                  # this fixes: it used to hardcode
                                  # MEDIA_PLUGIN, which is jw_fetch, not
                                  # librivox_fetch, here).
            # v26.08.07.09 REAL BUG FIX (same session, same root cause
            # as open_plugin_audio_list()'s new `listen_to_book` param):
            # this is also the multi-match "pick a book" step of
            # _start_find_audiobook() -- reached whenever Find Audiobook
            # found more than one confirmed edition/reader, so the
            # person picks one from a plain list. _listen_to_book_active
            # is already True at this point (set by _start_find_
            # audiobook() before this screen ever showed), same
            # reasoning as the single-match case just below -- captured
            # BEFORE the call for the same reason _book_plugin is
            # captured before it, and threaded through explicitly so B
            # from the resulting track list goes back to the book
            # instead of wherever plain browsing would default to.
            _was_listen_to_book = app._listen_to_book_active
            app.open_plugin_audio_list("list_book_tracks_for_ui",
                                        plugin=_book_plugin,
                                        item=app.dl_items[app.dl_index],
                                        listen_to_book=_was_listen_to_book)
            # v26.08.06.01 BUG FIX (caught via real headless simulation,
            # not just code-reading): open_plugin_audio_list() resets
            # _current_audio_book_label to None as part of its own
            # init -- must be set AFTER the call, same as the existing
            # dl_audio_pub_mode branch above does with its own labels,
            # or it's silently overwritten back to None.
            app._current_audio_book_label = _book_label
        elif btn == "A" and app.dl_items:
            app.start_download(app.dl_index)
        elif btn == "SELECT" and (app.dl_is_video or app.dl_is_audio) and app.dl_items:
            # Free to bind here: the other SELECT usage on this same
            # screen (SUPPORTS_MANUAL_CODE) is already explicitly guarded
            # with "not app.dl_is_video and not app.dl_is_audio", so
            # there's no collision either way.
            app.start_download(app.dl_index)
        elif btn == "START" and app.dl_is_video and app.dl_items:
            # v26.07.21.43 (Kaleb's request: unify the video/audio
            # queue buttons -- was START=Play All for video but
            # START=Shuffle All for audio, genuinely inconsistent).
            # START=Play All, L2=Shuffle All now for BOTH modes -- see
            # the audio branches below for the matching pair.
            app.play_video_queue_from(app.dl_index, shuffle=False)
        elif btn == "L2" and app.dl_is_video and app.dl_items:
            # v26.07.21.43: "Shuffle All" for video -- unified with
            # audio's own L2 binding below. See play_video_queue()'s
            # own docstring for why START/SELECT (not L/R) are the
            # in-playback skip controls for a video queue specifically
            # (unrelated to this button, which only applies before
            # playback starts).
            app.play_video_queue_from(0, shuffle=True)
        elif btn == "START" and app.dl_is_audio and app.dl_items:
            # v26.07.21.43 (Kaleb's request: unify the video/audio
            # queue buttons): "Play All" moved here from Y, to match
            # video's own START=Play All exactly. Y is otherwise unused
            # for audio on this screen (audio has no search binding),
            # so nothing lost by freeing it.
            app.play_audio_queue_from(app.dl_index, shuffle=False)
        elif btn == "L2" and app.dl_is_audio and app.dl_items:
            # v26.07.21.43: "Shuffle All" moved here from START, to
            # match video's own L2=Shuffle All exactly -- same reasoning
            # as the START change just above, unifying the two modes'
            # queue buttons instead of leaving them backwards from each
            # other (previously START meant "Play All" for video but
            # "Shuffle All" for audio -- the same physical button doing
            # opposite things depending on mode was a real, confusing
            # inconsistency, not a deliberate design choice).
            app.play_audio_queue_from(0, shuffle=True)
        elif btn == "X":
            # v26.07.21.42 (Kaleb's request: "drop help menu and replace
            # with pop up menu"). Was: opened SCREEN_DOWNLOAD_HELP (the
            # static Search/Pub-Code-only overlay) -- stale/incomplete
            # once this screen grew Play/Play All/Shuffle All/Download.
            # See SCREEN_DOWNLOAD_BROWSE_MENU's own comment.
            app.download_browse_menu_index = 0
            app._download_delete_armed = False  # v26.08.07.19: defensive
                                      # reset on fresh open too, belt-
                                      # and-suspenders alongside the
                                      # UP/DOWN/B resets just above.
            app.screen = SCREEN_DOWNLOAD_BROWSE_MENU
            app.refresh_status_indicators()

    elif app.screen == SCREEN_DOWNLOAD_BROWSE_MENU:
        items = _download_browse_menu_items(app)
        n = len(items)
        if btn == "UP":
            app.download_browse_menu_index = (app.download_browse_menu_index - 1) % n if n else 0
            _note_scroll_activity(app, SCREEN_DOWNLOAD_BROWSE_MENU)
            app._download_delete_armed = False  # v26.08.07.19: moving the
                                      # selection off the armed row must
                                      # disarm it -- otherwise A on a
                                      # DIFFERENT item right after could
                                      # delete without a fresh confirm.
        elif btn == "DOWN":
            app.download_browse_menu_index = (app.download_browse_menu_index + 1) % n if n else 0
            _note_scroll_activity(app, SCREEN_DOWNLOAD_BROWSE_MENU)
            app._download_delete_armed = False  # v26.08.07.19: see UP's own comment
        elif btn == "B":
            app.screen = SCREEN_DOWNLOAD_BROWSE
            app._download_delete_armed = False  # v26.08.07.19: leaving the
                                      # menu must disarm too -- reopening
                                      # it later should never start
                                      # pre-armed.
        elif btn == "A":
            choice = items[app.download_browse_menu_index] if items else None
            # Close the menu first -- every action here is screen-
            # takeover (playback) or fire-and-forget (download); the
            # two that open a text-entry box (Search/Enter Pub Code)
            # already set their own target screen internally, so
            # setting BROWSE here first is harmless for those too
            # (immediately overwritten by open_text_entry()'s own
            # screen change). v26.07.23.30: Font Size +/- and Screen
            # Scaling are toggle/adjuster items, not close-and-go
            # actions -- they need to STAY OPEN so the label updates
            # live and can be pressed again without re-opening the
            # menu each time, same "stays open" pattern Filter: Cycle
            # already uses on SCREEN_LIBRARY_MENU.
            stays_open = choice in ("Font Size +", "Font Size -", "Delete") or (
                choice is not None and choice.startswith("Fill Screen:"))
            if choice is not None and not stays_open:
                app.screen = SCREEN_DOWNLOAD_BROWSE
            if choice == "Stream":
                app.play_video_item(app.dl_index)
            elif choice == "Play":
                app.play_audio_item(app.dl_index)
            elif choice == "Download":
                app.start_download(app.dl_index)
            elif choice == "Font Size +":
                before = app.fonts.size_index
                app.fonts.bigger()
                pt = app.fonts.SIZE_STEPS[app.fonts.size_index]
                app.set_status(f"Font size: {pt}pt (largest)" if app.fonts.size_index == before
                                else f"Font size: {pt}pt")
            elif choice == "Font Size -":
                before = app.fonts.size_index
                app.fonts.smaller()
                pt = app.fonts.SIZE_STEPS[app.fonts.size_index]
                app.set_status(f"Font size: {pt}pt (smallest)" if app.fonts.size_index == before
                                else f"Font size: {pt}pt")
            elif choice is not None and choice.startswith("Fill Screen:"):
                app.video_fill_screen = not app.video_fill_screen
                save_settings({"video_fill_screen": app.video_fill_screen})
                app.set_status(f"Fill Screen: {'On' if app.video_fill_screen else 'Off'}")
            elif choice is not None and choice.startswith("Sort:"):
                app.video_sort_mode = "sequential" if app.video_sort_mode == "newest" else "newest"
                save_settings({"video_sort_mode": app.video_sort_mode})
                # v26.08.03.15: re-sort what's ALREADY loaded immediately,
                # not just future loads -- same "affects the current
                # screen right away" expectation as Fill Screen just
                # above. dl_index reset to 0 since positions no longer
                # correspond to the same items after a re-sort.
                app.dl_items = app._apply_video_sort(app.dl_items)
                if getattr(app, "_dl_video_all_items", None):
                    app._dl_video_all_items = app._apply_video_sort(app._dl_video_all_items)
                app.dl_index = 0
                state = "Newest First" if app.video_sort_mode == "newest" else "Sequential (default order)"
                app.set_status(f"Sort: {state}")
            elif choice == "Download All":
                app.start_download_all()
            elif choice == "Play All":
                if app.dl_is_video:
                    app.play_video_queue_from(app.dl_index, shuffle=False)
                else:
                    app.play_audio_queue_from(app.dl_index, shuffle=False)
            elif choice == "Shuffle All":
                if app.dl_is_video:
                    app.play_video_queue_from(0, shuffle=True)
                else:
                    app.play_audio_queue_from(0, shuffle=True)
            elif choice == "Search":
                if app.dl_is_video:
                    app.open_video_search_entry()
                else:
                    app.open_category_search_entry()
            elif choice == "Enter Pub Code":
                app.open_pub_code_entry()
            elif choice == "Delete":
                # v26.08.07.19 (Kaleb's request: "delete your downloaded
                # audiobooks, music or videos"). First press only arms
                # it (stays_open handled this above) -- see _download_
                # browse_menu_items()'s own comment for why this item
                # only ever appears for a local-only "Downloaded" item
                # in the first place.
                app._download_delete_armed = True
            elif choice == "Press A again to DELETE":
                # Second press -- actually delete. Already disarmed here
                # (not left armed for whatever the NEXT menu open shows)
                # regardless of success/failure, matching every other
                # two-press action in this app.
                app._download_delete_armed = False
                ok, msg = _delete_current_download_item(app)
                app.set_status(msg)
            elif choice in ("Pin", "Unpin"):
                # v26.08.06.05 (Kaleb's request: pin/favorite feature
                # in the downloader screens). Not added to stays_open
                # above -- unlike Font Size (an adjuster pressed
                # repeatedly) this is a one-shot toggle; closing the
                # menu and showing the "Pinned/Unpinned" status toast
                # (set inside toggle_download_pin()) is clearer
                # feedback than leaving the menu open with a
                # relabeled entry.
                if app.dl_items and 0 <= app.dl_index < len(app.dl_items):
                    app.toggle_download_pin(app.dl_items[app.dl_index])
            elif choice == "Library":
                # v26.07.24.04 (Kaleb's request: "titles should match
                # reader mode in functionality and text"): same body as
                # the reader Menu's own "Library" choice (refresh_
                # library/lib_index reset/flush_pin_finished_now), plus
                # the download-plugin-specific clear_search_token_cache()
                # cleanup SCREEN_DOWNLOAD_BROWSE's own "B" handler
                # already does when leaving the plugin entirely -- no
                # save_progress() here since there's no open book in
                # this context, unlike the reader menu's version.
                clear_fn = getattr(app.dl_plugin, "clear_search_token_cache", None)
                if clear_fn:
                    clear_fn()
                flush_pin_finished_now()
                flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
                app.refresh_library()
                app.lib_index = 0
                app.screen = SCREEN_LIBRARY
            elif choice == "Exit App":
                app.play_sound("error")  # v26.07.16.02: same exit cue as
                                          # Library's own B-to-quit path
                app.quit_requested = True
            # "Back" and any unmatched choice: already returned to
            # SCREEN_DOWNLOAD_BROWSE above, nothing further to do.

    elif app.screen == SCREEN_DOWNLOAD_QUICK_MENU:
        # v26.07.24.06 (Kaleb's follow-up: "were those pop up menus
        # supposed to have font size controls... is that still
        # there?"): Font Size +/- added, same "stays open" pattern as
        # SCREEN_DOWNLOAD_BROWSE_MENU's own handling of the identical
        # two items -- see _download_quick_menu_items()'s own docstring.
        items = _download_quick_menu_items(app)
        n = len(items)
        if btn == "UP":
            app.download_quick_menu_index = (app.download_quick_menu_index - 1) % n
            _note_scroll_activity(app, SCREEN_DOWNLOAD_QUICK_MENU)
        elif btn == "DOWN":
            app.download_quick_menu_index = (app.download_quick_menu_index + 1) % n
            _note_scroll_activity(app, SCREEN_DOWNLOAD_QUICK_MENU)
        elif btn == "B":
            app.screen = app.dl_quick_menu_return_screen
        elif btn == "A":
            choice = items[app.download_quick_menu_index]
            stays_open = choice in ("Font Size +", "Font Size -")
            if choice == "Font Size +":
                before = app.fonts.size_index
                app.fonts.bigger()
                pt = app.fonts.SIZE_STEPS[app.fonts.size_index]
                app.set_status(f"Font size: {pt}pt (largest)" if app.fonts.size_index == before
                                else f"Font size: {pt}pt")
            elif choice == "Font Size -":
                before = app.fonts.size_index
                app.fonts.smaller()
                pt = app.fonts.SIZE_STEPS[app.fonts.size_index]
                app.set_status(f"Font size: {pt}pt (smallest)" if app.fonts.size_index == before
                                else f"Font size: {pt}pt")
            elif choice == "Help":
                app.dl_help_return_screen = app.dl_quick_menu_return_screen
                app.dl_help_scroll = 0
                app.screen = SCREEN_DOWNLOAD_HELP
            elif choice == "A/V Controls Help":
                app.av_help_return_screen = app.dl_quick_menu_return_screen
                app.av_help_scroll = 0
                app.screen = SCREEN_AV_HELP
            elif choice == "Library":
                clear_fn = getattr(app.dl_plugin, "clear_search_token_cache", None)
                if clear_fn:
                    clear_fn()
                flush_pin_finished_now()
                flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
                app.refresh_library()
                app.lib_index = 0
                app.screen = SCREEN_LIBRARY
            elif choice == "Exit App":
                app.play_sound("error")
                app.quit_requested = True
            elif choice == "Unpin" and app.dl_quick_menu_return_screen == SCREEN_DOWNLOAD_PINNED:
                # v26.08.06.13: same one-shot-toggle-then-close shape as
                # the Browse screen's own Pin/Unpin item -- see that
                # handler's docstring for why it's not in stays_open
                # above (a status toast is clearer feedback than
                # leaving the menu open with nothing left to relabel).
                entries = list(app.download_pins.items())
                idx = min(app.download_pinned_index, len(entries) - 1) if entries else -1
                if idx >= 0:
                    key, entry = entries[idx]
                    app.unpin_by_key(key)
                    app.download_pinned_index = max(0, min(app.download_pinned_index,
                                                             len(app.download_pins) - 1))
                app.screen = app.dl_quick_menu_return_screen
            elif choice in ("Pin", "Unpin"):
                # v26.08.06.17 (dl_items/dl_index unification): the
                # SAME one-shot toggle _download_browse_menu_items()'s
                # "Pin"/"Unpin" already does, now reachable from a
                # sub-picker screen (Video Series first) too --
                # distinguished from the SCREEN_DOWNLOAD_PINNED-only
                # "Unpin" case above by the elif ordering (that branch
                # only matches when return_screen IS Pinned; this one
                # catches every other screen offering Pin/Unpin).
                if app.dl_items and 0 <= app.dl_index < len(app.dl_items):
                    app.toggle_download_pin(app.dl_items[app.dl_index],
                                             extra=app._current_picker_pin_extra())
                app.screen = app.dl_quick_menu_return_screen
            elif not stays_open:  # "Back"
                app.screen = app.dl_quick_menu_return_screen

    elif app.screen == SCREEN_DOWNLOAD_HELP:
        if btn == "UP":
            app.dl_help_scroll = max(0, app.dl_help_scroll - 1)
        elif btn == "DOWN":
            app.dl_help_scroll += 1  # clamped for real inside draw_download_help()
        elif btn == "L":
            # v26.07.17.16: same L/R jump-10 convention added to
            # SCREEN_LICENSES/SCREEN_HELP -- all three screens share
            # _draw_static_scroll_overlay()'s hint text, so leaving this
            # one out would make the hint bar claim L/R works here when
            # it didn't.
            app.dl_help_scroll = max(0, app.dl_help_scroll - 10)
        elif btn == "R":
            app.dl_help_scroll += 10  # clamped for real inside draw_download_help()
        elif btn == "B":
            app.screen = app.dl_help_return_screen

    elif app.screen == SCREEN_LICENSES:
        if btn == "UP":
            app.licenses_scroll = max(0, app.licenses_scroll - 1)
        elif btn == "DOWN":
            app.licenses_scroll += 1  # clamped for real inside draw_licenses()
        elif btn == "L":
            # v26.07.17.16 (Kaleb's request): L/R jump ±10, same
            # convention already used on Chapters/Bookmarks (see
            # Controls docstring at top of file) -- this screen is a
            # long static scroll (license text), same shape of problem.
            app.licenses_scroll = max(0, app.licenses_scroll - 10)
        elif btn == "R":
            app.licenses_scroll += 10  # clamped for real inside draw_licenses()
        elif btn == "B":
            app.screen = app.licenses_return_screen

    elif app.screen == SCREEN_HELP:
        if btn == "UP":
            app.help_scroll = max(0, app.help_scroll - 1)
        elif btn == "DOWN":
            app.help_scroll += 1  # clamped for real inside draw_app_help()
        elif btn == "L":
            # v26.07.17.16 (Kaleb's request): same L/R jump-10 convention
            # added to SCREEN_LICENSES above -- see that comment.
            app.help_scroll = max(0, app.help_scroll - 10)
        elif btn == "R":
            app.help_scroll += 10  # clamped for real inside draw_app_help()
        elif btn == "B":
            app.screen = app.help_return_screen

    elif app.screen == SCREEN_AV_HELP:
        if btn == "UP":
            app.av_help_scroll = max(0, app.av_help_scroll - 1)
        elif btn == "DOWN":
            app.av_help_scroll += 1  # clamped for real inside draw_av_help()
        elif btn == "L":
            app.av_help_scroll = max(0, app.av_help_scroll - 10)
        elif btn == "R":
            app.av_help_scroll += 10  # clamped for real inside draw_av_help()
        elif btn == "B":
            app.screen = app.av_help_return_screen

    elif app.screen == SCREEN_TEXT_ENTRY:
        rows = TEXT_ENTRY_GRID
        if btn == "UP":
            app.te_row = (app.te_row - 1) % len(rows)
            app.te_col = min(app.te_col, len(rows[app.te_row]) - 1)
        elif btn == "DOWN":
            app.te_row = (app.te_row + 1) % len(rows)
            app.te_col = min(app.te_col, len(rows[app.te_row]) - 1)
        elif btn == "LEFT":
            app.te_col = (app.te_col - 1) % len(rows[app.te_row])
        elif btn == "RIGHT":
            app.te_col = (app.te_col + 1) % len(rows[app.te_row])
        elif btn == "X" and not app.te_checking:
            app.te_value = app.te_value[:-1]  # quick-backspace shortcut
            app.te_error = None
        elif btn == "B" and not app.te_checking:
            app.screen = app.te_return_screen  # cancel -- neither callback is called
        elif btn == "A" and not app.te_checking:
            label, kind = rows[app.te_row][app.te_col]
            if kind == "char":
                # v26.07.23.07 (Kaleb's request: "keyboard should just
                # auto capitalize the letter of each word after a
                # space" for the New Folder feature -- explicitly
                # scoped via app.te_autocap, NOT applied globally, per
                # Kaleb's own follow-up concern that always doing this
                # could cause search-matching problems. Only New
                # Folder's open_text_entry() call passes autocap=True;
                # every other caller (Search Audio/Videos/Gutenberg,
                # pub code entry, theme naming) is completely
                # unaffected and behaves exactly as before this existed.
                if app.te_autocap and (not app.te_value or app.te_value.endswith(" ")):
                    app.te_value += label
                elif app.te_autocap:
                    app.te_value += label.lower()
                else:
                    app.te_value += label
                app.te_error = None
            elif kind == "space":
                app.te_value += " "
                app.te_error = None
            elif kind == "backspace":
                app.te_value = app.te_value[:-1]
                app.te_error = None
            elif kind == "cancel":
                app.screen = app.te_return_screen
            elif kind == "confirm":
                value = app.te_value
                if app.te_on_validate:
                    app.te_checking = True
                    app.te_checking_start = time.time()
                    app.te_error = None
                    validate_fn = app.te_on_validate
                    threading.Thread(target=lambda: validate_fn(app, value), daemon=True).start()
                else:
                    callback = app.te_on_confirm
                    app.screen = app.te_return_screen
                    if callback:
                        callback(app, value)

    elif app.screen == SCREEN_READER:
        # v26.07.13.14 BUG FIX (found while testing B/link behavior on a
        # still-building extreme page, Kaleb's request): this call used
        # to always run with renderer=None (handle_button() had no
        # renderer parameter at all) -- harmless before progressive
        # wrapping existed (the wrap was ALWAYS a single blocking call
        # either way), but _ensure_page_built()'s progressive branch
        # only activates when renderer is not None. With renderer=None
        # here, EVERY button press on a still-building extreme page
        # (not just B -- this line runs for ALL of them) silently fell
        # back to the old one-shot _wrap() and fully completed the
        # ENTIRE remaining page synchronously, right here, before the
        # button's own action even ran -- defeating the whole point of
        # chunking. Passing the real renderer through fixes it: this
        # now takes one bounded slice like every other call, same as
        # draw_reader()'s own call the same frame.
        app._ensure_page_built(renderer)
        visible_spans = app.visible_span_indices(line_h, body_rows)
        step = 10 if app.fast_scroll else 1
        if btn == "UP":
            if visible_spans and app.selected_span in visible_spans:
                pos = visible_spans.index(app.selected_span)
                if pos - step >= 0:
                    app.selected_span = visible_spans[pos - step]
                else:
                    app.scroll = max(0, app.scroll - step)
            else:
                app.scroll = max(0, app.scroll - step)
        elif btn == "DOWN":
            if visible_spans and app.selected_span in visible_spans:
                pos = visible_spans.index(app.selected_span)
                if pos + step < len(visible_spans):
                    app.selected_span = visible_spans[pos + step]
                else:
                    app.scroll = min(app.scroll + step, app._max_scroll(line_h, body_rows))
            else:
                app.scroll = min(app.scroll + step, app._max_scroll(line_h, body_rows))
        elif btn == "LEFT":
            if visible_spans and app.selected_span in visible_spans:
                pos = visible_spans.index(app.selected_span)
                if pos - 1 >= 0:
                    app.selected_span = visible_spans[pos - 1]
                else:
                    app.scroll = max(0, app.scroll - 1)
            else:
                app.scroll = max(0, app.scroll - 1)
        elif btn == "RIGHT":
            if visible_spans and app.selected_span in visible_spans:
                pos = visible_spans.index(app.selected_span)
                if pos + 1 < len(visible_spans):
                    app.selected_span = visible_spans[pos + 1]
                else:
                    app.scroll = min(app.scroll + 1, app._max_scroll(line_h, body_rows))
            else:
                app.scroll = min(app.scroll + 1, app._max_scroll(line_h, body_rows))
        elif btn == "A":
            app.follow_selected()
        elif btn == "B":
            if not app.go_back():
                app.save_progress()
                flush_pin_finished_now()  # v26.07.17.20: book-close checkpoint
                flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
                app.screen = SCREEN_LIBRARY
        elif btn == "L":
            app.page_up(line_h, body_rows)
        elif btn == "R":
            app.page_down(line_h, body_rows)
        elif btn == "L2":
            app.prev_chapter()
        elif btn == "R2":
            app.next_chapter()
        elif btn == "X":
            app.menu_index = 0
            app.screen = SCREEN_MENU
            app.refresh_status_indicators()
        elif btn == "Y":
            app.fast_scroll = not app.fast_scroll
        elif btn == "START":
            app.bookmark_here()
        elif btn == "SELECT":
            # v26.07.20.05: does the video download when the current
            # selection is a recognized JW video link -- see
            # _selected_video_link() and download_selected_link_
            # video()'s own docstring. v26.07.21.10 (Kaleb's request):
            # otherwise (the common case -- most selections aren't
            # video links), toggles Immersive Mode instead, so SELECT
            # is never a dead button in reading mode. Same clamp as the
            # Menu's own Immersive Mode toggle -- see that handler's
            # comment on why no repagination is needed, just a scroll
            # clamp to the new body_rows.
            if app._selected_video_link() is not None:
                app.download_selected_link_video()
            else:
                app.immersive_mode = not app.immersive_mode
                save_settings({"immersive_mode": app.immersive_mode})
                _line_h, _body_rows = _reader_body_layout(app.fonts, app.immersive_mode)[1:3]
                app.scroll = min(app.scroll, app._max_scroll(_line_h, _body_rows))

    elif app.screen == SCREEN_IMAGE_VIEW:
        pan_step = IMGVIEW_PAN_STEP_FRAC
        if btn == "UP":
            app._imgview_pan_by(0.0, -pan_step)
        elif btn == "DOWN":
            app._imgview_pan_by(0.0, pan_step)
        elif btn == "LEFT":
            app._imgview_pan_by(-pan_step, 0.0)
        elif btn == "RIGHT":
            app._imgview_pan_by(pan_step, 0.0)
        elif btn == "R":
            app._imgview_zoom_by(IMGVIEW_ZOOM_STEP)
            app.set_status(f"Zoom: {int(round(app._imgview_zoom * 100))}%")
        elif btn == "L":
            app._imgview_zoom_by(1.0 / IMGVIEW_ZOOM_STEP)
            app.set_status(f"Zoom: {int(round(app._imgview_zoom * 100))}%")
        elif btn == "B":
            app.screen = SCREEN_READER

    elif app.screen == SCREEN_MENU:
        n = len(MENU_ITEMS)

        def _menu_hidden(idx):
            # v26.08.07.08: now calls the shared _menu_item_hidden()
            # helper (defined next to MENU_ITEMS itself) instead of its
            # own separate inline copy of the same three checks -- see
            # that function's docstring for why this consolidation
            # happened this session.
            return _menu_item_hidden(MENU_ITEMS[idx], app)

        if btn == "UP":
            new_idx = app.menu_index
            for _ in range(n):
                new_idx = (new_idx - 1) % n
                if not _menu_hidden(new_idx):
                    break
            app.menu_index = new_idx
        elif btn == "DOWN":
            new_idx = app.menu_index
            for _ in range(n):
                new_idx = (new_idx + 1) % n
                if not _menu_hidden(new_idx):
                    break
            app.menu_index = new_idx
        elif btn == "B": app.screen = SCREEN_READER
        elif btn == "A":
            choice = MENU_ITEMS[app.menu_index]
            if choice == "Chapters":
                app.toc_flat = flatten_toc(app.doc.toc)
                app.toc_index = app._toc_index_for_current_position(app.toc_flat)
                app.screen = SCREEN_TOC
            elif choice == "Bookmarks":
                app.bookmarks_index = 0
                app._bookmark_delete_confirm_idx = None
                app.screen = SCREEN_BOOKMARKS
            elif choice == "Listen to this Book":
                _start_listen_to_book(app)
            elif choice == "Find Audiobook":
                _start_find_audiobook(app)
            elif choice == "Font Size +":
                before = app.fonts.size_index
                app.fonts.bigger()
                app._page_cache_key = None
                pt = app.fonts.SIZE_STEPS[app.fonts.size_index]
                if app.fonts.size_index == before:
                    app.set_status(f"Font size: {pt}pt (largest)")
                else:
                    app.set_status(f"Font size: {pt}pt")
            elif choice == "Font Size -":
                before = app.fonts.size_index
                app.fonts.smaller()
                app._page_cache_key = None
                pt = app.fonts.SIZE_STEPS[app.fonts.size_index]
                if app.fonts.size_index == before:
                    app.set_status(f"Font size: {pt}pt (smallest)")
                else:
                    app.set_status(f"Font size: {pt}pt")
            elif choice == "Themes...":
                app.theme_menu_index = 0
                app._theme_menu_return_screen = SCREEN_MENU
                app._theme_delete_armed = False  # v26.07.15.30: same
                                       # defensive reset as the Library
                                       # Menu's Themes... entry above
                app.screen = SCREEN_THEME_MENU
                app.refresh_status_indicators()
            elif choice == "Immersive Mode":
                app.immersive_mode = not app.immersive_mode
                save_settings({"immersive_mode": app.immersive_mode})
                # v26.07.21.09: clamp scroll to the new body_rows right
                # away -- see _reader_body_layout()'s own comment on why
                # no repagination/wrap-cache invalidation is needed,
                # this clamp is purely so the view doesn't sit one
                # interaction behind a toggle that shrinks body_rows.
                _line_h, _body_rows = _reader_body_layout(app.fonts, app.immersive_mode)[1:3]
                app.scroll = min(app.scroll, app._max_scroll(_line_h, _body_rows))
                # stays open, same as Theme +/- -- lets the label update
                # in place without re-opening the menu
            elif choice == "Fast Scroll":
                # v26.07.27.08 (Feature #2, Kaleb's request: "Always on
                # Fast Mode... default to always on when opening a book,
                # but still let me turn it off"). Cycles the PERSISTENT
                # starting default only -- open_book() reads this to
                # decide what app.fast_scroll starts at for the next
                # book opened; it does NOT touch the live fast_scroll
                # state for the book currently open (Y still does that,
                # same as always -- this setting is about what happens
                # on the NEXT book open, not right now).
                app.fast_scroll_default = "manual" if app.fast_scroll_default == "always_on" else "always_on"
                save_settings({"fast_scroll_default": app.fast_scroll_default})
                # stays open, same pattern as Immersive Mode/Sound Effects above
            elif choice == "Sound Effects":
                app.sound_enabled = not app.sound_enabled
                save_settings({"sound_enabled": app.sound_enabled})
                # stays open, same pattern as Immersive Mode above
            elif choice == "Night Mode":
                set_night_mode(not NIGHT_MODE_ENABLED)
                # stays open, same pattern as Immersive Mode above
            elif choice == "Image Dimming":
                set_image_dim_level((app.image_dim_level + 1) % len(IMAGE_DIM_LABELS), app)
                # stays open, same pattern as Immersive Mode above
            elif choice == "Video Settings" and native_media is not None:
                # Defensive native_media check even though nav-skip
                # already prevents selecting this while hidden.
                app.video_settings_index = 0
                app.screen = SCREEN_VIDEO_SETTINGS
                app.refresh_status_indicators()
            elif choice == "Library":
                app.save_progress()
                flush_pin_finished_now()  # v26.07.17.20: book-close checkpoint
                flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
                app.refresh_library()
                app.lib_index = 0
                app.screen = SCREEN_LIBRARY
            elif choice == "Settings":
                app.storage_index = 0
                app._storage_confirm_idx = None
                app._storage_return_screen = SCREEN_READER
                app.refresh_storage_stats()
                app.screen = SCREEN_STORAGE
            elif choice == "Exit App":
                # v26.07.12.20 (Kaleb's request): "Resume" was removed --
                # identical to just pressing B to close the menu, so it
                # was dead weight in the list. Exit App added in its
                # place at the bottom, mirroring Library's own
                # save_progress() call just above so reading position
                # isn't lost by exiting straight from the reader instead
                # of going through Library's B-to-quit path first.
                app.save_progress()
                flush_pin_finished_now()  # v26.07.17.20: book-close checkpoint
                flush_recents_now()  # v26.07.27.31: same checkpoint as flush_pin_finished_now()
                app.play_sound("error")  # v26.07.16.02: same exit cue
                                          # as Library's B-to-quit path
                app.quit_requested = True

    elif app.screen == SCREEN_TOC:
        n = len(app.toc_flat)
        if btn == "UP": app.toc_index = (app.toc_index - 1) % n if n else 0
        elif btn == "DOWN": app.toc_index = (app.toc_index + 1) % n if n else 0
        elif btn == "Y": app.toc_index = min(n - 1, app.toc_index + 10)
        elif btn == "L": app.toc_index = max(0, app.toc_index - 10)
        elif btn == "R": app.toc_index = min(n - 1, app.toc_index + 10)
        elif btn == "L2":
            # Jump to the previous "real" section (book/article), skipping
            # over its "<Name> Outline" companion page. This epub's TOC
            # turned out to have NO level nesting at all (every entry is
            # level 0 -- Bible books, magazine articles, everything is
            # flat), so level couldn't be used to detect section
            # boundaries. Instead: each Bible book appears as two
            # consecutive entries, "Genesis Outline" then "Genesis" --
            # skip the Outline summary pages and land only on the real
            # book/article entry, which is what gives an actual
            # "previous/next book" jump instead of just stepping through
            # every Outline+book pair one at a time.
            for i in range(app.toc_index - 1, -1, -1):
                if not app.toc_flat[i].title.endswith(" Outline"):
                    app.toc_index = i
                    break
            else:
                app.toc_index = 0
        elif btn == "R2":
            for i in range(app.toc_index + 1, n):
                if not app.toc_flat[i].title.endswith(" Outline"):
                    app.toc_index = i
                    break
            else:
                app.toc_index = n - 1
        elif btn == "B": app.screen = SCREEN_READER
        elif btn == "A" and app.toc_flat:
            entry = app.toc_flat[app.toc_index]
            if "#" in entry.href:
                f, a = entry.href.split("#", 1)
            else:
                f, a = entry.href, None
            app._scroll_stack.append(app.scroll)
            app.state.goto(f, a)
            app.scroll = 0
            app.selected_span = 0
            app._page_cache_key = None
            app.screen = SCREEN_READER
            # v26.07.10.31 BUG FIX -- really a design reversal, not a
            # logic bug (Kaleb's on-device report): v26.07.10.22 armed
            # the extreme-page-queue drain here too, treating a TOC
            # selection as equivalent to an L2/R2 chapter transition.
            # That worked exactly as designed, but Kaleb found the
            # RESULT confusing in real use: opening "Enjoy Life
            # Forever!", jumping via TOC to "Track Your Bible Reading"
            # (a cold render), closing the book and app, then reopening
            # later and jumping via TOC to the SAME page again -- it now
            # cold-rendered a DIFFERENT, unrelated large page into the
            # queue first, then finally loaded the one he actually
            # asked for, repeating on every subsequent TOC jump as the
            # queue kept advancing. Technically correct (this is the
            # extreme-page queue doing exactly what it was told), but
            # unexpected and surprising from the reader's side, since
            # nothing about picking a TOC ENTRY suggests "also go
            # prerender some other unrelated page in the background."
            # L2/R2 (main loop, above) remains the only trigger --
            # chapter-to-chapter navigation via the physical buttons is
            # a much clearer signal that proactive caching is welcome
            # than a TOC selection, which reads more like "take me to
            # exactly this one page," not "and warm up others nearby."

    elif app.screen == SCREEN_BOOKMARKS:
        bms = [b for b in get_bookmarks(app.current_book_path) if b.get("label") != "__lastpos__"]
        n = len(bms)
        if btn == "UP":
            app.bookmarks_index = (app.bookmarks_index - 1) % n if n else 0
            app._bookmark_delete_confirm_idx = None
        elif btn == "DOWN":
            app.bookmarks_index = (app.bookmarks_index + 1) % n if n else 0
            app._bookmark_delete_confirm_idx = None
        elif btn == "Y":
            app.bookmarks_index = min(max(0, n - 1), app.bookmarks_index + 10)
            app._bookmark_delete_confirm_idx = None
        elif btn == "L":
            app.bookmarks_index = max(0, app.bookmarks_index - 10)
            app._bookmark_delete_confirm_idx = None
        elif btn == "R":
            app.bookmarks_index = min(max(0, n - 1), app.bookmarks_index + 10)
            app._bookmark_delete_confirm_idx = None
        elif btn == "B":
            if app._bookmark_delete_confirm_idx is not None:
                app._bookmark_delete_confirm_idx = None  # cancel pending delete first
            else:
                app.screen = SCREEN_READER
        elif btn == "X" and bms:
            if app._bookmark_delete_confirm_idx == app.bookmarks_index:
                # second X on the same row -- actually delete
                bm = bms[app.bookmarks_index]
                delete_bookmark(app.current_book_path, bm["file"], bm.get("anchor"), bm.get("ts"))
                app._bookmark_delete_confirm_idx = None
                app.bookmarks_index = max(0, min(app.bookmarks_index, n - 2))
                app.set_status("Bookmark deleted")
            else:
                # first X -- arm this row, require a second press to confirm
                # so a stray button press can't silently delete a bookmark
                app._bookmark_delete_confirm_idx = app.bookmarks_index
        elif btn == "A" and bms:
            bm = bms[app.bookmarks_index]
            app._scroll_stack.append(app.scroll)
            app.state.goto(bm["file"], bm.get("anchor"), char_off=bm.get("char_off"))
            app.scroll = 0
            app.selected_span = 0
            app._page_cache_key = None
            app._bookmark_delete_confirm_idx = None
            app.screen = SCREEN_READER

    elif app.screen == SCREEN_RECENTLY_PLAYED:
        # v26.07.27.31 (Kaleb's request): row 0 is the synthetic "Clear
        # History" action (see draw_recently_played()'s own comment for
        # why it's a row IN the list rather than a separate popup/menu
        # entry -- Kaleb's exact phrasing was "a clear history function
        # in the list"), real entries are recents[i-1] for row >= 1.
        # Same two-press arm/confirm shape as Clear All Finished.
        recents = load_recents()
        n_rows = len(recents) + 1
        if btn == "UP":
            app.recents_index = (app.recents_index - 1) % n_rows if n_rows else 0
            app._recents_clear_armed = False
        elif btn == "DOWN":
            app.recents_index = (app.recents_index + 1) % n_rows if n_rows else 0
            app._recents_clear_armed = False
        elif btn == "LEFT" and n_rows:
            # v26.07.27.36 (Kaleb's request: "make it work like Library
            # with the same button mapping controls" -- Library uses
            # LEFT/RIGHT jump-10, clamped not wrapped, per its own
            # v0.1.110 comment; matched exactly here rather than
            # Bookmarks/Chapters' Y/L/R scheme, since Kaleb specifically
            # named Library as the one to match).
            app.recents_index = max(0, app.recents_index - 10)
            app._recents_clear_armed = False
        elif btn == "RIGHT" and n_rows:
            app.recents_index = min(n_rows - 1, app.recents_index + 10)
            app._recents_clear_armed = False
        elif btn == "B":
            if app._recents_clear_armed:
                app._recents_clear_armed = False  # cancel pending clear first
            else:
                app.screen = app._recents_return_screen
        elif btn == "A":
            if app.recents_index == 0:
                if not recents:
                    pass  # nothing to clear -- no-op, same spirit as
                          # Clear All Finished's own empty-set no-op
                elif app._recents_clear_armed:
                    app.clear_recents()
                    app._recents_clear_armed = False
                else:
                    app._recents_clear_armed = True
            else:
                app._recents_clear_armed = False
                entry = recents[app.recents_index - 1]
                app.play_recent(entry)

    elif app.screen == SCREEN_STORAGE:
        n = len(STORAGE_ACTIONS)

        def _storage_hidden(idx):
            action = STORAGE_ACTIONS[idx]
            if action == "Pre-render Book Images":
                return native_image is not None and native_image.available
            if action == "Toggle Disk Cache (RAM-only mode)":
                # v26.07.12.14: same hide-when-native-available pattern
                return native_image is not None and native_image.available
            if action == "Toggle Video Fill Screen":
                # v26.07.20.07: opposite direction from the two hides
                # above -- this one is hidden when native_media ISN'T
                # available (there's nothing to toggle without it),
                # rather than hidden when a native module IS available.
                return native_media is None
            if action == "Streaming Quality":
                return native_media is None
            if action == "Video Player":
                return native_media is None
            if action == "Audio Player":
                return native_media is None
            # v26.07.21.01 BUG FIX (Kaleb's report: invisible selected rows
            # with no highlight, and "Help" appearing to jump mid-scroll):
            # these two hides existed in draw_storage()'s `continue` checks
            # but were missing here, so UP/DOWN could land storage_index on
            # a row the draw loop then skipped entirely -- no highlight box
            # drawn at all (looks like the cursor vanished), and since the
            # scroll window is centered on storage_index while row_pos only
            # advances for rows actually drawn, the visible window shifted
            # by one row, making the next real row (often "Help") appear to
            # suddenly jump into view. Fixed by mirroring draw_storage()'s
            # conditions exactly -- same list, same order, single source of
            # truth from now on. If a new conditional hide is ever added to
            # draw_storage(), it MUST be added here too, or this bug class
            # recurs.
            if action == "Remove Ports Shortcut":
                return not os.path.exists(_ports_launcher_path())
            if action == "Reinstall Ports Shortcut":
                return not load_settings().get("ports_shortcut_opted_out")
            return False


        if btn == "UP":
            new_idx = app.storage_index
            for _ in range(n):
                new_idx = (new_idx - 1) % n
                if not _storage_hidden(new_idx):
                    break
            app.storage_index = new_idx
            app._storage_confirm_idx = None
            _note_scroll_activity(app, SCREEN_STORAGE)
        elif btn == "DOWN":
            new_idx = app.storage_index
            for _ in range(n):
                new_idx = (new_idx + 1) % n
                if not _storage_hidden(new_idx):
                    break
            app.storage_index = new_idx
            app._storage_confirm_idx = None
            _note_scroll_activity(app, SCREEN_STORAGE)
        elif btn == "B":
            if app._storage_confirm_idx is not None:
                app._storage_confirm_idx = None  # cancel pending action first
            else:
                app.screen = app._storage_return_screen
        elif btn == "A":
            action = STORAGE_ACTIONS[app.storage_index]
            if action == "Back":
                app.screen = app._storage_return_screen
            elif action == "Toggle Disk Cache (RAM-only mode)":
                # v26.07.12.14: same 3-layer defense as Pre-render Book
                # Images (hidden from the draw loop, skipped in UP/DOWN
                # navigation, and -- in case this row is ever reached some
                # other way -- refused here too, with the same
                # explanatory message pattern). Unlike Pre-render this is
                # a persistent setting, not an action: refusing here does
                # NOT touch the saved value, it just declines to flip it,
                # so save_settings() is never called and whatever's
                # already on disk (someone's genuine mini_jpeg-fallback
                # preference from another device/build) stays untouched.
                if native_image is not None and native_image.available:
                    app.set_status("Not needed -- native fast image decode is already active")
                else:
                    # Non-destructive, instant -- no confirm needed. Updates the
                    # LIVE ImageLoader (not just the setting for next launch), so
                    # it takes effect immediately without restarting.
                    app.disk_cache_enabled = not app.disk_cache_enabled
                    app.image_loader.disk_cache_enabled = app.disk_cache_enabled
                    save_settings({"disk_cache_enabled": app.disk_cache_enabled})
                    state = "ON (cached to disk)" if app.disk_cache_enabled else "OFF (RAM-only)"
                    app.set_status(f"Disk cache: {state}")
            elif action == "Toggle Images (text-only mode)":
                # Non-destructive, instant. Turning images back ON doesn't
                # need to do anything extra -- _ensure_page_built() already
                # ran, images list is still intact, draw_reader() just
                # starts calling get_image_texture() again on the next
                # frame (which re-decodes or pulls from disk cache as
                # normal). Cancel any in-flight pre-render when switching
                # to text-only, since decoding images nobody will see
                # defeats the point of the mode.
                app.images_enabled = not app.images_enabled
                if not app.images_enabled and app._prerender_active:
                    app.cancel_prerender()
                save_settings({"images_enabled": app.images_enabled})
                state = "OFF (text-only)" if not app.images_enabled else "ON"
                app.set_status(f"Images: {state}")
            elif action == "Toggle Video Fill Screen" and native_media is not None:
                # Defensive native_media check even though nav-skip
                # already prevents selecting this while hidden.
                # Non-destructive, instant -- purely a flag read at the
                # next play_video_source() call (both call sites already pass
                # app.video_fill_screen/SW/SH through every time), nothing
                # to update live since no video is playing while this
                # menu is even open.
                app.video_fill_screen = not app.video_fill_screen
                save_settings({"video_fill_screen": app.video_fill_screen})
                state = "Fill (stretch)" if app.video_fill_screen else "Fit (preserve aspect ratio)"
                app.set_status(f"Video Scaling: {state}")
            elif action == "Streaming Quality" and native_media is not None:
                # Non-destructive, instant -- same "just a flag read at
                # the next play_video_source()/resolve call" reasoning as
                # Video Fill Screen above. Downloads never read this
                # setting at all -- see play_video_item()/
                # download_selected_link_video()'s own comments for
                # exactly which call sites do and don't thread it through.
                _idx = STREAM_QUALITY_CYCLE.index(app.video_stream_quality) \
                    if app.video_stream_quality in STREAM_QUALITY_CYCLE else 1
                app.video_stream_quality = STREAM_QUALITY_CYCLE[(_idx + 1) % len(STREAM_QUALITY_CYCLE)]
                save_settings({"video_stream_quality": app.video_stream_quality})
                app.set_status(f"Streaming Quality: {app.video_stream_quality}")
            elif action == "Video Player" and native_media is not None:
                _cycle = {"mpv": "ffplay", "ffplay": "mpv"}
                app.video_player_pref = _cycle.get(app.video_player_pref, "ffplay")
                save_settings({"video_player_pref": app.video_player_pref})
                app.set_status(f"Video Player: {app.video_player_pref.capitalize()}")
            elif action == "Audio Player" and native_media is not None:
                _cycle = {"mpv": "ffplay", "ffplay": "mpv"}
                app.audio_player_pref = _cycle.get(app.audio_player_pref, "ffplay")
                save_settings({"audio_player_pref": app.audio_player_pref})
                app.set_status(f"Audio Player: {app.audio_player_pref.capitalize()}")
            elif action == "Toggle Open Last Book on Launch":
                # Non-destructive, instant -- only affects the NEXT app
                # launch (checked once at the end of App.__init__), no
                # live behavior to update right now.
                app.open_last_book_enabled = not app.open_last_book_enabled
                save_settings({"open_last_book_enabled": app.open_last_book_enabled})
                state = "ON" if app.open_last_book_enabled else "OFF"
                app.set_status(f"Open Last Book on Launch: {state}")
            elif action == "Toggle Sound Effects":
                app.sound_enabled = not app.sound_enabled
                save_settings({"sound_enabled": app.sound_enabled})
                state = "ON" if app.sound_enabled else "OFF"
                app.set_status(f"Sound Effects: {state}")
            elif action == "Cycle Image Night Dimming":
                set_image_dim_level((app.image_dim_level + 1) % len(IMAGE_DIM_LABELS), app)
                app.set_status(f"Image Night Dimming: {IMAGE_DIM_LABELS[app.image_dim_level]}")
            elif action == "Check for New Categories" and not app._checking_new_categories:
                app._checking_new_categories = True
                app.set_status("Checking for new/removed categories...", duration=20)

                def _do_check_new_categories():
                    try:
                        added, removed, err = CHECKER_PLUGIN.check_new_categories()
                    except Exception as e:
                        app._checking_new_categories = False
                        app.set_status(f"Check failed: {e}", duration=5.0)
                        app.dirty = True
                        return
                    app._checking_new_categories = False
                    # v26.08.03.06 (Kaleb's request: show last-checked
                    # status on the checker): recorded even when err is
                    # set -- a partial failure (e.g. one of the two root
                    # categories timed out) still represents a real,
                    # timestamped attempt, and the status message already
                    # says "Check failed" separately when that happens.
                    app._last_new_categories_check_ts = time.time()
                    save_settings({"last_new_categories_check_ts": app._last_new_categories_check_ts})
                    if err:
                        app.set_status(f"Check failed: {err}", duration=5.0)
                    elif added or removed:
                        # v26.08.03.05 BUG FIX: without this, the change
                        # was correctly saved to jw_fetch's VIDEO_SOURCES/
                        # AUDIO_SOURCES but wouldn't actually show up in
                        # the menu until the app was restarted -- see
                        # _rebuild_media_source_tables()'s own docstring.
                        _rebuild_media_source_tables()
                        parts = []
                        if added:
                            parts.append(f"{added} new")
                        if removed:
                            parts.append(f"{removed} removed")
                        app.set_status(
                            f'{" / ".join(parts)} categor{"y" if (added + removed) == 1 else "ies"} '
                            f'-- see "New Categories" in Music/Video menus', duration=6.0)
                    else:
                        app.set_status("No changes -- categories up to date", duration=3.0)
                    app.dirty = True

                threading.Thread(target=_do_check_new_categories, daemon=True).start()
            elif action == "Verify Curated Categories" and not app._checking_curated_categories:
                app._checking_curated_categories = True
                app.set_status("Verifying curated categories (60+ requests, may take "
                                "a minute)...", duration=90)

                def _do_check_curated_categories():
                    try:
                        dead = CHECKER_PLUGIN.check_curated_categories()
                    except Exception as e:
                        app._checking_curated_categories = False
                        app.set_status(f"Verify failed: {e}", duration=5.0)
                        app.dirty = True
                        return
                    app._checking_curated_categories = False
                    app._last_curated_categories_check_ts = time.time()
                    save_settings({"last_curated_categories_check_ts": app._last_curated_categories_check_ts})
                    if not dead:
                        app.set_status("All curated categories still live", duration=4.0)
                    else:
                        # v26.08.06.28 (same class of fix as v26.08.06.25):
                        # CHECKER_PLUGIN is capability-detected, not
                        # guaranteed to be JW.org specifically.
                        checker_name = getattr(CHECKER_PLUGIN, "PLUGIN_NAME", "this source") if CHECKER_PLUGIN else "this source"
                        names = ", ".join(label for label, _key in dead[:5])
                        more = f" (+{len(dead) - 5} more)" if len(dead) > 5 else ""
                        app.set_status(
                            f"{len(dead)} curated categor{'y' if len(dead) == 1 else 'ies'} "
                            f"appear removed by {checker_name}: {names}{more} -- review, not "
                            f"auto-changed", duration=10.0)
                    app.dirty = True

                threading.Thread(target=_do_check_curated_categories, daemon=True).start()
            elif action == "Check for New Publications" and not app._checking_new_publications:
                app._checking_new_publications = True
                # v26.08.06.28 (same class of fix as v26.08.06.25):
                # CHECKER_PLUGIN is capability-detected, not guaranteed
                # to be jw.org specifically.
                checker_name = getattr(CHECKER_PLUGIN, "PLUGIN_NAME", "this source") if CHECKER_PLUGIN else "this source"
                app.set_status(f"Checking {checker_name} library pages for new EPUBs...", duration=20)

                def _do_check_new_publications():
                    try:
                        added, err = CHECKER_PLUGIN.check_new_publications()
                    except Exception as e:
                        app._checking_new_publications = False
                        app.set_status(f"Check failed: {e}", duration=5.0)
                        app.dirty = True
                        return
                    app._checking_new_publications = False
                    app._last_new_publications_check_ts = time.time()
                    save_settings({"last_new_publications_check_ts": app._last_new_publications_check_ts})
                    if err:
                        app.set_status(f"Check failed: {err}", duration=5.0)
                    elif added:
                        app.set_status(
                            f"Found {added} new publication{'s' if added != 1 else ''} with EPUBs -- "
                            f"see Download Books > Books/Brochures/Tracts", duration=6.0)
                    else:
                        app.set_status("No new EPUB publications found", duration=3.0)
                    app.dirty = True

                threading.Thread(target=_do_check_new_publications, daemon=True).start()
            elif action == "Check Reminder":
                _cycle = {7: 14, 14: 30, 30: None, None: 7}
                app.staleness_check_days = _cycle.get(app.staleness_check_days, 7)
                save_settings({"staleness_check_days": app.staleness_check_days})
                state = f"{app.staleness_check_days} days" if app.staleness_check_days else "Manual Only"
                app.set_status(f"Check Reminder: {state}")
            elif action == "Help":
                app.help_return_screen = SCREEN_STORAGE
                app.help_scroll = 0
                app.screen = SCREEN_HELP
            elif action == "Credits / License":
                app.licenses_return_screen = SCREEN_STORAGE
                app.licenses_scroll = 0
                app.screen = SCREEN_LICENSES
            elif action == "Pre-render Book Images":
                # v0.1.82: confirmed on-device (Kaleb: "full native
                # instantaneous image rendering") that native_jpeg.py's
                # real libSDL2_image decode is fast enough that
                # pre-warming the cache ahead of time has nothing
                # meaningful left to buy -- the whole reason this feature
                # existed was to front-load mini_jpeg.py's slow decode so
                # it wasn't happening while someone was trying to read.
                # Kept as a real, working feature for the mini_jpeg
                # fallback path (a device/build without libSDL2_image
                # still benefits from it), but a no-op with an
                # explanatory message when native decode is already
                # doing the job -- avoids pointless CPU/disk-cache-write
                # work for zero real benefit on the common fast path.
                if native_image is not None and native_image.available:
                    app.set_status("Not needed -- native fast image decode is already active")
                elif app._prerender_active:
                    app.cancel_prerender()
                    app.set_status("Pre-render cancelled")
                elif app.doc is None:
                    app.set_status("Open a book first")
                else:
                    app.start_prerender()
                    app.set_status("Pre-rendering book images in the background...")
            elif action == "Backup Bookmarks Now":
                # Non-destructive, instant -- only ever ADDS a new backup
                # file, never touches live data, so no confirm needed.
                fname = backup_bookmarks()
                if fname:
                    app.set_status(f"Backed up to backups/{fname}")
                    app.refresh_storage_stats()
                else:
                    app.set_status("Nothing to back up -- no bookmarks yet")
            elif action == "Check for Files to Migrate":
                # v26.08.05.20/.21/.22 (Kaleb's requests, extended
                # twice: "when we migrated books into jw.org folder it
                # left a lot over" -- books ARE covered now; then "for
                # gutenberg we designed a feature to nest them into a
                # Gutenberg folder with the sub categories... we at
                # least need to move those epubs that are in those
                # folders" -- also covered now, plus bookmarks/pins/
                # finished/caches now travel with every moved book via
                # migrate_book_state(). See check_and_migrate_library()/
                # _scan_and_migrate_stray_books()'s own docstrings for
                # the full two-pass story. Non-destructive/instant, same
                # reasoning as Backup Bookmarks Now just above -- only
                # ever MOVES files into their correct existing-structure
                # location, so no confirm gate needed.
                result = check_and_migrate_library()
                parts = []
                if result["migrated"]:
                    parts.append(f'{result["migrated"]} file(s) migrated')
                if result["folders_cleaned"]:
                    parts.append(f'{result["folders_cleaned"]} folder(s) cleaned up')
                if result["skipped"]:
                    parts.append(f'{result["skipped"]} skipped (already existed)')
                if result.get("possible_duplicates"):
                    # v26.08.07.10 (Kaleb's report: "books migrate and
                    # duplicate"): distinct from "skipped" above --
                    # these are SAME-BOOK-different-filename matches
                    # left in place untouched rather than moved
                    # alongside an existing copy. Worded as a flag to
                    # go look, not an error -- this tool deliberately
                    # never deletes on a title match alone.
                    parts.append(f'{result["possible_duplicates"]} possible duplicate(s) '
                                 f'found and left in place for you to review')
                msg = None
                if parts:
                    msg = ", ".join(parts).capitalize()
                elif result["ambiguous"]:
                    msg = (f'Nothing safe to migrate -- {len(result["ambiguous"])} '
                           f"folder(s) found but left alone (mixed issues/books, "
                           f"can't be safely sorted)")
                else:
                    msg = "Nothing to migrate -- library already organized"
                # v26.08.06.25 (generalized -- see check_and_migrate_
                # library()'s own docstring): used to be a hardcoded
                # "(some Gutenberg books need a live lookup -- not
                # checked)" whenever a single hardcoded bool was set.
                # Now names whichever plugin(s) actually caused the
                # ambiguity, dynamically -- correct even if a future
                # THIRD network-dependent plugin (without a local
                # pub-code-style resolver) is ever added alongside
                # Gutenberg, not just a Gutenberg-shaped message that
                # would be silently wrong for that case.
                unresolved = result.get("unresolved_plugin_names") or []
                if unresolved:
                    if len(unresolved) == 1:
                        who = unresolved[0]
                    elif len(unresolved) == 2:
                        who = f"{unresolved[0]} and {unresolved[1]}"
                    else:
                        who = ", ".join(unresolved[:-1]) + f", and {unresolved[-1]}"
                    msg += f" (some {who} books need a live lookup -- not checked)"
                app.set_status(msg, duration=3.5)
                if parts:
                    app.refresh_storage_stats()
            elif action == "Backup Custom Themes Now":
                # Same non-destructive/instant reasoning as Backup
                # Bookmarks Now above.
                fname = backup_custom_themes()
                if fname:
                    app.set_status(f"Backed up to backups/{fname}")
                    app.refresh_storage_stats()
                else:
                    app.set_status("Nothing to back up -- no custom themes yet")
            elif action == "Reinstall Ports Shortcut":
                # v26.07.14.12: non-destructive, instant, same reasoning as
                # Backup Bookmarks Now above -- this only ever ADDS the
                # shortcut back (and clears the opt-out flag), never
                # touches anything a person could lose, so no confirm
                # needed even though its sibling Remove does need one.
                try:
                    _reinstall_ports_launcher()
                    app.set_status("Ports shortcut reinstalled")
                except Exception as e:
                    app.set_status(f"Couldn't reinstall Ports shortcut: {e}")
            elif app._storage_confirm_idx == app.storage_index:
                # second A on the same destructive/data-changing action --
                # actually do it
                app._storage_confirm_idx = None
                if action == "Clear Image Cache":
                    freed = clear_image_cache()
                    app.image_loader._results.clear()
                    # v26.07.09.12 BUG FIX: this used to be a bare
                    # app._image_textures.clear() -- dropped the Python
                    # dict references but never called SDL_DestroyTexture()
                    # on the entries themselves first, unlike
                    # _evict_image_textures_if_needed()'s LRU path (which
                    # always destroys before removing). A real GPU-memory
                    # leak: pressing this action repeatedly freed the RAM
                    # decode cache but not the GPU texture memory alongside it.
                    for _key, entry in app._image_textures.items():
                        SDL.SDL_DestroyTexture(entry[0])
                    app._image_textures.clear()
                    app.set_status(f"Image cache cleared -- {format_bytes(freed)} freed")
                    app.refresh_storage_stats()
                elif action == "Clear Cache for Finished Books":
                    count, freed = clear_finished_book_caches()
                    if count:
                        app.set_status(f"Cleared cache for {count} finished book(s) -- "
                                        f"{format_bytes(freed)} freed")
                        app.refresh_storage_stats()
                    else:
                        app.set_status("No cached finished books to clear")
                elif action == "Clean Up Orphaned Bookmarks":
                    removed = clean_orphaned_bookmarks()
                    if removed:
                        app.set_status(f"Removed bookmarks for {removed} deleted book(s)")
                        app.refresh_storage_stats()
                    else:
                        app.set_status("No orphaned bookmarks found")
                elif action == "Restore Latest Backup":
                    fname, books, added = restore_latest_backup()
                    if fname:
                        app.set_status(f"Restored {fname}: {added} bookmark(s) "
                                        f"across {books} book(s) merged in")
                        app.refresh_storage_stats()
                    else:
                        app.set_status("No backup found to restore")
                elif action == "Restore Custom Themes Backup":
                    # v26.07.15.23 BUG FIX: if a randomized-but-not-yet-
                    # saved draft was the currently active theme, its
                    # position in all_themes() is always LAST -- but
                    # "last" is a moving target as CUSTOM_THEMES' length
                    # changes. Blindly re-applying the pre-restore
                    # THEME_INDEX (as this used to do) could silently
                    # land on a real restored custom theme instead of
                    # the still-pending draft, if the restored list's
                    # length differs from what it was when the draft
                    # was generated. Captured BEFORE the restore call,
                    # since all_themes()'s length is about to change.
                    was_showing_draft = (_DRAFT_THEME is not None and
                                          THEME_INDEX == len(all_themes()) - 1)
                    fname = restore_latest_custom_themes_backup()
                    if fname:
                        app.set_status(f"Restored {fname} ({len(CUSTOM_THEMES)} theme(s))")
                        app.refresh_storage_stats()
                        if was_showing_draft:
                            # Draft is unaffected by the restore (it's
                            # session-only, not part of CUSTOM_THEMES)
                            # and always sits last -- re-find that spot.
                            apply_theme(len(all_themes()) - 1)
                        else:
                            # Currently showing a fixed THEMES entry (index
                            # unaffected) or a real custom slot (index may
                            # now resolve to a different theme, or be out
                            # of range) -- re-apply defensively, same
                            # "clamp handles it" pattern apply_theme()
                            # already uses everywhere else.
                            apply_theme(THEME_INDEX)
                        app._page_cache_key = None
                    else:
                        app.set_status("No backup found to restore")
                elif action == "Remove Ports Shortcut":
                    # v26.07.14.11: same fail-soft-to-a-status-message
                    # principle as every other action here -- this only
                    # ever touches one small .sh file, never anything a
                    # person would lose real data from, but a permission/
                    # read-only-filesystem error is still worth SHOWING
                    # rather than silently swallowing, unlike the
                    # self-install's own log-and-move-on version of this.
                    try:
                        if _remove_ports_launcher():
                            app.set_status("Ports shortcut removed")
                        else:
                            app.set_status("No Ports shortcut found to remove")
                    except Exception as e:
                        app.set_status(f"Couldn't remove Ports shortcut: {e}")
            elif action in ("Clear Image Cache", "Clear Cache for Finished Books",
                             "Clean Up Orphaned Bookmarks",
                             "Restore Latest Backup", "Restore Custom Themes Backup",
                             "Remove Ports Shortcut"):
                # first A on a destructive/data-changing action -- arm it,
                # require a second press to confirm
                app._storage_confirm_idx = app.storage_index


if __name__ == "__main__":
    main()
